// Seven original birthday pages, kept isolated in iframes so their CSS/JS
// cannot overwrite one another. Only the required next-page links are joined.
const BIRTHDAY_PAGES = ["<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Heart Animation</title>\n  </head>\n<body>\n\n  <main class=\"page\">\n\n    <div class=\"heart-container\">\n      <svg class=\"heart-svg\"\n           viewBox=\"0 0 1000 400\"\n           xmlns=\"http://www.w3.org/2000/svg\">\n\n        <defs>\n          <filter id=\"pinkGlow\">\n            <feGaussianBlur stdDeviation=\"5\"/>\n          </filter>\n        </defs>\n\n        <!-- Pink glow -->\n        <path\n          class=\"heart-glow\"\n          d=\"\n            M 0 205\n            C 80 225 140 175 225 190\n            C 300 205 340 215 405 205\n\n            C 375 185 365 155 380 120\n            C 395 78 435 92 445 155\n            C 455 92 495 78 510 120\n            C 525 155 500 190 445 245\n            C 435 255 410 220 405 205\n\n            C 465 180 525 185 590 205\n            C 670 230 730 175 805 190\n            C 880 205 940 185 1000 205\n          \"\n        />\n\n        <!-- Red continuous line -->\n        <path\n          class=\"heart-red\"\n          d=\"\n            M 0 205\n            C 80 225 140 175 225 190\n            C 300 205 340 215 405 205\n\n            C 375 185 365 155 380 120\n            C 395 78 435 92 445 155\n            C 455 92 495 78 510 120\n            C 525 155 500 190 445 245\n            C 435 255 410 220 405 205\n\n            C 465 180 525 185 590 205\n            C 670 230 730 175 805 190\n            C 880 205 940 185 1000 205\n          \"\n        />\n\n        <circle class=\"end-dot\" cx=\"1000\" cy=\"205\" r=\"5\"/>\n\n      </svg>\n    </div>\n\n  </main>\n\n  <script>\n      setTimeout(() => parent.postMessage({type:\"birthday-reveal-next\"}, \"*\"), 3600);\n    </script>\n</body>\n</html>\n<style>\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nhtml,\nbody {\n  width: 100%;\n  height: 100%;\n  overflow: hidden;\n}\n\nbody {\n  background: #fff0e7;\n}\n\n/* BACKGROUND */\n\n.page {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  height: 100dvh;\n\n  display: flex;\n  justify-content: center;\n  align-items: center;\n\n  background: linear-gradient(\n    180deg,\n    #fffaf5 0%,\n    #fff0e7 50%,\n    #ffeadc 100%\n  );\n\n  overflow: hidden;\n}\n\n/* PERFECT CENTER */\n\n.heart-container {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n\n  width: 140vw;\n  max-width: none;\n\n  transform: translate(-50%, -50%);\n\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.heart-svg {\n  display: block;\n  width: 100%;\n  height: auto;\n  overflow: visible;\n}\n\n/* COMMON STROKE */\n\n.heart-glow,\n.heart-red {\n  fill: none !important;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n/* PINK GLOW */\n\n.heart-glow {\n  stroke: #ff9fc9;\n  stroke-width: 17;\n  opacity: 0.75;\n\n  filter:\n    drop-shadow(0 0 7px #ffb6d5)\n    drop-shadow(0 0 15px #ff69b4);\n}\n\n/* BOLD RED LINE */\n\n.heart-red {\n  stroke: #d93636;\n  stroke-width: 6;\n}\n\n/* END DOT */\n\n.end-dot {\n  fill: #d93636;\n  opacity: 0;\n  filter: drop-shadow(0 0 5px #ff9fc9);\n}\n\n/* MOBILE */\n\n@media (max-width: 600px) {\n  .heart-container {\n    width: 140vw;\n  }\n\n  .heart-red {\n    stroke-width: 6;\n  }\n\n  .heart-glow {\n    stroke-width: 17;\n  }\n}\n</style><script>\nwindow.addEventListener(\"DOMContentLoaded\", () => {\n\n  const redLine = document.querySelector(\".heart-red\");\n  const pinkLine = document.querySelector(\".heart-glow\");\n  const endDot = document.querySelector(\".end-dot\");\n\n  if (!redLine || !pinkLine) return;\n\n  const paths = [pinkLine, redLine];\n\n  paths.forEach(path => {\n    const length = path.getTotalLength();\n\n    path.style.strokeDasharray = length;\n    path.style.strokeDashoffset = length;\n  });\n\n  if (endDot) {\n    endDot.style.opacity = \"0\";\n  }\n\n  setTimeout(() => {\n\n    paths.forEach(path => {\n      const length = path.getTotalLength();\n\n      path.animate(\n        [\n          { strokeDashoffset: length },\n          { strokeDashoffset: 0 }\n        ],\n        {\n          duration: 3000,\n          easing: \"ease-in-out\",\n          fill: \"forwards\"\n        }\n      );\n    });\n\n    setTimeout(() => {\n      if (endDot) {\n        endDot.style.transition = \"opacity 0.3s ease\";\n        endDot.style.opacity = \"1\";\n      }\n    }, 3000);\n\n  }, 300);\n\n});\n</script>", "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Birthday Surprise</title>\n  </head>\n<body>\n\n<section class=\"intro\" id=\"intro\">\n\n  <div class=\"top-text\">A LITTLE SURPRISE FOR YOU</div>\n\n  <!-- HEART -->\n  <div class=\"heart-area\" id=\"heartArea\">\n    <div class=\"heart-glow\"></div>\n\n    <svg class=\"main-heart\" id=\"mainHeart\" viewBox=\"0 0 120 110\">\n      <defs>\n        <linearGradient id=\"heartGradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n          <stop offset=\"0%\" stop-color=\"#ff9bb7\"/>\n          <stop offset=\"55%\" stop-color=\"#ff477e\"/>\n          <stop offset=\"100%\" stop-color=\"#d91650\"/>\n        </linearGradient>\n      </defs>\n\n      <path\n        d=\"M60 102 C48 90 7 62 7 33\n        C7 5 43 -5 60 23\n        C77 -5 113 5 113 33\n        C113 62 72 90 60 102Z\"\n        fill=\"url(#heartGradient)\"\n      />\n    </svg>\n  </div>\n\n  <!-- BOW AND ARROW -->\n  <div class=\"bow-position\" id=\"bowPosition\">\n\n    <svg class=\"bow-art\" id=\"bowArt\" viewBox=\"0 0 320 380\">\n\n      <defs>\n        <linearGradient id=\"woodGradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" stop-color=\"#65351d\"/>\n          <stop offset=\"35%\" stop-color=\"#bd7940\"/>\n          <stop offset=\"65%\" stop-color=\"#8b4d27\"/>\n          <stop offset=\"100%\" stop-color=\"#4e2919\"/>\n        </linearGradient>\n\n        <linearGradient id=\"stringGradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" stop-color=\"#fff0a8\"/>\n          <stop offset=\"50%\" stop-color=\"#c99a39\"/>\n          <stop offset=\"100%\" stop-color=\"#fff0a8\"/>\n        </linearGradient>\n\n        <linearGradient id=\"metalGradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" stop-color=\"#777e89\"/>\n          <stop offset=\"50%\" stop-color=\"#ffffff\"/>\n          <stop offset=\"100%\" stop-color=\"#9ba2ae\"/>\n        </linearGradient>\n      </defs>\n\n      <!-- WOODEN BOW -->\n      <g id=\"bowBody\">\n        <path\n          d=\"M55 260 A105 105 0 0 1 265 260\"\n          fill=\"none\"\n          stroke=\"#4d2818\"\n          stroke-width=\"17\"\n          stroke-linecap=\"round\"\n        />\n\n        <path\n          d=\"M55 260 A105 105 0 0 1 265 260\"\n          fill=\"none\"\n          stroke=\"url(#woodGradient)\"\n          stroke-width=\"12\"\n          stroke-linecap=\"round\"\n        />\n\n        <path\n          d=\"M70 205 Q160 105 250 205\"\n          fill=\"none\"\n          stroke=\"#e0a16a\"\n          stroke-width=\"1.5\"\n          opacity=\".65\"\n        />\n      </g>\n\n      <!-- GOLDEN STRING -->\n      <g id=\"bowString\">\n        <path\n          d=\"M55 260 L160 345 L265 260\"\n          fill=\"none\"\n          stroke=\"#8e682c\"\n          stroke-width=\"3\"\n        />\n\n        <path\n          d=\"M55 260 L160 345 L265 260\"\n          fill=\"none\"\n          stroke=\"url(#stringGradient)\"\n          stroke-width=\"1.5\"\n        />\n      </g>\n\n      <!-- ARROW -->\n      <g id=\"arrowArt\">\n\n        <path\n          d=\"M160 345 L160 165\"\n          stroke=\"#623719\"\n          stroke-width=\"6\"\n          stroke-linecap=\"round\"\n        />\n\n        <path\n          d=\"M160 345 L160 165\"\n          stroke=\"#d69a5e\"\n          stroke-width=\"2\"\n        />\n\n        <!-- METAL TIP -->\n        <path\n          d=\"M160 128 L148 167 L160 162 L172 167 Z\"\n          fill=\"url(#metalGradient)\"\n          stroke=\"#777e89\"\n          stroke-width=\"1\"\n        />\n\n        <path\n          d=\"M160 128 L160 162\"\n          stroke=\"#ffffff\"\n          stroke-width=\"1.5\"\n        />\n\n        <!-- RED FEATHERS -->\n        <path\n          d=\"M160 315 Q139 303 130 283 Q150 289 160 302Z\"\n          fill=\"#e83f62\"\n        />\n\n        <path\n          d=\"M160 315 Q181 303 190 283 Q170 289 160 302Z\"\n          fill=\"#f17b96\"\n        />\n\n        <path\n          d=\"M160 315 L160 371 Q145 352 160 315Z\"\n          fill=\"#c91f4e\"\n        />\n\n        <path\n          d=\"M160 315 L137 289 M160 315 L183 289\"\n          stroke=\"#ffd0dc\"\n          stroke-width=\"1.2\"\n        />\n\n      </g>\n    </svg>\n  </div>\n\n  <div class=\"touch-hint\" id=\"touchHint\">\n    TOUCH ANYWHERE TO RELEASE\n  </div>\n\n  <div id=\"particleLayer\"></div>\n\n</section>\n\n<!-- FINAL BIRTHDAY SCREEN -->\n<section class=\"final-screen\" id=\"finalScreen\">\n\n  <!-- BALLOONS -->\n  <div class=\"balloon-layer\" id=\"balloonLayer\"></div>\n\n  <div class=\"final-content\">\n\n    <div class=\"small-wish\">\n      A SPECIAL DAY FOR A SPECIAL PERSON\n    </div>\n\n    <h1>Happy Birthday</h1>\n\n    <div class=\"title-line\"></div>\n\n    <p>\n      May your life always be filled with happiness and love.\n    </p>\n\n    <div class=\"final-heart\">♥</div>\n\n  </div>\n</section>\n\n<script>\n      let released = false;\n      document.addEventListener(\"pointerdown\", () => {\n        if (released) return;\n        released = true;\n        setTimeout(() => parent.postMessage({type:\"birthday-reveal-next\"}, \"*\"), 1800);\n      }, {once:true, capture:true});\n    </script>\n</body>\n</html>\n<style>\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nhtml, body {\n  width: 100%;\n  height: 100%;\n  overflow: hidden;\n  font-family: Georgia, serif;\n}\n\n/* INTRO */\n\n.intro {\n  position: fixed;\n  inset: 0;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at 50% 25%, #fff9fb, transparent 42%),\n    linear-gradient(145deg, #fff5f7, #ffe5ed, #fff0f4);\n  transition: opacity 1s ease, visibility 1s ease;\n  touch-action: manipulation;\n}\n\n.intro.hide {\n  opacity: 0;\n  visibility: hidden;\n}\n\n.top-text {\n  position: absolute;\n  top: 5%;\n  width: 100%;\n  text-align: center;\n  color: #c76b88;\n  font-family: Arial, sans-serif;\n  font-size: clamp(10px, 2.8vw, 14px);\n  letter-spacing: 4px;\n  font-weight: 600;\n}\n\n/* HEART: 3CM UP */\n\n.heart-area {\n  position: absolute;\n  width: clamp(179px, 33vw, 248px);\n  aspect-ratio: 120 / 110;\n  top: calc(13% + 2cm);\n  left: 50%;\n  transform: translateX(-50%);\n  z-index: 6;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.heart-glow {\n  position: absolute;\n  width: 220%;\n  height: 220%;\n  border-radius: 50%;\n  background: radial-gradient(\n    circle,\n    rgba(255, 74, 130, .32),\n    rgba(255, 120, 160, .12) 42%,\n    transparent 70%\n  );\n  filter: blur(22px);\n  animation: glowPulse 1.8s ease-in-out infinite alternate;\n}\n\n.main-heart {\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n  filter:\n    drop-shadow(0 0 8px rgba(255, 55, 110, .7))\n    drop-shadow(0 0 20px rgba(255, 55, 110, .5))\n    drop-shadow(0 0 35px rgba(255, 55, 110, .35));\n  animation: heartFloat 2.5s ease-in-out infinite;\n  transform-origin: center;\n}\n\n@keyframes glowPulse {\n  from {\n    opacity: .65;\n    transform: scale(.9);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1.1);\n  }\n}\n\n@keyframes heartFloat {\n  0%, 100% {\n    transform: translateY(0) scale(1);\n  }\n  50% {\n    transform: translateY(-7px) scale(1.04);\n  }\n}\n\n/* HEART BREAK */\n\n.main-heart.broken {\n  animation: heartBreak .45s ease forwards;\n}\n\n@keyframes heartBreak {\n  0% {\n    transform: scale(1);\n    opacity: 1;\n  }\n  40% {\n    transform: scale(1.35);\n    filter: brightness(1.8);\n  }\n  100% {\n    transform: scale(.1);\n    opacity: 0;\n  }\n}\n\n/* BOW: ONLY BOW IS 30% SMALLER */\n\n.bow-position {\n  position: absolute;\n  width: min(52.5vw, 231px);\n  aspect-ratio: 320 / 380;\n  left: 50%;\n  bottom: 2.5cm;\n  transform: translateX(-50%);\n  z-index: 5;\n}\n\n.bow-art {\n  display: block;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n  filter: drop-shadow(0 8px 9px rgba(75, 35, 20, .22));\n}\n\n/* BOW DISAPPEARS */\n\n#bowBody,\n#bowString {\n  transition: opacity .25s ease, filter .25s ease;\n}\n\n.bow-position.released #bowBody,\n.bow-position.released #bowString {\n  opacity: 0;\n  filter: blur(5px);\n}\n\n/* ARROW: KEEP CURRENT SIZE */\n\n#arrowArt {\n  transform-box: view-box;\n  transform-origin: 160px 255px;\n  transform: scale(.8);\n  transition: transform .9s cubic-bezier(.18, .72, .25, 1);\n  will-change: transform;\n}\n\n#arrowArt.flying {\n  filter: drop-shadow(0 0 8px rgba(255, 150, 170, .9));\n}\n\n/* TOUCH TEXT */\n\n.touch-hint {\n  position: absolute;\n  bottom: 12px;\n  left: 0;\n  width: 100%;\n  text-align: center;\n  color: #b65c79;\n  font-family: Arial, sans-serif;\n  font-size: 10px;\n  letter-spacing: 3px;\n  font-weight: bold;\n  animation: hintPulse 1.5s ease-in-out infinite;\n  transition: opacity .3s ease;\n}\n\n@keyframes hintPulse {\n  0%, 100% { opacity: .45; }\n  50% { opacity: 1; }\n}\n\n/* FALLING MINI HEARTS */\n\n#particleLayer {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  overflow: hidden;\n  z-index: 10;\n}\n\n.heart-particle {\n  position: absolute;\n  display: block;\n  color: #ff477e;\n  font-family: Arial, sans-serif;\n  line-height: 1;\n  text-shadow: 0 0 8px rgba(255, 65, 125, .55);\n  animation: heartFall var(--fall-duration, 2.5s)\n    cubic-bezier(.2, .65, .4, 1) forwards;\n  will-change: transform, opacity;\n}\n\n@keyframes heartFall {\n  0% {\n    transform: translate(0, 0) rotate(0deg) scale(.45);\n    opacity: 0;\n  }\n  12% {\n    opacity: 1;\n    transform:\n      translate(calc(var(--fall-x) * .15), 15px)\n      rotate(35deg) scale(1);\n  }\n  100% {\n    transform:\n      translate(var(--fall-x), var(--fall-y))\n      rotate(var(--fall-rotate)) scale(.55);\n    opacity: 0;\n  }\n}\n\n/* GLOW RING */\n\n.glow-ring {\n  position: absolute;\n  width: 24px;\n  height: 24px;\n  border: 3px solid #ff6690;\n  border-radius: 50%;\n  animation: ringBurst .8s ease-out forwards;\n}\n\n@keyframes ringBurst {\n  to {\n    transform: scale(9);\n    opacity: 0;\n  }\n}\n\n/* FINAL SCREEN */\n\n.final-screen {\n  position: fixed;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  padding: 25px;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at center, #ff8cae, transparent 55%),\n    linear-gradient(140deg, #a90d42, #e52d65, #8d123f);\n  color: white;\n  opacity: 0;\n  visibility: hidden;\n  transition: opacity 1s ease, visibility 1s ease;\n}\n\n.final-screen.show {\n  opacity: 1;\n  visibility: visible;\n}\n\n/* BIRTHDAY TEXT */\n\n.final-content {\n  position: relative;\n  z-index: 3;\n  width: 100%;\n  animation: finalAppear 1.2s ease both;\n}\n\n@keyframes finalAppear {\n  from {\n    transform: translateY(35px) scale(.9);\n    opacity: 0;\n  }\n  to {\n    transform: translateY(0) scale(1);\n    opacity: 1;\n  }\n}\n\n.small-wish {\n  font-family: Arial, sans-serif;\n  font-size: clamp(10px, 2.5vw, 13px);\n  letter-spacing: 4px;\n  margin-bottom: 22px;\n  color: #ffe1e9;\n}\n\n.final-content h1 {\n  font-size: clamp(38px, 10vw, 70px);\n  font-weight: normal;\n  text-shadow: 0 5px 25px rgba(70, 0, 25, .3);\n}\n\n.title-line {\n  width: 100px;\n  height: 2px;\n  background: #ffd6e2;\n  margin: 24px auto;\n  border-radius: 10px;\n}\n\n.final-content p {\n  max-width: 400px;\n  margin: auto;\n  font-size: clamp(14px, 3.5vw, 18px);\n  line-height: 1.7;\n  color: #ffe9ef;\n}\n\n.final-heart {\n  font-size: 42px;\n  color: #ffd5e0;\n  margin-top: 30px;\n  animation: finalHeartPulse 1.3s infinite alternate;\n}\n\n@keyframes finalHeartPulse {\n  to {\n    transform: scale(1.2);\n    text-shadow: 0 0 25px white;\n  }\n}\n\n/* BALLOON LAYER */\n\n.balloon-layer {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  pointer-events: none;\n  z-index: 2;\n}\n\n/* BALLOON */\n\n.birthday-balloon {\n  position: absolute;\n  bottom: -130px;\n  left: var(--balloon-left);\n  width: var(--balloon-width);\n  height: calc(var(--balloon-width) * 1.28);\n  border-radius: 50% 50% 46% 46%;\n  background: var(--balloon-color);\n  box-shadow:\n    inset -9px -8px 14px rgba(0, 0, 0, .13),\n    inset 7px 6px 12px rgba(255, 255, 255, .32),\n    0 5px 15px rgba(0, 0, 0, .12);\n  animation: balloonRise var(--balloon-duration) linear forwards;\n  animation-delay: var(--balloon-delay);\n  opacity: 0;\n  will-change: transform;\n}\n\n/* Balloon shine */\n\n.birthday-balloon::before {\n  content: \"\";\n  position: absolute;\n  top: 15%;\n  left: 19%;\n  width: 17%;\n  height: 30%;\n  background: rgba(255, 255, 255, .65);\n  border-radius: 50%;\n  transform: rotate(25deg);\n}\n\n/* Balloon knot */\n\n.birthday-balloon::after {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  bottom: -7px;\n  transform: translateX(-50%);\n  border-left: 6px solid transparent;\n  border-right: 6px solid transparent;\n  border-top: 9px solid var(--balloon-color);\n}\n\n/* Balloon string */\n\n.balloon-string {\n  position: absolute;\n  left: 50%;\n  top: calc(100% + 7px);\n  width: 1px;\n  height: var(--string-length);\n  background: rgba(255, 255, 255, .75);\n  transform-origin: top center;\n  animation: stringSwing 1.5s ease-in-out infinite alternate;\n}\n\n@keyframes stringSwing {\n  from { transform: rotate(-8deg); }\n  to { transform: rotate(8deg); }\n}\n\n@keyframes balloonRise {\n  0% {\n    opacity: 0;\n    transform: translate3d(0, 0, 0) rotate(-8deg);\n  }\n  8% {\n    opacity: 1;\n  }\n  50% {\n    transform:\n      translate3d(var(--balloon-drift), -55vh, 0)\n      rotate(8deg);\n  }\n  100% {\n    opacity: 0;\n    transform:\n      translate3d(var(--balloon-drift-end), -125vh, 0)\n      rotate(-12deg);\n  }\n}\n\n/* MOBILE */\n\n@media (max-width: 480px) {\n  .bow-position {\n    width: min(57.75vw, 216px);\n    bottom: 2.1cm;\n  }\n}\n\n@media (max-height: 650px) {\n  .heart-area {\n    top: calc(7% + 2cm);\n    width: clamp(143px, 26.25vw, 198px);\n  }\n\n  .bow-position {\n    width: min(40.6vh, 182px);\n    bottom: 1cm;\n  }\n}\n</style><script>\nconst intro = document.getElementById(\"intro\");\nconst bowPosition = document.getElementById(\"bowPosition\");\nconst bowArt = document.getElementById(\"bowArt\");\nconst arrowArt = document.getElementById(\"arrowArt\");\nconst heartArea = document.getElementById(\"heartArea\");\nconst mainHeart = document.getElementById(\"mainHeart\");\nconst touchHint = document.getElementById(\"touchHint\");\nconst particleLayer = document.getElementById(\"particleLayer\");\nconst finalScreen = document.getElementById(\"finalScreen\");\nconst balloonLayer = document.getElementById(\"balloonLayer\");\n\nlet launched = false;\nlet balloonsStarted = false;\n\nintro.addEventListener(\"pointerdown\", () => {\n  if (launched) return;\n\n  launched = true;\n  launchArrow();\n});\n\n/* ARROW RELEASE */\n\nfunction launchArrow() {\n  touchHint.style.opacity = \"0\";\n\n  // Bow disappears immediately.\n  bowPosition.classList.add(\"released\");\n\n  const svgPoint = bowArt.createSVGPoint();\n  svgPoint.x = 160;\n  svgPoint.y = 128;\n\n  const arrowTip = svgPoint.matrixTransform(\n    bowArt.getScreenCTM()\n  );\n\n  const heartRect = heartArea.getBoundingClientRect();\n\n  const heartX = heartRect.left + heartRect.width / 2;\n  const heartY = heartRect.top + heartRect.height / 2;\n\n  const dx = heartX - arrowTip.x;\n  const dy = heartY - arrowTip.y;\n\n  arrowArt.classList.add(\"flying\");\n\n  requestAnimationFrame(() => {\n    arrowArt.style.transform =\n      `translate(${dx}px, ${dy}px) scale(.8)`;\n  });\n\n  setTimeout(() => {\n    arrowArt.style.opacity = \"0\";\n    hitHeart();\n  }, 950);\n}\n\n/* HEART IMPACT */\n\nfunction hitHeart() {\n  const rect = heartArea.getBoundingClientRect();\n\n  const x = rect.left + rect.width / 2;\n  const y = rect.top + rect.height / 2;\n\n  mainHeart.classList.add(\"broken\");\n\n  createFallingHearts(x, y, rect.width, rect.height);\n  createGlowRing(x, y);\n\n  setTimeout(() => {\n    intro.classList.add(\"hide\");\n\n    setTimeout(() => {\n      finalScreen.classList.add(\"show\");\n\n      // Balloons begin as the birthday screen appears.\n      if (!balloonsStarted) {\n        balloonsStarted = true;\n        startBalloons();\n      }\n\n    }, 350);\n\n  }, 2600);\n}\n\n/* FALLING HEART PARTICLES */\n\nfunction createFallingHearts(x, y, width, height) {\n  const colors = [\n    \"#ff174f\",\n    \"#ff477e\",\n    \"#ff75a0\",\n    \"#f52f69\",\n    \"#ff9bb7\",\n    \"#d91650\",\n    \"#ffc1d2\",\n    \"#ffffff\"\n  ];\n\n  for (let i = 0; i < 75; i++) {\n    const particle = document.createElement(\"span\");\n\n    particle.className = \"heart-particle\";\n    particle.textContent = \"♥\";\n\n    const startX =\n      x + (Math.random() - 0.5) * width * 0.72;\n\n    const startY =\n      y + (Math.random() - 0.5) * height * 0.55;\n\n    particle.style.left = `${startX}px`;\n    particle.style.top = `${startY}px`;\n\n    const color =\n      colors[Math.floor(Math.random() * colors.length)];\n\n    particle.style.color = color;\n\n    const size = 7 + Math.random() * 17;\n    particle.style.fontSize = `${size}px`;\n\n    const fallX = (Math.random() - 0.5) * 220;\n    const fallY = 140 + Math.random() * 380;\n    const rotation = (Math.random() - 0.5) * 540;\n    const duration = 1.7 + Math.random() * 1.5;\n\n    particle.style.setProperty(\"--fall-x\", `${fallX}px`);\n    particle.style.setProperty(\"--fall-y\", `${fallY}px`);\n    particle.style.setProperty(\"--fall-rotate\", `${rotation}deg`);\n    particle.style.setProperty(\"--fall-duration\", `${duration}s`);\n\n    particleLayer.appendChild(particle);\n\n    setTimeout(() => particle.remove(), duration * 1000 + 100);\n  }\n}\n\n/* GLOW RING */\n\nfunction createGlowRing(x, y) {\n  const ring = document.createElement(\"span\");\n\n  ring.className = \"glow-ring\";\n  ring.style.left = `${x - 12}px`;\n  ring.style.top = `${y - 12}px`;\n\n  particleLayer.appendChild(ring);\n\n  setTimeout(() => ring.remove(), 900);\n}\n\n/* BIRTHDAY BALLOONS */\n\nfunction startBalloons() {\n  const colors = [\n    \"#ff4f83\",\n    \"#ffd166\",\n    \"#9b7bff\",\n    \"#54d6c8\",\n    \"#ff8b42\",\n    \"#ffb4d0\",\n    \"#ffffff\",\n    \"#72a9ff\",\n    \"#d66bff\"\n  ];\n\n  // Initial large group of balloons.\n  for (let i = 0; i < 28; i++) {\n    setTimeout(() => {\n      createBalloon(colors);\n    }, i * 180);\n  }\n\n  // More balloons continue rising.\n  const balloonInterval = setInterval(() => {\n    if (!finalScreen.classList.contains(\"show\")) {\n      clearInterval(balloonInterval);\n      return;\n    }\n\n    createBalloon(colors);\n  }, 650);\n\n  // Stop adding new balloons after a while.\n  setTimeout(() => {\n    clearInterval(balloonInterval);\n  }, 18000);\n}\n\nfunction createBalloon(colors) {\n  const balloon = document.createElement(\"div\");\n\n  balloon.className = \"birthday-balloon\";\n\n  const color =\n    colors[Math.floor(Math.random() * colors.length)];\n\n  const width = 25 + Math.random() * 30;\n  const left = 5 + Math.random() * 90;\n  const duration = 5 + Math.random() * 5;\n  const delay = Math.random() * 0.5;\n\n  const drift = (Math.random() - 0.5) * 110;\n  const driftEnd = (Math.random() - 0.5) * 160;\n\n  balloon.style.setProperty(\"--balloon-color\", color);\n  balloon.style.setProperty(\"--balloon-width\", `${width}px`);\n  balloon.style.setProperty(\"--balloon-left\", `${left}%`);\n  balloon.style.setProperty(\"--balloon-duration\", `${duration}s`);\n  balloon.style.setProperty(\"--balloon-delay\", `${delay}s`);\n  balloon.style.setProperty(\"--balloon-drift\", `${drift}px`);\n  balloon.style.setProperty(\"--balloon-drift-end\", `${driftEnd}px`);\n\n  balloon.style.setProperty(\n    \"--string-length\",\n    `${35 + Math.random() * 35}px`\n  );\n\n  const string = document.createElement(\"span\");\n  string.className = \"balloon-string\";\n\n  balloon.appendChild(string);\n  balloonLayer.appendChild(balloon);\n\n  setTimeout(() => {\n    balloon.remove();\n  }, (duration + delay) * 1000 + 500);\n}\n</script>", "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<title>Happy Birthday - Blooming Heart Tree</title>\n\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@600;700&family=Nunito:ital,wght@0,500;0,700;1,600;1,700&display=swap\" rel=\"stylesheet\">\n\n<style>\n* {\n    box-sizing: border-box;\n    -webkit-tap-highlight-color: transparent;\n    user-select: none;\n}\n\nbody {\n    margin: 0;\n    padding: 0;\n    min-height: 100vh;\n    min-height: 100dvh;\n    background-color: #2b1f1a;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-family: 'Nunito', sans-serif;\n    overflow: hidden;\n}\n\n#app-container {\n    position: relative;\n    width: 100vw;\n    height: 100vh;\n    height: 100dvh;\n    max-width: 480px;\n    max-height: 920px;\n    background: radial-gradient(circle at 50% 62%, #fffdf8 0%, #fff0dc 32%, #fce1c3 68%, #f7cfa8 100%);\n    overflow: hidden;\n    box-shadow: 0 25px 60px rgba(0,0,0,.45);\n    cursor: pointer;\n}\n\n@media (min-width: 520px) {\n    #app-container {\n        height: 94vh;\n        border-radius: 28px;\n        border: 4px solid rgba(255,255,255,.25);\n    }\n}\n\n.sun-glow {\n    position: absolute;\n    top: 48%;\n    left: 50%;\n    transform: translate(-50%,-50%);\n    width: 85%;\n    aspect-ratio: 1/1;\n    background: radial-gradient(circle, rgba(255,255,255,.75) 0%, rgba(255,244,224,.35) 45%, rgba(255,230,200,0) 75%);\n    pointer-events: none;\n    z-index: 1;\n}\n\n.balloon-layer {\n    position: absolute;\n    inset: 0;\n    overflow: hidden;\n    z-index: 2;\n    pointer-events: none;\n}\n\n#treeCanvas {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    z-index: 3;\n    display: block;\n}\n\n.glass-card {\n    position: absolute;\n    left: 4.5%;\n    right: 4.5%;\n    bottom: 9.5%;\n    min-height: 31%;\n    background: linear-gradient(135deg,rgba(255,255,255,.56),rgba(255,248,242,.42));\n    backdrop-filter: blur(8px);\n    -webkit-backdrop-filter: blur(8px);\n    border-radius: 20px;\n    border: 1px solid rgba(255,255,255,.65);\n    box-shadow: 0 10px 30px rgba(135,85,65,.08);\n    padding: 24px 24px 28px;\n    z-index: 4;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    opacity: 0;\n    transform: translateY(14px);\n    transition: opacity .8s ease-out,transform .8s cubic-bezier(.22,1,.36,1);\n    pointer-events: auto;\n}\n\n.glass-card.visible {\n    opacity: 1;\n    transform: translateY(0);\n}\n\n.subtitle-top {\n    font-family: 'Nunito',sans-serif;\n    font-style: italic;\n    font-weight: 700;\n    font-size: clamp(.95rem,3.8vw,1.12rem);\n    color: #805b68;\n    text-shadow: 0 1px 8px rgba(255,255,255,.7);\n    letter-spacing: .01em;\n    margin-bottom: 8px;\n    opacity: 0;\n    transform: translateY(8px);\n    transition: opacity .7s ease,transform .7s ease;\n}\n\n.title-main {\n    font-family: 'Fredoka',sans-serif;\n    font-weight: 700;\n    font-size: clamp(1.85rem,7.6vw,2.35rem);\n    line-height: 1.12;\n    color: #df5b57;\n    text-shadow: 0 2px 10px rgba(223,91,87,.14);\n    margin-bottom: 14px;\n    opacity: 0;\n    transform: translateY(10px) scale(.97);\n    transition: opacity .8s ease,transform .8s cubic-bezier(.22,1,.36,1);\n    word-wrap: break-word;\n}\n\n.subtitle-bottom {\n    font-family: 'Nunito',sans-serif;\n    font-style: italic;\n    font-weight: 700;\n    font-size: clamp(.95rem,3.8vw,1.12rem);\n    color: #75505b;\n    letter-spacing: .01em;\n    opacity: 0;\n    transform: translateY(8px);\n    transition: opacity .7s ease,transform .7s ease;\n    min-height: 1.4em;\n}\n\n.text-show {\n    opacity: 1 !important;\n    transform: translateY(0) scale(1) !important;\n}\n\n.tap-prompt {\n    position: absolute;\n    bottom: 2.2%;\n    left: 0;\n    right: 0;\n    text-align: center;\n    font-family: 'Nunito',sans-serif;\n    font-weight: 700;\n    font-size: .9rem;\n    color: #a89088;\n    letter-spacing: .02em;\n    z-index: 5;\n    opacity: 0;\n    transition: opacity .8s ease;\n    animation: gentlePulse 2.2s infinite ease-in-out;\n    pointer-events: none;\n}\n\n.tap-prompt.visible {\n    opacity: 1;\n}\n\n@keyframes gentlePulse {\n    0%,100% { opacity: .55; transform: translateY(0); }\n    50% { opacity: 1; transform: translateY(-2px); }\n}\n\n.top-controls {\n    position: absolute;\n    top: 16px;\n    right: 16px;\n    display: flex;\n    gap: 8px;\n    z-index: 10;\n}\n\n.icon-btn {\n    width: 36px;\n    height: 36px;\n    border-radius: 50%;\n    background: rgba(255,255,255,.45);\n    backdrop-filter: blur(6px);\n    -webkit-backdrop-filter: blur(6px);\n    border: 1px solid rgba(255,255,255,.65);\n    color: #6e564f;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: all .2s ease;\n    box-shadow: 0 2px 8px rgba(90,56,46,.08);\n}\n\n.icon-btn:hover {\n    background: rgba(255,255,255,.8);\n    transform: scale(1.06);\n    color: #df5b57;\n}\n\n#nameModal {\n    position: absolute;\n    inset: 0;\n    background: rgba(58,38,30,.45);\n    backdrop-filter: blur(5px);\n    -webkit-backdrop-filter: blur(5px);\n    z-index: 20;\n    display: none;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n}\n\n#nameModal.open {\n    display: flex;\n}\n\n/* BALLOONS */\n\n.balloon {\n    --balloon-color: #ff8fab;\n    --balloon-light: #ffd2df;\n    position: absolute;\n    left: var(--x);\n    bottom: -125px;\n    width: var(--size);\n    height: calc(var(--size) * 1.22);\n    border-radius: 50% 50% 46% 46%;\n    opacity: 0;\n    background:\n        radial-gradient(ellipse at 29% 24%,rgba(255,255,255,.88) 0 5%,rgba(255,255,255,.38) 13%,transparent 32%),\n        radial-gradient(ellipse at 68% 72%,rgba(0,0,0,.13),transparent 48%),\n        linear-gradient(115deg,var(--balloon-light),var(--balloon-color) 56%,#a45b78);\n    box-shadow: inset -5px -7px 10px rgba(90,35,60,.12),0 5px 13px rgba(112,65,55,.10);\n    animation: balloonRise var(--duration) linear forwards;\n    animation-delay: var(--delay);\n    will-change: transform,opacity;\n}\n\n.balloon::before {\n    content: \"\";\n    position: absolute;\n    left: 50%;\n    bottom: -7px;\n    transform: translateX(-50%);\n    width: 10px;\n    height: 9px;\n    background: var(--balloon-color);\n    clip-path: polygon(0 0,100% 0,50% 100%);\n}\n\n.balloon::after {\n    content: \"\";\n    position: absolute;\n    left: 50%;\n    top: calc(100% + 2px);\n    width: 1px;\n    height: calc(var(--size) * .95);\n    background: rgba(105,75,70,.48);\n    transform-origin: top;\n    animation: stringSway 2.8s ease-in-out infinite alternate;\n}\n\n@keyframes balloonRise {\n    0% { opacity: 0; transform: translate3d(0,0,0) rotate(-5deg) scale(.88); }\n    8% { opacity: .82; }\n    48% { transform: translate3d(var(--drift),-58vh,0) rotate(5deg) scale(1); }\n    92% { opacity: .78; }\n    100% { opacity: 0; transform: translate3d(calc(var(--drift) * -.35),-135vh,0) rotate(-4deg) scale(.96); }\n}\n\n@keyframes stringSway {\n    from { transform: rotate(-7deg); }\n    to { transform: rotate(8deg); }\n}\n\n/* TEXT ANIMATION FIX */\n\n.birthday-line {\n    display: inline-block;\n    color: #d94f68;\n    filter: drop-shadow(0 3px 5px rgba(215,75,105,.12));\n}\n\n.letter {\n    display: inline-block;\n    opacity: 0;\n    transform: translateY(18px) scale(.82) rotate(-5deg);\n    animation: letterBloom .58s cubic-bezier(.2,.85,.25,1.25) forwards;\n    animation-delay: var(--letter-delay,0ms);\n}\n\n#recipientName {\n    display: inline-block;\n    color: #d94f78;\n    -webkit-text-fill-color: initial;\n    letter-spacing: .075em;\n    text-shadow: 0 3px 0 rgba(255,255,255,.55),0 5px 16px rgba(217,79,120,.24);\n}\n\n/* FIX: Gradient is applied to each animated letter */\n.birthday-line .letter,\n#recipientName .letter {\n    background: linear-gradient(100deg,#c83f70,#f18ba7 48%,#c83f70);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n    -webkit-text-fill-color: transparent;\n}\n\n@keyframes letterBloom {\n    0% {\n        opacity: 0;\n        transform: translateY(18px) scale(.82) rotate(-5deg);\n        filter: blur(3px);\n    }\n    72% {\n        opacity: 1;\n        transform: translateY(-3px) scale(1.08) rotate(1deg);\n        filter: blur(0);\n    }\n    100% {\n        opacity: 1;\n        transform: translateY(0) scale(1) rotate(0);\n        filter: blur(0);\n    }\n}\n\n.subtitle-bottom.typing::after {\n    content: \"\";\n    display: inline-block;\n    width: 2px;\n    height: .95em;\n    margin-left: 3px;\n    vertical-align: -2px;\n    background: #d94f78;\n    animation: typingCursor .75s steps(1) infinite;\n}\n\n@keyframes typingCursor {\n    50% { opacity: 0; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .balloon,.balloon::after,.letter,.subtitle-bottom.typing::after {\n        animation-duration: .01ms !important;\n        animation-iteration-count: 1 !important;\n    }\n}\n</style>\n</head>\n\n<body>\n\n<div id=\"app-container\" title=\"Tap anywhere for a heart burst or replay\">\n\n    <div class=\"sun-glow\"></div>\n\n    <div id=\"balloonLayer\" class=\"balloon-layer\" aria-hidden=\"true\"></div>\n\n    <div class=\"top-controls\" id=\"controls-bar\">\n\n        <button id=\"editNameBtn\" class=\"icon-btn\" title=\"Customize Name\" aria-label=\"Customize Name\">\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M12 20h9\"></path>\n                <path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"></path>\n            </svg>\n        </button>\n\n        <button id=\"replayBtn\" class=\"icon-btn\" title=\"Replay Tree Growth\" aria-label=\"Replay Animation\">\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8\"></path>\n                <path d=\"M3 3v5h5\"></path>\n            </svg>\n        </button>\n\n    </div>\n\n    <canvas id=\"treeCanvas\"></canvas>\n\n    <div class=\"glass-card\" id=\"glassCard\">\n        <p class=\"subtitle-top\" id=\"textTop\">it's officially your day</p>\n\n        <h1 class=\"title-main\" id=\"textMain\">\n            <span class=\"birthday-line\" id=\"birthdayLine\">Happy Birthday,</span>\n            <br>\n            <span id=\"recipientName\">SHIVANI</span>\n        </h1>\n\n        <p class=\"subtitle-bottom\" id=\"textBottom\">here's to a year that blooms</p>\n    </div>\n\n    <div class=\"tap-prompt\" id=\"tapPrompt\">tap anywhere to continue</div>\n\n    <div id=\"nameModal\">\n        <div class=\"bg-white/95 rounded-2xl p-6 w-full max-w-xs shadow-2xl border border-amber-100 text-center\" onclick=\"event.stopPropagation()\">\n\n            <h2 class=\"text-lg font-bold text-[#59382e] mb-1\" style=\"font-family:'Fredoka',sans-serif;\">\n                Personalize Card\n            </h2>\n\n            <p class=\"text-xs text-[#8a6d65] mb-4\">\n                Enter the birthday person's name\n            </p>\n\n            <input\n                type=\"text\"\n                id=\"nameInput\"\n                maxlength=\"22\"\n                placeholder=\"e.g. KOMAL\"\n                class=\"w-full px-4 py-2.5 rounded-xl border border-rose-200 focus:outline-none focus:border-[#df5b57] text-center font-bold text-[#df5b57] uppercase tracking-wide mb-4 bg-rose-50/40\"\n            >\n\n            <div class=\"flex gap-2\">\n                <button id=\"cancelModalBtn\" class=\"flex-1 py-2 rounded-xl bg-stone-100 text-stone-600 font-semibold text-sm hover:bg-stone-200 transition\">\n                    Cancel\n                </button>\n\n                <button id=\"saveNameBtn\" class=\"flex-1 py-2 rounded-xl bg-[#df5b57] text-white font-semibold text-sm hover:bg-[#c94a46] transition shadow-md\">\n                    Bloom ✨\n                </button>\n            </div>\n\n        </div>\n    </div>\n\n</div>\n\n<script>\n(function () {\n\n    const container = document.getElementById('app-container');\n    const canvas = document.getElementById('treeCanvas');\n    const ctx = canvas.getContext('2d');\n\n    const glassCard = document.getElementById('glassCard');\n    const textTop = document.getElementById('textTop');\n    const textMain = document.getElementById('textMain');\n    const textBottom = document.getElementById('textBottom');\n    const tapPrompt = document.getElementById('tapPrompt');\n\n    const recipientNameEl = document.getElementById('recipientName');\n    const birthdayLineEl = document.getElementById('birthdayLine');\n    const balloonLayer = document.getElementById('balloonLayer');\n\n    const bottomMessage = \"here's to a year that blooms\";\n\n    const editNameBtn = document.getElementById('editNameBtn');\n    const replayBtn = document.getElementById('replayBtn');\n    const nameModal = document.getElementById('nameModal');\n    const nameInput = document.getElementById('nameInput');\n    const cancelModalBtn = document.getElementById('cancelModalBtn');\n    const saveNameBtn = document.getElementById('saveNameBtn');\n\n    const HEART_COLORS = [\n        {base:'#ff758f',light:'#ffb3c1',dark:'#d94862'},\n        {base:'#ff8fa3',light:'#ffccd5',dark:'#e05770'},\n        {base:'#ffa07a',light:'#ffd6c4',dark:'#e06d44'},\n        {base:'#ffb703',light:'#ffe89e',dark:'#d99200'},\n        {base:'#ffcad4',light:'#fff0f3',dark:'#e396a4'},\n        {base:'#ffd166',light:'#fff3cc',dark:'#e0a82e'},\n        {base:'#fff1e6',light:'#ffffff',dark:'#edd4c0'}\n    ];\n\n    let width = 0;\n    let height = 0;\n    let dpr = Math.min(window.devicePixelRatio || 1,2);\n\n    let startTime = null;\n    let animationId = null;\n\n    let branches = [];\n    let canopyHearts = [];\n    let ambientHearts = [];\n    let burstHearts = [];\n\n    let isTreeBloomed = false;\n    let balloonsStarted = false;\n    let balloonTimer = null;\n    let typingTimer = null;\n\n    const TRUNK_DURATION = 650;\n    const BRANCH_DURATION = 1050;\n    const BLOOM_START = 1350;\n    const BLOOM_DURATION = 1600;\n\n    const spriteCache = new Map();\n\n    function getHeartSprite(colorObj,size) {\n\n        const quantizedSize = Math.round(size);\n        const key = `${colorObj.base}_${quantizedSize}`;\n\n        if (spriteCache.has(key)) {\n            return spriteCache.get(key);\n        }\n\n        const pad = 6;\n        const dim = quantizedSize * 2 + pad * 2;\n\n        const off = document.createElement('canvas');\n        off.width = dim * dpr;\n        off.height = dim * dpr;\n\n        const octx = off.getContext('2d');\n        octx.scale(dpr,dpr);\n\n        const cx = dim/2;\n        const cy = dim/2;\n        const s = quantizedSize;\n\n        function traceHeart(c,x,y,r) {\n\n            c.beginPath();\n\n            const topCurveHeight = r*.32;\n\n            c.moveTo(x,y+topCurveHeight);\n\n            c.bezierCurveTo(\n                x,y-r*.25,\n                x-r,y-r*.25,\n                x-r,y+topCurveHeight\n            );\n\n            c.bezierCurveTo(\n                x-r,y+r*.75,\n                x,y+r*1.15,\n                x,y+r*1.35\n            );\n\n            c.bezierCurveTo(\n                x,y+r*1.15,\n                x+r,y+r*.75,\n                x+r,y+topCurveHeight\n            );\n\n            c.bezierCurveTo(\n                x+r,y-r*.25,\n                x,y-r*.25,\n                x,y+topCurveHeight\n            );\n\n            c.closePath();\n        }\n\n        octx.save();\n\n        octx.shadowColor = 'rgba(140,65,55,.18)';\n        octx.shadowBlur = 4;\n        octx.shadowOffsetY = 2;\n\n        const grad = octx.createRadialGradient(\n            cx-s*.3,cy-s*.1,s*.08,\n            cx,cy+s*.2,s*1.35\n        );\n\n        grad.addColorStop(0,colorObj.light);\n        grad.addColorStop(.55,colorObj.base);\n        grad.addColorStop(1,colorObj.dark);\n\n        traceHeart(octx,cx,cy-s*.45,s);\n\n        octx.fillStyle = grad;\n        octx.fill();\n\n        octx.restore();\n\n        octx.save();\n\n        octx.beginPath();\n        octx.ellipse(\n            cx-s*.36,\n            cy-s*.18,\n            s*.22,\n            s*.12,\n            -Math.PI/4,\n            0,\n            Math.PI*2\n        );\n\n        octx.fillStyle = 'rgba(255,255,255,.65)';\n        octx.fill();\n\n        octx.restore();\n\n        spriteCache.set(key,off);\n\n        return off;\n    }\n\n    function heartPoint(t,scaleX,scaleY) {\n\n        const x = 16*Math.pow(Math.sin(t),3);\n\n        const y = -(\n            13*Math.cos(t)\n            -5*Math.cos(2*t)\n            -2*Math.cos(3*t)\n            -Math.cos(4*t)\n        );\n\n        return {\n            x:x*scaleX,\n            y:y*scaleY\n        };\n    }\n\n    function generateTreeStructure() {\n\n        branches = [];\n\n        const centerX = width*.5;\n        const groundY = height+8;\n        const forkY = height*.43;\n\n        branches.push({\n            x0:centerX-2,\n            y0:groundY,\n            cx:centerX+3,\n            cy:(groundY+forkY)*.52,\n            x1:centerX,\n            y1:forkY,\n            widthStart:Math.max(8,width*.022),\n            widthEnd:Math.max(5.5,width*.015),\n            startTime:0,\n            duration:TRUNK_DURATION,\n            depth:0\n        });\n\n        function addBranch(\n            x0,y0,angle,length,\n            wStart,wEnd,delay,dur,depth\n        ) {\n\n            const x1 = x0+Math.cos(angle)*length;\n            const y1 = y0+Math.sin(angle)*length;\n\n            const perp = angle+(depth%2===0?.35:-.35);\n\n            const cx = (x0+x1)*.5+Math.cos(perp)*(length*.12);\n            const cy = (y0+y1)*.5+Math.sin(perp)*(length*.12);\n\n            branches.push({\n                x0,y0,cx,cy,x1,y1,\n                widthStart:wStart,\n                widthEnd:wEnd,\n                startTime:delay,\n                duration:dur,\n                depth\n            });\n\n            if (depth<4) {\n\n                const nextDelay = delay+dur*.65;\n                const nextDur = dur*.82;\n                const spread = .34-depth*.03;\n                const shrink = .74;\n\n                addBranch(\n                    x1,y1,\n                    angle-spread-Math.random()*.08,\n                    length*(shrink+Math.random()*.08),\n                    wEnd,wEnd*.68,\n                    nextDelay,nextDur,depth+1\n                );\n\n                addBranch(\n                    x1,y1,\n                    angle+spread+Math.random()*.08,\n                    length*(shrink+Math.random()*.08),\n                    wEnd,wEnd*.68,\n                    nextDelay+30,nextDur,depth+1\n                );\n            }\n        }\n\n        const baseLen = Math.min(width*.24,height*.14);\n        const wBough = Math.max(4.8,width*.013);\n\n        addBranch(\n            centerX,forkY+4,\n            -Math.PI*.68,\n            baseLen,\n            wBough,wBough*.65,\n            TRUNK_DURATION*.82,340,1\n        );\n\n        addBranch(\n            centerX,forkY+4,\n            -Math.PI*.32,\n            baseLen,\n            wBough,wBough*.65,\n            TRUNK_DURATION*.82,340,1\n        );\n\n        addBranch(\n            centerX,forkY-6,\n            -Math.PI*.52,\n            baseLen*.72,\n            wBough*.8,wBough*.5,\n            TRUNK_DURATION*.9,320,1\n        );\n    }\n\n    function generateHeartCanopy() {\n\n        canopyHearts = [];\n\n        const heartCenterX = width*.5;\n        const heartCenterY = height*.265;\n\n        const scaleX = (width*.43)/16;\n        const scaleY = (height*.21)/16;\n\n        const totalHearts = 460;\n\n        for (let i=0;i<totalHearts;i++) {\n\n            const isPerimeter = i<120;\n            const t = Math.random()*Math.PI*2;\n\n            const r = isPerimeter\n                ? .86+Math.random()*.16\n                : Math.pow(Math.random(),.48)*.95;\n\n            const pt = heartPoint(t,scaleX*r,scaleY*r);\n\n            const x = heartCenterX+pt.x+(Math.random()-.5)*6;\n            const y = heartCenterY+pt.y+(Math.random()-.5)*6;\n\n            const distNorm = Math.min(1,r);\n\n            const bloomDelay =\n                BLOOM_START+distNorm*950+Math.random()*450;\n\n            const colorObj =\n                HEART_COLORS[Math.floor(Math.random()*HEART_COLORS.length)];\n\n            const baseSize =\n                Math.max(9,Math.min(width*.036,16))*(.78+Math.random()*.55);\n\n            canopyHearts.push({\n                x,y,baseSize,colorObj,\n                rotation:(Math.random()-.5)*.55,\n                delay:bloomDelay,\n                duration:480+Math.random()*260,\n                swayPhase:Math.random()*Math.PI*2,\n                swaySpeed:.0015+Math.random()*.0015\n            });\n        }\n\n        canopyHearts.sort(\n            (a,b)=>(a.delay-b.delay)+(Math.random()-.5)*120\n        );\n    }\n\n    function generateAmbientHearts() {\n\n        ambientHearts = [];\n\n        const count = 14;\n\n        for (let i=0;i<count;i++) {\n\n            ambientHearts.push({\n                x:Math.random()*width,\n                y:Math.random()*height,\n                size:5+Math.random()*5,\n                speedY:.18+Math.random()*.25,\n                driftPhase:Math.random()*Math.PI*2,\n                opacity:.22+Math.random()*.35,\n                colorObj:HEART_COLORS[i%4]\n            });\n        }\n    }\n\n    function spawnBurst(x,y) {\n\n        const count = 16;\n\n        for (let i=0;i<count;i++) {\n\n            const angle =\n                Math.PI*2*i/count+(Math.random()-.5)*.3;\n\n            const speed = 1.6+Math.random()*3.2;\n\n            burstHearts.push({\n                x,y,\n                vx:Math.cos(angle)*speed,\n                vy:Math.sin(angle)*speed-1.2,\n                size:7+Math.random()*7,\n                alpha:1,\n                rotation:(Math.random()-.5)*.5,\n                colorObj:HEART_COLORS[\n                    Math.floor(Math.random()*HEART_COLORS.length)\n                ]\n            });\n        }\n    }\n\n    function easeOutBack(t) {\n\n        const c1 = 1.70158;\n        const c3 = c1+1;\n\n        return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2);\n    }\n\n    function drawGrowingBranch(b,progress) {\n\n        if (progress<=0) return;\n\n        const p = Math.min(1,progress);\n        const steps = Math.max(6,Math.ceil(p*18));\n\n        ctx.lineCap = 'round';\n        ctx.strokeStyle = '#59382e';\n\n        let prevX = b.x0;\n        let prevY = b.y0;\n\n        for (let i=1;i<=steps;i++) {\n\n            const t = (i/steps)*p;\n            const invT = 1-t;\n\n            const currX =\n                invT*invT*b.x0+\n                2*invT*t*b.cx+\n                t*t*b.x1;\n\n            const currY =\n                invT*invT*b.y0+\n                2*invT*t*b.cy+\n                t*t*b.y1;\n\n            ctx.beginPath();\n            ctx.moveTo(prevX,prevY);\n            ctx.lineTo(currX,currY);\n\n            ctx.lineWidth =\n                b.widthStart+(b.widthEnd-b.widthStart)*t;\n\n            ctx.stroke();\n\n            prevX = currX;\n            prevY = currY;\n        }\n    }\n\n    /* LETTER ANIMATION */\n\n    function animateLetters(element) {\n\n        const value = element.textContent;\n\n        element.textContent = '';\n\n        Array.from(value).forEach((character,index)=>{\n\n            const span = document.createElement('span');\n\n            span.className = 'letter';\n\n            span.style.setProperty(\n                '--letter-delay',\n                `${index*58}ms`\n            );\n\n            span.textContent =\n                character===' '?'\\u00A0':character;\n\n            element.appendChild(span);\n        });\n    }\n\n    /* BOTTOM MESSAGE TYPING */\n\n    function typeBottomMessage() {\n\n        if (typingTimer) {\n            clearInterval(typingTimer);\n        }\n\n        textBottom.textContent = '';\n        textBottom.classList.add('typing');\n\n        let index = 0;\n\n        typingTimer = setInterval(()=>{\n\n            textBottom.textContent +=\n                bottomMessage.charAt(index);\n\n            index++;\n\n            if (index>=bottomMessage.length) {\n\n                clearInterval(typingTimer);\n                typingTimer = null;\n\n                setTimeout(()=>{\n                    textBottom.classList.remove('typing');\n                },700);\n            }\n\n        },42);\n    }\n\n    /* BALLOONS */\n\n    const BALLOON_PALETTE = [\n        ['#ff7fa0','#ffd0dc'],\n        ['#ffb347','#ffe0a8'],\n        ['#9b8cff','#d9d2ff'],\n        ['#62c7d5','#c5f3f5'],\n        ['#f47fba','#ffd0e8'],\n        ['#8fcf9b','#d8f4d9'],\n        ['#f2c94c','#fff0a8']\n    ];\n\n    function createBalloon() {\n\n        if (!balloonLayer) return;\n\n        const balloon = document.createElement('span');\n\n        balloon.className = 'balloon';\n\n        const palette =\n            BALLOON_PALETTE[\n                Math.floor(Math.random()*BALLOON_PALETTE.length)\n            ];\n\n        const size = 25+Math.random()*23;\n\n        balloon.style.setProperty('--balloon-color',palette[0]);\n        balloon.style.setProperty('--balloon-light',palette[1]);\n        balloon.style.setProperty('--size',`${size}px`);\n        balloon.style.setProperty('--x',`${3+Math.random()*90}%`);\n        balloon.style.setProperty('--duration',`${10+Math.random()*7}s`);\n        balloon.style.setProperty('--delay',`${Math.random()*.7}s`);\n        balloon.style.setProperty('--drift',`${-34+Math.random()*68}px`);\n\n        balloon.addEventListener(\n            'animationend',\n            ()=>balloon.remove(),\n            {once:true}\n        );\n\n        balloonLayer.appendChild(balloon);\n    }\n\n    function startBalloons() {\n\n        if (balloonsStarted) return;\n\n        balloonsStarted = true;\n\n        for (let i=0;i<5;i++) {\n            setTimeout(createBalloon,i*260);\n        }\n\n        balloonTimer = setInterval(createBalloon,850);\n    }\n\n    function stopBalloons() {\n\n        if (balloonTimer) {\n            clearInterval(balloonTimer);\n            balloonTimer = null;\n        }\n\n        balloonsStarted = false;\n\n        if (balloonLayer) {\n            balloonLayer.replaceChildren();\n        }\n    }\n\n    /* GREETING TEXT REVEAL */\n\n    function scheduleCardTextReveal() {\n\n        glassCard.classList.remove('visible');\n\n        textTop.classList.remove('text-show');\n        textMain.classList.remove('text-show');\n\n        textBottom.classList.remove('text-show','typing');\n\n        tapPrompt.classList.remove('visible');\n\n        if (typingTimer) {\n            clearInterval(typingTimer);\n            typingTimer = null;\n        }\n\n        textBottom.textContent = '';\n\n        animateLetters(birthdayLineEl);\n        animateLetters(recipientNameEl);\n\n        setTimeout(()=>{\n            glassCard.classList.add('visible');\n            textTop.classList.add('text-show');\n        },850);\n\n        setTimeout(()=>{\n            textMain.classList.add('text-show');\n        },1250);\n\n        setTimeout(()=>{\n            textBottom.classList.add('text-show');\n            typeBottomMessage();\n        },2150);\n\n        setTimeout(()=>{\n            tapPrompt.classList.add('visible');\n            isTreeBloomed = true;\n        },3900);\n    }\n\n    /* MAIN RENDER LOOP */\n\n    function render(timestamp) {\n\n        if (!startTime) {\n            startTime = timestamp;\n        }\n\n        const elapsed = timestamp-startTime;\n\n        if (elapsed>=3900&&!balloonsStarted) {\n            startBalloons();\n        }\n\n        ctx.clearRect(0,0,width,height);\n\n        /* Floating hearts */\n\n        for (let i=0;i<ambientHearts.length;i++) {\n\n            const ah = ambientHearts[i];\n\n            ah.y -= ah.speedY;\n\n            if (ah.y < -20) {\n                ah.y = height+20;\n                ah.x = Math.random()*width;\n            }\n\n            const swayX =\n                Math.sin(timestamp*.0012+ah.driftPhase)*12;\n\n            const sprite =\n                getHeartSprite(ah.colorObj,ah.size);\n\n            const drawDim = sprite.width/dpr;\n\n            ctx.save();\n\n            ctx.globalAlpha = ah.opacity;\n\n            ctx.drawImage(\n                sprite,\n                ah.x+swayX-drawDim/2,\n                ah.y-drawDim/2,\n                drawDim,\n                drawDim\n            );\n\n            ctx.restore();\n        }\n\n        /* Tree branches */\n\n        for (let i=0;i<branches.length;i++) {\n\n            const b = branches[i];\n\n            const localElapsed = elapsed-b.startTime;\n\n            if (localElapsed>0) {\n\n                const rawProgress =\n                    Math.min(1,localElapsed/b.duration);\n\n                const eased =\n                    1-Math.pow(1-rawProgress,2.2);\n\n                drawGrowingBranch(b,eased);\n            }\n        }\n\n        /* Heart canopy */\n\n        for (let i=0;i<canopyHearts.length;i++) {\n\n            const h = canopyHearts[i];\n\n            const localElapsed = elapsed-h.delay;\n\n            if (localElapsed<=0) continue;\n\n            const rawT = Math.min(1,localElapsed/h.duration);\n\n            const scale =\n                rawT<1?easeOutBack(rawT):1;\n\n            const breezeX =\n                rawT>=1\n                ?Math.sin(timestamp*h.swaySpeed+h.swayPhase)*1.6\n                :0;\n\n            const breezeY =\n                rawT>=1\n                ?Math.cos(timestamp*h.swaySpeed+h.swayPhase)*1.1\n                :0;\n\n            const sprite =\n                getHeartSprite(h.colorObj,h.baseSize);\n\n            const drawDim =\n                (sprite.width/dpr)*scale;\n\n            ctx.save();\n\n            ctx.translate(h.x+breezeX,h.y+breezeY);\n\n            ctx.rotate(\n                h.rotation+\n                (rawT>=1\n                    ?Math.sin(timestamp*.0015+h.swayPhase)*.04\n                    :0)\n            );\n\n            ctx.drawImage(\n                sprite,\n                -drawDim/2,\n                -drawDim/2,\n                drawDim,\n                drawDim\n            );\n\n            ctx.restore();\n        }\n\n        /* Tap burst hearts */\n\n        for (let i=burstHearts.length-1;i>=0;i--) {\n\n            const bh = burstHearts[i];\n\n            bh.x += bh.vx;\n            bh.y += bh.vy;\n\n            bh.vy += .04;\n            bh.alpha -= .018;\n\n            if (bh.alpha<=0) {\n                burstHearts.splice(i,1);\n                continue;\n            }\n\n            const sprite =\n                getHeartSprite(bh.colorObj,bh.size);\n\n            const drawDim = sprite.width/dpr;\n\n            ctx.save();\n\n            ctx.globalAlpha = bh.alpha;\n\n            ctx.translate(bh.x,bh.y);\n            ctx.rotate(bh.rotation);\n\n            ctx.drawImage(\n                sprite,\n                -drawDim/2,\n                -drawDim/2,\n                drawDim,\n                drawDim\n            );\n\n            ctx.restore();\n        }\n\n        animationId = requestAnimationFrame(render);\n    }\n\n    /* CANVAS RESIZE */\n\n    function resizeCanvas() {\n\n        const rect = container.getBoundingClientRect();\n\n        width = rect.width;\n        height = rect.height;\n\n        dpr = Math.min(window.devicePixelRatio||1,2);\n\n        canvas.width = width*dpr;\n        canvas.height = height*dpr;\n\n        ctx.setTransform(dpr,0,0,dpr,0,0);\n\n        generateTreeStructure();\n        generateHeartCanopy();\n        generateAmbientHearts();\n    }\n\n    /* REPLAY ANIMATION */\n\n    function startAnimation() {\n\n        if (animationId) {\n            cancelAnimationFrame(animationId);\n        }\n\n        stopBalloons();\n\n        if (typingTimer) {\n            clearInterval(typingTimer);\n            typingTimer = null;\n        }\n\n        isTreeBloomed = false;\n        startTime = null;\n\n        burstHearts = [];\n\n        resizeCanvas();\n\n        scheduleCardTextReveal();\n\n        animationId = requestAnimationFrame(render);\n    }\n\n    /* CLICK INTERACTION */\n\n    container.addEventListener('click',(e)=>{\n\n        if (\n            e.target.closest('#controls-bar')||\n            e.target.closest('#nameModal')\n        ) {\n            return;\n        }\n\n        const rect = container.getBoundingClientRect();\n\n        const clickX = e.clientX-rect.left;\n        const clickY = e.clientY-rect.top;\n\n        spawnBurst(clickX,clickY);\n\n        if (\n            e.target.closest('#tapPrompt')||\n            (isTreeBloomed&&clickY>height*.88)\n        ) {\n            startAnimation();\n        }\n    });\n\n    /* REPLAY BUTTON */\n\n    replayBtn.addEventListener('click',(e)=>{\n        e.stopPropagation();\n        startAnimation();\n    });\n\n    /* CHANGE NAME */\n\n    editNameBtn.addEventListener('click',(e)=>{\n\n        e.stopPropagation();\n\n        nameInput.value =\n            recipientNameEl.textContent.trim();\n\n        nameModal.classList.add('open');\n\n        setTimeout(()=>{\n            nameInput.focus();\n        },50);\n    });\n\n    cancelModalBtn.addEventListener('click',(e)=>{\n\n        e.stopPropagation();\n\n        nameModal.classList.remove('open');\n    });\n\n    function applyNewName() {\n\n        const val = nameInput.value.trim();\n\n        if (val) {\n            recipientNameEl.textContent =\n                val.toUpperCase();\n        }\n\n        nameModal.classList.remove('open');\n\n        startAnimation();\n    }\n\n    saveNameBtn.addEventListener('click',(e)=>{\n        e.stopPropagation();\n        applyNewName();\n    });\n\n    nameInput.addEventListener('keydown',(e)=>{\n\n        if (e.key==='Enter') {\n            e.preventDefault();\n            applyNewName();\n        }\n    });\n\n    /* RESPONSIVE RESIZE */\n\n    let resizeTimer;\n\n    window.addEventListener('resize',()=>{\n\n        clearTimeout(resizeTimer);\n\n        resizeTimer = setTimeout(()=>{\n            resizeCanvas();\n        },150);\n    });\n\n    /* START */\n\n    window.onload = function () {\n        startAnimation();\n    };\n\n})();\n</script>\n\n<script>\n      setTimeout(() => parent.postMessage({type:\"birthday-reveal-next\"}, \"*\"), 14000);\n      document.addEventListener(\"click\", () => {\n        setTimeout(() => parent.postMessage({type:\"birthday-reveal-next\"}, \"*\"), 800);\n      }, {once:true, capture:true});\n    </script>\n</body>\n</html>", "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<title>Pop the balloons 🎈</title>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n<style>\n* {\n  box-sizing: border-box;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  min-height: 100dvh;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  background-color: #160f17;\n  color: #ffffff;\n  overflow-x: hidden;\n}\n\n.ambient-bg {\n  background:\n    radial-gradient(circle at 50% 44%, rgba(124,78,86,.52) 0%, rgba(74,46,54,.42) 38%, rgba(28,18,28,.92) 82%, #150e16 100%),\n    linear-gradient(180deg,#1b121c 0%,#3a242c 48%,#181019 100%);\n}\n\n.app-shell {\n  position: relative;\n  width: 100%;\n  max-width: 440px;\n  min-height: 100dvh;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  padding: 20px 18px 32px;\n  overflow: hidden;\n}\n\n#fx-canvas {\n  position: fixed;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  z-index: 40;\n}\n\n#dust-canvas {\n  position: fixed;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  z-index: 1;\n}\n\n.balloon-stage {\n  position: relative;\n  width: 100%;\n  height: 280px;\n  margin-top: 8px;\n  transition: height .55s cubic-bezier(.22,1,.36,1), opacity .4s ease;\n  z-index: 15;\n  flex-shrink: 0;\n}\n\n.balloon-item {\n  position: absolute;\n  cursor: pointer;\n  transform-origin: center bottom;\n  transition: transform .25s cubic-bezier(.34,1.56,.64,1), opacity .22s ease;\n  touch-action: manipulation;\n}\n\n.balloon-item:hover {\n  filter: brightness(1.06);\n}\n\n.balloon-item:active {\n  transform: scale(.94);\n}\n\n@keyframes floatSlow1 {\n  0%,100% { transform: translate3d(0,0,0) rotate(-1.5deg); }\n  50% { transform: translate3d(0,-10px,0) rotate(1.5deg); }\n}\n\n@keyframes floatSlow2 {\n  0%,100% { transform: translate3d(0,-4px,0) rotate(1.2deg); }\n  50% { transform: translate3d(0,8px,0) rotate(-1.8deg); }\n}\n\n@keyframes floatSlow3 {\n  0%,100% { transform: translate3d(0,2px,0) rotate(-1deg); }\n  50% { transform: translate3d(0,-9px,0) rotate(1.6deg); }\n}\n\n.float-1 { animation: floatSlow1 4.2s ease-in-out infinite; }\n.float-2 { animation: floatSlow2 4.7s ease-in-out infinite; }\n.float-3 { animation: floatSlow3 3.9s ease-in-out infinite; }\n.float-4 { animation: floatSlow2 4.5s ease-in-out infinite .5s; }\n.float-5 { animation: floatSlow1 4.3s ease-in-out infinite .8s; }\n\n@keyframes popOut {\n  0% { transform: scale(1); opacity: 1; }\n  45% { transform: scale(1.36); opacity: .85; }\n  100% { transform: scale(1.65); opacity: 0; }\n}\n\n.balloon-popping {\n  animation: popOut .24s cubic-bezier(.16,1,.3,1) forwards !important;\n  pointer-events: none;\n}\n\n.reason-card {\n  position: relative;\n  width: 100%;\n  border-radius: 14px;\n  background: linear-gradient(135deg,rgba(53,33,42,.82) 0%,rgba(39,24,32,.86) 100%);\n  border: 1px solid rgba(235,175,110,.44);\n  box-shadow: 0 8px 24px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,224,185,.14);\n  backdrop-filter: blur(10px);\n  -webkit-backdrop-filter: blur(10px);\n  padding: 13px 16px 14px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  opacity: 0;\n  transform: translateY(18px) scale(.97);\n  animation: cardReveal .48s cubic-bezier(.22,1,.36,1) forwards;\n}\n\n@keyframes cardReveal {\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}\n\n.reason-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 3px 9px;\n  border-radius: 999px;\n  background: rgba(255,130,130,.18);\n  border: 1px solid rgba(255,154,139,.25);\n  color: #ff9a8b;\n  font-size: 10.5px;\n  font-weight: 700;\n  letter-spacing: .04em;\n  text-transform: uppercase;\n  line-height: 1.2;\n  margin-bottom: 6px;\n}\n\n@keyframes sparklePulse {\n  0%,100% { transform: scale(1) rotate(0deg); opacity: .9; }\n  50% { transform: scale(1.18) rotate(8deg); opacity: 1; }\n}\n\n.card-sparkle {\n  font-size: 18px;\n  line-height: 1;\n  animation: sparklePulse 2.6s ease-in-out infinite;\n  flex-shrink: 0;\n}\n\n.keep-going-btn {\n  width: 100%;\n  border: none;\n  border-radius: 999px;\n  padding: 15px 24px;\n  background: linear-gradient(90deg,#ff9d6c 0%,#ff7b7b 100%);\n  color: #ffffff;\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: .01em;\n  box-shadow: 0 10px 26px rgba(255,126,118,.38), inset 0 1px 1px rgba(255,255,255,.35);\n  cursor: pointer;\n  transition: transform .2s cubic-bezier(.34,1.56,.64,1), box-shadow .2s ease, filter .2s ease;\n}\n\n.keep-going-btn:hover {\n  transform: translateY(-2px);\n  filter: brightness(1.05);\n  box-shadow: 0 14px 30px rgba(255,126,118,.48);\n}\n\n.keep-going-btn:active {\n  transform: scale(.97);\n}\n\n.top-icon-btn {\n  background: rgba(255,255,255,.08);\n  border: 1px solid rgba(255,255,255,.14);\n  color: #f3e6e9;\n  border-radius: 999px;\n  padding: 6px 11px;\n  font-size: 12px;\n  font-weight: 500;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  cursor: pointer;\n  transition: background .2s ease, transform .15s ease;\n  backdrop-filter: blur(6px);\n}\n\n.top-icon-btn:hover {\n  background: rgba(255,255,255,.15);\n}\n\n.top-icon-btn:active {\n  transform: scale(.95);\n}\n\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(14,9,15,.78);\n  backdrop-filter: blur(8px);\n  z-index: 60;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 18px;\n}\n</style>\n</head>\n\n<body class=\"ambient-bg\">\n\n<canvas id=\"dust-canvas\"></canvas>\n<canvas id=\"fx-canvas\"></canvas>\n\n<main class=\"app-shell\">\n\n<header class=\"relative z-20 flex items-center justify-between mb-3\">\n\n<button id=\"replay-btn\" class=\"top-icon-btn\" title=\"Reset balloons\">\n<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n<path d=\"M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8\"/>\n<path d=\"M3 3v5h5\"/>\n</svg>\n<span>Replay</span>\n</button>\n\n<div class=\"flex items-center gap-2\">\n\n<button id=\"sound-toggle-btn\" class=\"top-icon-btn\" title=\"Toggle pop sound\">\n<span id=\"sound-icon\">🔊</span>\n</button>\n\n<button id=\"edit-btn\" class=\"top-icon-btn\" title=\"Customize messages\">\n<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n<path d=\"M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z\"/>\n</svg>\n<span>Edit Text</span>\n</button>\n\n</div>\n</header>\n\n<section class=\"relative z-20 text-center px-1 mt-1\">\n<h1 id=\"page-title\" class=\"text-[25px] sm:text-[27px] font-bold tracking-tight text-white leading-snug\">\nPop the balloons 🎈\n</h1>\n\n<p id=\"page-subtitle\" class=\"text-[13.5px] sm:text-[14px] text-[#dfd0d4] mt-1.5 leading-relaxed font-normal\">\n5 balloons. Each one holds a reason you're loved. Pop them all 🎈\n</p>\n</section>\n\n<section id=\"balloon-stage\" class=\"balloon-stage\" aria-label=\"Interactive balloons\"></section>\n\n<section id=\"cards-container\" class=\"relative z-20 flex flex-col gap-3 w-full mt-1\" aria-live=\"polite\"></section>\n\n<section id=\"finale-section\" class=\"relative z-20 hidden flex-col items-center text-center mt-5 mb-2\">\n\n<p id=\"finale-caption\" class=\"text-[15.5px] italic font-medium text-[#f5d59c] tracking-wide mb-4 opacity-0 transition-opacity duration-500\">\n...and a thousand more reasons 💛\n</p>\n\n<button id=\"keep-going-btn\" class=\"keep-going-btn opacity-0 translate-y-3 transition-all duration-500\">\nKeep going 💛\n</button>\n\n</section>\n</main>\n\n<div id=\"edit-modal\" class=\"modal-backdrop hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modal-heading\">\n\n<div class=\"w-full max-w-[400px] rounded-2xl bg-[#271822] border border-[#ebb06e]/40 p-5 shadow-2xl text-white\">\n\n<div class=\"flex items-center justify-between mb-3\">\n<h2 id=\"modal-heading\" class=\"text-base font-semibold text-white\">Customize Messages ✨</h2>\n<button id=\"close-modal-btn\" class=\"text-white/60 hover:text-white text-lg px-2 py-0.5\">&times;</button>\n</div>\n\n<p class=\"text-xs text-[#d6c2c7] mb-3\">Edit any of the 5 romantic reasons below and tap Save:</p>\n\n<div id=\"edit-inputs-list\" class=\"flex flex-col gap-2.5 max-h-[52vh] overflow-y-auto pr-1\"></div>\n\n<div class=\"flex items-center justify-end gap-2 mt-4 pt-3 border-t border-white/10\">\n\n<button id=\"reset-defaults-btn\" class=\"px-3 py-2 rounded-xl text-xs font-medium text-[#e5cfd4] bg-white/10 hover:bg-white/15\">\nReset Default\n</button>\n\n<button id=\"save-text-btn\" class=\"px-4 py-2 rounded-xl text-xs font-semibold text-white bg-gradient-to-r from-[#ff9d6c] to-[#ff7b7b] shadow-md\">\nSave & Replay\n</button>\n\n</div>\n</div>\n</div><script>\n\nconst DEFAULT_REASONS = [\n  \"You make every day brighter ✨\",\n  \"My favorite person forever ❤️\",\n  \"Your smile melts my heart 🥰\",\n  \"I love you endlessly 💖\",\n  \"My soulmate & best friend 💕\"\n];\n\nlet reasons = (() => {\n  try {\n    const saved = localStorage.getItem('pop_balloons_custom_reasons');\n    if (saved) {\n      const parsed = JSON.parse(saved);\n      if (Array.isArray(parsed) && parsed.length === 5) return parsed;\n    }\n  } catch (e) {\n    console.warn('Storage unavailable, using defaults');\n  }\n  return [...DEFAULT_REASONS];\n})();\n\nconst BALLOON_CONFIGS = [\n  {\n    id: 'pink',\n    left: '4%',\n    top: '8px',\n    width: 82,\n    height: 102,\n    floatClass: 'float-1',\n    c1: '#ffd1dc',\n    c2: '#ff9eb5',\n    c3: '#e06380',\n    knot: '#d95876',\n    confettiColor: '#ff9eb5'\n  },\n  {\n    id: 'yellow',\n    left: '14%',\n    top: '116px',\n    width: 82,\n    height: 102,\n    floatClass: 'float-2',\n    c1: '#fff099',\n    c2: '#ffd24c',\n    c3: '#dfa01e',\n    knot: '#d19215',\n    confettiColor: '#ffd24c'\n  },\n  {\n    id: 'lavender',\n    left: '33%',\n    top: '68px',\n    width: 82,\n    height: 102,\n    floatClass: 'float-3',\n    c1: '#dfd6ff',\n    c2: '#b3a1ff',\n    c3: '#7a68d9',\n    knot: '#6c5ac9',\n    confettiColor: '#b3a1ff'\n  },\n  {\n    id: 'cyan',\n    left: '58%',\n    top: '2px',\n    width: 84,\n    height: 104,\n    floatClass: 'float-4',\n    c1: '#b8f3ff',\n    c2: '#56d4f5',\n    c3: '#1888b0',\n    knot: '#14799e',\n    confettiColor: '#56d4f5'\n  },\n  {\n    id: 'peach',\n    left: '72%',\n    top: '76px',\n    width: 82,\n    height: 102,\n    floatClass: 'float-5',\n    c1: '#ffd0ad',\n    c2: '#ff9c59',\n    c3: '#de6226',\n    knot: '#cc551c',\n    confettiColor: '#ff9c59'\n  }\n];\n\nclass BalloonSoundEngine {\n\n  constructor() {\n    this.ctx = null;\n    this.enabled = true;\n  }\n\n  init() {\n    if (!this.ctx) {\n      const AudioCtx = window.AudioContext || window.webkitAudioContext;\n      if (AudioCtx) this.ctx = new AudioCtx();\n    }\n\n    if (this.ctx && this.ctx.state === 'suspended') {\n      this.ctx.resume();\n    }\n  }\n\n  playPop() {\n    if (!this.enabled) return;\n\n    this.init();\n    if (!this.ctx) return;\n\n    const now = this.ctx.currentTime;\n\n    const bufferSize = Math.floor(this.ctx.sampleRate * 0.09);\n    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n    const output = noiseBuffer.getChannelData(0);\n\n    for (let i = 0; i < bufferSize; i++) {\n      const env = Math.pow(1 - i / bufferSize, 2.4);\n      output[i] = (Math.random() * 2 - 1) * env;\n    }\n\n    const whiteNoise = this.ctx.createBufferSource();\n    whiteNoise.buffer = noiseBuffer;\n\n    const bandpass = this.ctx.createBiquadFilter();\n    bandpass.type = 'bandpass';\n    bandpass.frequency.setValueAtTime(1150, now);\n    bandpass.frequency.exponentialRampToValueAtTime(320, now + 0.08);\n    bandpass.Q.value = 0.9;\n\n    const noiseGain = this.ctx.createGain();\n    noiseGain.gain.setValueAtTime(1.15, now);\n    noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.085);\n\n    whiteNoise.connect(bandpass);\n    bandpass.connect(noiseGain);\n    noiseGain.connect(this.ctx.destination);\n\n    whiteNoise.start(now);\n    whiteNoise.stop(now + 0.09);\n\n    const osc = this.ctx.createOscillator();\n    const oscGain = this.ctx.createGain();\n\n    osc.type = 'sine';\n    osc.frequency.setValueAtTime(210, now);\n    osc.frequency.exponentialRampToValueAtTime(42, now + 0.11);\n\n    oscGain.gain.setValueAtTime(0.85, now);\n    oscGain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);\n\n    osc.connect(oscGain);\n    oscGain.connect(this.ctx.destination);\n\n    osc.start(now);\n    osc.stop(now + 0.12);\n\n    const chime = this.ctx.createOscillator();\n    const chimeGain = this.ctx.createGain();\n\n    chime.type = 'triangle';\n    chime.frequency.setValueAtTime(880, now + 0.03);\n    chime.frequency.exponentialRampToValueAtTime(1320, now + 0.22);\n\n    chimeGain.gain.setValueAtTime(0.001, now);\n    chimeGain.gain.linearRampToValueAtTime(0.11, now + 0.045);\n    chimeGain.gain.exponentialRampToValueAtTime(0.001, now + 0.26);\n\n    chime.connect(chimeGain);\n    chimeGain.connect(this.ctx.destination);\n\n    chime.start(now + 0.02);\n    chime.stop(now + 0.27);\n  }\n\n  playCelebration() {\n    if (!this.enabled) return;\n\n    this.init();\n    if (!this.ctx) return;\n\n    const notes = [523.25, 659.25, 783.99, 1046.5];\n\n    notes.forEach((freq, idx) => {\n      const now = this.ctx.currentTime + idx * 0.065;\n\n      const osc = this.ctx.createOscillator();\n      const gain = this.ctx.createGain();\n\n      osc.type = 'sine';\n      osc.frequency.setValueAtTime(freq, now);\n\n      gain.gain.setValueAtTime(0.12, now);\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);\n\n      osc.connect(gain);\n      gain.connect(this.ctx.destination);\n\n      osc.start(now);\n      osc.stop(now + 0.36);\n    });\n  }\n}\n\nconst soundEngine = new BalloonSoundEngine();\n\nconst fxCanvas = document.getElementById('fx-canvas');\nconst fxCtx = fxCanvas.getContext('2d');\n\nconst dustCanvas = document.getElementById('dust-canvas');\nconst dustCtx = dustCanvas.getContext('2d');\n\nlet confettiParticles = [];\nlet dustParticles = [];\n\nfunction resizeCanvases() {\n  const dpr = Math.min(window.devicePixelRatio || 1, 2);\n\n  fxCanvas.width = window.innerWidth * dpr;\n  fxCanvas.height = window.innerHeight * dpr;\n  fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);\n\n  dustCanvas.width = window.innerWidth * dpr;\n  dustCanvas.height = window.innerHeight * dpr;\n  dustCtx.setTransform(dpr, 0, 0, dpr, 0, 0);\n}\n\nwindow.addEventListener('resize', resizeCanvases);\nresizeCanvases();\n\nfunction initDust() {\n  dustParticles = [];\n\n  const count = 42;\n\n  for (let i = 0; i < count; i++) {\n    dustParticles.push({\n      x: Math.random() * window.innerWidth,\n      y: Math.random() * window.innerHeight,\n      r: Math.random() * 1.6 + 0.5,\n      vy: -(Math.random() * 0.25 + 0.08),\n      vx: (Math.random() - 0.5) * 0.15,\n      alpha: Math.random() * 0.55 + 0.15,\n      twinkleSpeed: Math.random() * 0.02 + 0.008,\n      phase: Math.random() * Math.PI * 2\n    });\n  }\n}\n\ninitDust();\n\nconst CONFETTI_PALETTE = [\n  '#ff9eb5',\n  '#ffd24c',\n  '#b3a1ff',\n  '#56d4f5',\n  '#ff9c59',\n  '#ffffff',\n  '#ff758f',\n  '#ffe57f'\n];\n\nfunction spawnConfettiBurst(x, y, count = 44) {\n\n  for (let i = 0; i < count; i++) {\n\n    const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.45;\n    const speed = Math.random() * 6.5 + 2.4;\n\n    const shapes = ['circle', 'rect', 'ribbon'];\n    const shape = shapes[Math.floor(Math.random() * shapes.length)];\n\n    confettiParticles.push({\n      x,\n      y,\n      vx: Math.cos(angle) * speed,\n      vy: Math.sin(angle) * speed - 2.2,\n      size: Math.random() * 5 + 3.5,\n      color: CONFETTI_PALETTE[Math.floor(Math.random() * CONFETTI_PALETTE.length)],\n      shape,\n      rotation: Math.random() * 360,\n      vRot: (Math.random() - 0.5) * 14,\n      drag: 0.965,\n      gravity: 0.16,\n      alpha: 1,\n      decay: Math.random() * 0.012 + 0.009\n    });\n  }\n}\n\nfunction animateParticles() {\n\n  dustCtx.clearRect(0, 0, window.innerWidth, window.innerHeight);\n\n  for (const p of dustParticles) {\n\n    p.x += p.vx;\n    p.y += p.vy;\n    p.phase += p.twinkleSpeed;\n\n    if (p.y < -10) {\n      p.y = window.innerHeight + 10;\n      p.x = Math.random() * window.innerWidth;\n    }\n\n    if (p.x < -10) p.x = window.innerWidth + 10;\n    if (p.x > window.innerWidth + 10) p.x = -10;\n\n    const currentAlpha = p.alpha * (0.65 + 0.35 * Math.sin(p.phase));\n\n    dustCtx.beginPath();\n    dustCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);\n    dustCtx.fillStyle = `rgba(255,236,210,${currentAlpha.toFixed(3)})`;\n    dustCtx.fill();\n  }\n\n  fxCtx.clearRect(0, 0, window.innerWidth, window.innerHeight);\n\n  for (let i = confettiParticles.length - 1; i >= 0; i--) {\n\n    const c = confettiParticles[i];\n\n    c.vx *= c.drag;\n    c.vy = c.vy * c.drag + c.gravity;\n\n    c.x += c.vx;\n    c.y += c.vy;\n\n    c.rotation += c.vRot;\n    c.alpha -= c.decay;\n\n    if (c.alpha <= 0 || c.y > window.innerHeight + 30) {\n      confettiParticles.splice(i, 1);\n      continue;\n    }\n\n    fxCtx.save();\n\n    fxCtx.globalAlpha = Math.max(0, c.alpha);\n    fxCtx.translate(c.x, c.y);\n    fxCtx.rotate((c.rotation * Math.PI) / 180);\n    fxCtx.fillStyle = c.color;\n\n    if (c.shape === 'circle') {\n      fxCtx.beginPath();\n      fxCtx.arc(0, 0, c.size * 0.55, 0, Math.PI * 2);\n      fxCtx.fill();\n    } else if (c.shape === 'rect') {\n      fxCtx.fillRect(-c.size * 0.5, -c.size * 0.5, c.size, c.size * 0.7);\n    } else {\n      fxCtx.fillRect(-c.size * 0.7, -c.size * 0.25, c.size * 1.4, c.size * 0.45);\n    }\n\n    fxCtx.restore();\n  }\n\n  requestAnimationFrame(animateParticles);\n}const balloonStage = document.getElementById('balloon-stage');\nconst cardsContainer = document.getElementById('cards-container');\nconst finaleSection = document.getElementById('finale-section');\nconst finaleCaption = document.getElementById('finale-caption');\nconst keepGoingBtn = document.getElementById('keep-going-btn');\n\nlet poppedCount = 0;\nlet remainingIds = new Set();\n\nfunction createBalloonSVG(cfg) {\n\n  const gradId = `grad-${cfg.id}`;\n  const shineId = `shine-${cfg.id}`;\n\n  return `\n    <svg width=\"${cfg.width}\" height=\"${cfg.height + 54}\" viewBox=\"0 0 100 168\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"overflow:visible;display:block;\">\n\n      <defs>\n        <radialGradient id=\"${gradId}\" cx=\"34%\" cy=\"28%\" r=\"68%\" fx=\"30%\" fy=\"24%\">\n          <stop offset=\"0%\" stop-color=\"${cfg.c1}\"/>\n          <stop offset=\"48%\" stop-color=\"${cfg.c2}\"/>\n          <stop offset=\"100%\" stop-color=\"${cfg.c3}\"/>\n        </radialGradient>\n\n        <radialGradient id=\"${shineId}\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n          <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"0.72\"/>\n          <stop offset=\"100%\" stop-color=\"#ffffff\" stop-opacity=\"0\"/>\n        </radialGradient>\n      </defs>\n\n      <path d=\"M50 112 Q48 134 51 164\" stroke=\"rgba(255,245,240,.42)\" stroke-width=\"1.35\" stroke-linecap=\"round\" fill=\"none\"/>\n\n      <path d=\"M46 108 L54 108 L52 114 L48 114 Z\" fill=\"${cfg.knot}\"/>\n\n      <path d=\"M50 4 C76 4 94 25 94 53 C94 82 72 103 50 109 C28 103 6 82 6 53 C6 25 24 4 50 4 Z\"\n            fill=\"url(#${gradId})\"/>\n\n      <ellipse cx=\"31\" cy=\"31\" rx=\"11\" ry=\"18\" transform=\"rotate(-24 31 31)\" fill=\"url(#${shineId})\"/>\n\n      <circle cx=\"24\" cy=\"49\" r=\"3.2\" fill=\"rgba(255,255,255,.45)\"/>\n\n    </svg>\n  `;\n}\n\nfunction updateStageLayout() {\n\n  if (remainingIds.size === 0) {\n    balloonStage.style.height = '0px';\n    balloonStage.style.marginTop = '0px';\n    balloonStage.style.opacity = '0';\n    balloonStage.style.pointerEvents = 'none';\n    return;\n  }\n\n  let maxBottom = 145;\n\n  BALLOON_CONFIGS.forEach(cfg => {\n\n    if (remainingIds.has(cfg.id)) {\n\n      const topVal = parseInt(cfg.top, 10) || 0;\n      const bottomEstimate = topVal + cfg.height + 42;\n\n      if (bottomEstimate > maxBottom) {\n        maxBottom = bottomEstimate;\n      }\n    }\n  });\n\n  balloonStage.style.height = `${Math.min(maxBottom,272)}px`;\n  balloonStage.style.marginTop = '8px';\n  balloonStage.style.opacity = '1';\n  balloonStage.style.pointerEvents = 'auto';\n}\n\nfunction revealNextReasonCard(index) {\n\n  const reasonNumber = index + 1;\n  const text = reasons[index] || DEFAULT_REASONS[index];\n\n  const card = document.createElement('article');\n  card.className = 'reason-card';\n\n  card.innerHTML = `\n    <div class=\"flex flex-col items-start text-left min-w-0\">\n\n      <span class=\"reason-badge\">\n        REASON NO.${reasonNumber} ❤️\n      </span>\n\n      <p class=\"text-[15.5px] sm:text-[16.5px] font-medium text-white leading-snug break-words\">\n        ${escapeHTML(text)}\n      </p>\n\n    </div>\n\n    <span class=\"card-sparkle\" aria-hidden=\"true\">✨</span>\n  `;\n\n  cardsContainer.appendChild(card);\n}\n\nfunction escapeHTML(str) {\n  const div = document.createElement('div');\n  div.textContent = str;\n  return div.innerHTML;\n}\n\nfunction triggerFinale() {\n\n  finaleSection.classList.remove('hidden');\n  finaleSection.classList.add('flex');\n\n  requestAnimationFrame(() => {\n\n    setTimeout(() => {\n      finaleCaption.classList.remove('opacity-0');\n    }, 180);\n\n    setTimeout(() => {\n      keepGoingBtn.classList.remove('opacity-0', 'translate-y-3');\n    }, 360);\n\n  });\n}\n\nfunction handleBalloonPop(cfg, el) {\n\n  if (!remainingIds.has(cfg.id)) return;\n\n  remainingIds.delete(cfg.id);\n\n  soundEngine.playPop();\n\n  const rect = el.getBoundingClientRect();\n\n  const centerX = rect.left + rect.width / 2;\n  const centerY = rect.top + rect.height * 0.38;\n\n  spawnConfettiBurst(centerX, centerY, 46);\n\n  el.classList.add('balloon-popping');\n\n  setTimeout(() => {\n    el.remove();\n    updateStageLayout();\n  }, 230);\n\n  const currentIndex = poppedCount;\n\n  poppedCount += 1;\n\n  revealNextReasonCard(currentIndex);\n\n  if (poppedCount === BALLOON_CONFIGS.length) {\n    setTimeout(triggerFinale, 350);\n  }\n}\n\nfunction initExperience() {\n\n  poppedCount = 0;\n\n  remainingIds = new Set(BALLOON_CONFIGS.map(b => b.id));\n\n  balloonStage.innerHTML = '';\n  cardsContainer.innerHTML = '';\n\n  finaleSection.classList.add('hidden');\n  finaleSection.classList.remove('flex');\n\n  finaleCaption.classList.add('opacity-0');\n\n  keepGoingBtn.classList.add('opacity-0', 'translate-y-3');\n  keepGoingBtn.disabled = false;\n  keepGoingBtn.textContent = 'Keep going 💛';\n\n  BALLOON_CONFIGS.forEach(cfg => {\n\n    const el = document.createElement('div');\n\n    el.className = `balloon-item ${cfg.floatClass}`;\n\n    el.style.left = cfg.left;\n    el.style.top = cfg.top;\n\n    el.setAttribute('role', 'button');\n    el.setAttribute('tabindex', '0');\n    el.setAttribute('aria-label', `Pop ${cfg.id} balloon`);\n\n    el.innerHTML = createBalloonSVG(cfg);\n\n    el.addEventListener('click', () => {\n      handleBalloonPop(cfg, el);\n    });\n\n    el.addEventListener('keydown', e => {\n\n      if (e.key === 'Enter' || e.key === ' ') {\n        e.preventDefault();\n        handleBalloonPop(cfg, el);\n      }\n\n    });\n\n    balloonStage.appendChild(el);\n  });\n\n  updateStageLayout();\n}\n\nconst replayBtn = document.getElementById('replay-btn');\nconst soundToggleBtn = document.getElementById('sound-toggle-btn');\nconst soundIcon = document.getElementById('sound-icon');\n\nconst editBtn = document.getElementById('edit-btn');\nconst editModal = document.getElementById('edit-modal');\n\nconst closeModalBtn = document.getElementById('close-modal-btn');\nconst editInputsList = document.getElementById('edit-inputs-list');\n\nconst saveTextBtn = document.getElementById('save-text-btn');\nconst resetDefaultsBtn = document.getElementById('reset-defaults-btn');\n\nreplayBtn.addEventListener('click', () => {\n  initExperience();\n});\n\nsoundToggleBtn.addEventListener('click', () => {\n\n  soundEngine.enabled = !soundEngine.enabled;\n\n  soundIcon.textContent = soundEngine.enabled ? '🔊' : '🔇';\n\n  if (soundEngine.enabled) {\n    soundEngine.init();\n  }\n\n});\n\n/* =========================================\n   NEXT PAGE NAVIGATION\n   Filename can be changed later.\n========================================= */\n\nconst NEXT_PAGE_URL = 'next-page.html';\n\nkeepGoingBtn.addEventListener('click', e => {\n\n  if (keepGoingBtn.disabled) return;\n\n  soundEngine.playCelebration();\n\n  const rect = e.currentTarget.getBoundingClientRect();\n\n  spawnConfettiBurst(rect.left + rect.width * 0.25, rect.top, 45);\n  spawnConfettiBurst(rect.left + rect.width * 0.75, rect.top, 45);\n\n  keepGoingBtn.disabled = true;\n  keepGoingBtn.textContent = 'Going... 💛';\n\n  setTimeout(() => {\n    window.parent.postMessage({ type: \"birthday-next\" }, \"*\");\n  }, 450);\n\n});\n\n/* =========================================\n   EDIT TEXT MODAL\n========================================= */\n\neditBtn.addEventListener('click', () => {\n\n  editInputsList.innerHTML = '';\n\n  reasons.forEach((msg, idx) => {\n\n    const wrapper = document.createElement('div');\n\n    wrapper.innerHTML = `\n      <label class=\"block text-[11px] font-semibold uppercase tracking-wider text-[#ff9a8b] mb-1\">\n        Reason No.${idx + 1}\n      </label>\n\n      <input\n        type=\"text\"\n        data-reason-idx=\"${idx}\"\n        value=\"${escapeHTML(msg)}\"\n        maxlength=\"70\"\n        class=\"w-full rounded-xl bg-white/10 border border-white/15 px-3 py-2 text-sm text-white placeholder-white/40 focus:outline-none focus:border-[#ff9d6c]\"\n      />\n    `;\n\n    editInputsList.appendChild(wrapper);\n\n  });\n\n  editModal.classList.remove('hidden');\n});\n\ncloseModalBtn.addEventListener('click', () => {\n  editModal.classList.add('hidden');\n});\n\neditModal.addEventListener('click', e => {\n\n  if (e.target === editModal) {\n    editModal.classList.add('hidden');\n  }\n\n});\n\nsaveTextBtn.addEventListener('click', () => {\n\n  const inputs = editInputsList.querySelectorAll('input[data-reason-idx]');\n\n  const updated = [];\n\n  inputs.forEach((inp, idx) => {\n\n    const val = inp.value.trim();\n\n    updated.push(val || DEFAULT_REASONS[idx]);\n\n  });\n\n  reasons = updated;\n\n  try {\n    localStorage.setItem('pop_balloons_custom_reasons', JSON.stringify(reasons));\n  } catch (e) {}\n\n  editModal.classList.add('hidden');\n\n  initExperience();\n});\n\nresetDefaultsBtn.addEventListener('click', () => {\n\n  reasons = [...DEFAULT_REASONS];\n\n  try {\n    localStorage.removeItem('pop_balloons_custom_reasons');\n  } catch (e) {}\n\n  const inputs = editInputsList.querySelectorAll('input[data-reason-idx]');\n\n  inputs.forEach((inp, idx) => {\n    inp.value = DEFAULT_REASONS[idx];\n  });\n\n});\n\nwindow.onload = function () {\n  animateParticles();\n  initExperience();\n};\n\n</script>\n<script>\n      // Navigation is connected to the combined sequence in the original button handler.\n    </script>\n</body>\n</html>", "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#180d29\">\n  <title>Happy Birthday Shivani ❤️</title>\n  </head>\n\n<body>\n\n  <div class=\"stars\" id=\"stars\"></div>\n  <div class=\"glow-bg\"></div>\n\n  <main class=\"birthday-page\" id=\"birthdayPage\">\n\n    <!-- INTRO -->\n    <header class=\"intro\">\n      <p class=\"intro-title\">A LITTLE SOMETHING FOR YOU</p>\n      <p class=\"intro-subtitle\">Made with Aniket ❤️</p>\n    </header>\n\n    <!-- CAKE -->\n    <section class=\"cake-section\">\n\n      <svg class=\"cake-svg\"\n           viewBox=\"0 0 420 330\"\n           xmlns=\"http://www.w3.org/2000/svg\">\n\n        <defs>\n\n          <linearGradient id=\"bottomPink\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0%\" stop-color=\"#ffc3d8\"/>\n            <stop offset=\"55%\" stop-color=\"#f58bad\"/>\n            <stop offset=\"100%\" stop-color=\"#e96d98\"/>\n          </linearGradient>\n\n          <linearGradient id=\"middlePink\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0%\" stop-color=\"#ffd0e1\"/>\n            <stop offset=\"55%\" stop-color=\"#f99ab9\"/>\n            <stop offset=\"100%\" stop-color=\"#ed7fa7\"/>\n          </linearGradient>\n\n          <linearGradient id=\"topPink\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0%\" stop-color=\"#ffe0eb\"/>\n            <stop offset=\"100%\" stop-color=\"#f39bb8\"/>\n          </linearGradient>\n\n          <linearGradient id=\"cream\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n            <stop offset=\"100%\" stop-color=\"#ffd8e8\"/>\n          </linearGradient>\n\n          <linearGradient id=\"candle\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n            <stop offset=\"0%\" stop-color=\"#ffe3eb\"/>\n            <stop offset=\"50%\" stop-color=\"#ffffff\"/>\n            <stop offset=\"100%\" stop-color=\"#ffc2d5\"/>\n          </linearGradient>\n\n          <radialGradient id=\"flameColor\">\n            <stop offset=\"0%\" stop-color=\"#fff9bd\"/>\n            <stop offset=\"45%\" stop-color=\"#ffcf42\"/>\n            <stop offset=\"100%\" stop-color=\"#ff8b22\"/>\n          </radialGradient>\n\n          <filter id=\"glow\" x=\"-150%\" y=\"-150%\" width=\"400%\" height=\"400%\">\n            <feGaussianBlur stdDeviation=\"9\"/>\n          </filter>\n\n        </defs>\n\n        <!-- PLATE -->\n        <g class=\"plate-build\">\n          <ellipse cx=\"210\" cy=\"286\" rx=\"175\" ry=\"8\" fill=\"#fff5fa\"/>\n          <ellipse cx=\"210\" cy=\"284\" rx=\"163\" ry=\"3\"\n                   fill=\"#ffffff\" opacity=\".7\"/>\n        </g>\n\n        <!-- BOTTOM LAYER -->\n        <g class=\"layer-bottom\">\n          <rect x=\"65\" y=\"218\" width=\"290\" height=\"60\"\n                rx=\"13\" fill=\"url(#bottomPink)\"/>\n        </g>\n\n        <!-- MIDDLE LAYER -->\n        <g class=\"layer-middle\">\n          <rect x=\"83\" y=\"163\" width=\"254\" height=\"60\"\n                rx=\"11\" fill=\"url(#middlePink)\"/>\n        </g>\n\n        <!-- TOP LAYER -->\n        <g class=\"layer-top\">\n          <rect x=\"103\" y=\"119\" width=\"214\" height=\"50\"\n                rx=\"10\" fill=\"url(#topPink)\"/>\n        </g>\n\n        <!-- TOP CREAM AND DRIPS -->\n        <g class=\"cream-build\">\n\n          <path d=\"\n            M98 123\n            C98 109 112 103 130 106\n            C153 101 174 106 193 104\n            C215 102 239 104 260 104\n            C282 102 307 105 322 111\n            C335 117 330 131 326 144\n\n            L324 170\n            C323 184 310 188 305 174\n            L296 145\n            C292 132 282 133 276 145\n            L264 166\n            C256 180 243 178 239 164\n            L232 140\n            C228 127 216 127 211 141\n            L204 174\n            C200 190 186 190 181 175\n            L172 140\n            C168 127 156 129 151 143\n            L140 168\n            C134 181 121 179 117 166\n            L110 141\n            C107 132 101 135 98 143\n            Z\"\n            fill=\"url(#cream)\"/>\n\n          <path d=\"M110 113 Q210 99 315 113\"\n                fill=\"none\"\n                stroke=\"#ffffff\"\n                stroke-width=\"3\"\n                opacity=\".6\"/>\n\n        </g>\n\n        <!-- CANDLE -->\n        <g class=\"candle-build\">\n\n          <rect x=\"202\" y=\"43\" width=\"16\" height=\"65\"\n                rx=\"4\" fill=\"url(#candle)\"/>\n\n          <path d=\"M202 57 H218 V66 H202Z\" fill=\"#f18eaf\"/>\n          <path d=\"M202 77 H218 V86 H202Z\" fill=\"#f18eaf\"/>\n          <path d=\"M202 97 H218 V105 H202Z\" fill=\"#f18eaf\"/>\n\n          <path d=\"M210 44 V37\"\n                stroke=\"#4b2934\"\n                stroke-width=\"2\"\n                stroke-linecap=\"round\"/>\n\n        </g>\n\n        <!-- FLAME -->\n        <g id=\"flameGroup\" class=\"flame-build\">\n\n          <ellipse class=\"flame-glow\"\n                   cx=\"210\" cy=\"24\"\n                   rx=\"22\" ry=\"29\"\n                   fill=\"#ffae32\"\n                   filter=\"url(#glow)\"/>\n\n          <g class=\"flame\" id=\"flame\">\n\n            <path d=\"\n              M210 39\n              C190 24 202 5 210 -5\n              C218 8 232 25 210 39Z\"\n              fill=\"url(#flameColor)\"/>\n\n            <path d=\"\n              M210 33\n              C203 25 208 15 211 10\n              C219 23 216 30 210 33Z\"\n              fill=\"#fff8bf\"/>\n\n          </g>\n        </g>\n\n        <!-- SMOKE -->\n        <g class=\"smoke\" id=\"smoke\">\n\n          <path class=\"smoke-one\"\n                d=\"M210 38 C193 22 225 15 210 -4\"\n                fill=\"none\"\n                stroke=\"#eee1ed\"\n                stroke-width=\"3.5\"\n                stroke-linecap=\"round\"/>\n\n          <path class=\"smoke-two\"\n                d=\"M210 38 C226 22 194 15 210 -4\"\n                fill=\"none\"\n                stroke=\"#eee1ed\"\n                stroke-width=\"3\"\n                stroke-linecap=\"round\"/>\n\n        </g>\n\n      </svg>\n\n    </section>\n\n    <!-- PARTICLES -->\n    <div class=\"particle-container\" id=\"particleContainer\"></div>\n\n    <!-- BIRTHDAY TEXT -->\n    <section class=\"birthday-content\" id=\"birthdayContent\">\n\n      <h1 id=\"birthdayHeading\"></h1>\n\n      <p class=\"wish-text\" id=\"wishText\">\n        Make a wish 🕯️\n      </p>\n\n      <button class=\"wish-button\" id=\"wishButton\">\n        Make a Wish ❤️\n      </button>\n\n    </section>\n\n    <!-- AFTER WISH -->\n    <section class=\"after-wish\" id=\"afterWish\">\n\n      <h2>Your wish is on its way! ❤️</h2>\n\n      <p>Keep smiling, Shivani ✨</p>\n\n      <button class=\"continue-button\" id=\"continueButton\">\n        Continue →\n      </button>\n\n    </section>\n\n  </main>\n\n  <!-- NEXT PAGE -->\n  <main class=\"next-page\" id=\"nextPage\" hidden>\n  </main>\n\n  <div class=\"heart-container\" id=\"heartContainer\"></div>\n\n  <script>\n      // Navigation is connected to the combined sequence in the original button handler.\n    </script>\n</body>\n</html>\n<style>\n/* =====================================\n   RESET\n===================================== */\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nhtml {\n  min-height: 100%;\n  background: #180d29;\n}\n\nbody {\n  min-height: 100vh;\n  min-height: 100svh;\n  overflow-x: hidden;\n\n  font-family: Georgia, \"Times New Roman\", serif;\n\n  background:\n    radial-gradient(\n      ellipse at 50% 45%,\n      #352044 0%,\n      #251533 48%,\n      #130b20 100%\n    );\n\n  color: white;\n}\n\n/* =====================================\n   BACKGROUND\n===================================== */\n\n.glow-bg {\n  position: fixed;\n  inset: 0;\n  background: radial-gradient(\n    circle at 50% 50%,\n    rgba(130,65,117,.13),\n    transparent 65%\n  );\n  pointer-events: none;\n  z-index: 0;\n}\n\n.stars {\n  position: fixed;\n  inset: 0;\n  overflow: hidden;\n  pointer-events: none;\n  z-index: 0;\n}\n\n.star {\n  position: absolute;\n  background: #fff;\n  border-radius: 50%;\n\n  box-shadow:\n    0 0 5px rgba(255,255,255,.8),\n    0 0 12px rgba(255,255,255,.3);\n\n  animation:\n    starTwinkle var(--duration) ease-in-out infinite alternate;\n}\n\n@keyframes starTwinkle {\n  from {\n    opacity: .15;\n    transform: scale(.65);\n  }\n\n  to {\n    opacity: 1;\n    transform: scale(1.35);\n  }\n}\n\n/* =====================================\n   MAIN\n===================================== */\n\n.birthday-page {\n  width: 100%;\n  min-height: 100vh;\n  min-height: 100svh;\n\n  padding: 48px 15px 35px;\n\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n\n  position: relative;\n  z-index: 2;\n\n  transition: opacity .6s ease;\n}\n\n.birthday-page.page-hidden {\n  opacity: 0;\n  pointer-events: none;\n}\n\n/* =====================================\n   INTRO\n===================================== */\n\n.intro {\n  width: 100%;\n  text-align: center;\n  margin-top: 8px;\n\n  opacity: 0;\n  animation: introAppear 1s .2s ease forwards;\n}\n\n.intro-title {\n  color: #ffe3a8;\n  font-size: clamp(13px, 3.7vw, 21px);\n  letter-spacing: 5px;\n  line-height: 1.7;\n  white-space: nowrap;\n}\n\n.intro-subtitle {\n  color: #ffe3b6;\n  font-size: clamp(15px, 4vw, 22px);\n  letter-spacing: 4px;\n  margin-top: 5px;\n}\n\n@keyframes introAppear {\n  to { opacity: 1; }\n}\n\n/* =====================================\n   CAKE\n===================================== */\n\n.cake-section {\n  width: min(380px, 94vw);\n  margin-top: auto;\n  margin-bottom: auto;\n\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.cake-svg {\n  width: 100%;\n  height: auto;\n  overflow: visible;\n}\n\n/* PLATE SLIDES FROM LEFT */\n\n.plate-build {\n  opacity: 0;\n  transform: translateX(-450px);\n\n  animation: plateSlide 1s .8s cubic-bezier(.2,.8,.3,1) forwards;\n}\n\n@keyframes plateSlide {\n  0% {\n    opacity: 0;\n    transform: translateX(-450px);\n  }\n\n  75% {\n    opacity: 1;\n    transform: translateX(12px);\n  }\n\n  100% {\n    opacity: 1;\n    transform: translateX(0);\n  }\n}\n\n/* LAYER DROP */\n\n.layer-bottom,\n.layer-middle,\n.layer-top {\n  opacity: 0;\n  transform: translateY(-400px);\n  transform-box: view-box;\n}\n\n.layer-bottom {\n  animation: layerDrop .85s 1.9s cubic-bezier(.2,.75,.3,1) forwards;\n}\n\n.layer-middle {\n  animation: layerDrop .85s 2.9s cubic-bezier(.2,.75,.3,1) forwards;\n}\n\n.layer-top {\n  animation: layerDrop .85s 3.9s cubic-bezier(.2,.75,.3,1) forwards;\n}\n\n@keyframes layerDrop {\n  0% {\n    opacity: 0;\n    transform: translateY(-400px);\n  }\n\n  72% {\n    opacity: 1;\n    transform: translateY(12px);\n  }\n\n  86% {\n    transform: translateY(-5px);\n  }\n\n  100% {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* CREAM DROP */\n\n.cream-build {\n  opacity: 0;\n  transform: translateY(-180px);\n  transform-box: view-box;\n  transform-origin: center top;\n\n  animation: creamDrop 1.1s 4.85s cubic-bezier(.2,.8,.3,1) forwards;\n}\n\n@keyframes creamDrop {\n  0% {\n    opacity: 0;\n    transform: translateY(-180px) scaleY(.5);\n  }\n\n  70% {\n    opacity: 1;\n    transform: translateY(8px) scaleY(1.05);\n  }\n\n  85% {\n    transform: translateY(-3px) scaleY(.98);\n  }\n\n  100% {\n    opacity: 1;\n    transform: translateY(0) scaleY(1);\n  }\n}\n\n/* CANDLE RISES FROM CAKE */\n\n.candle-build {\n  opacity: 0;\n  transform: translateY(75px);\n\n  animation: candleRise 1s 5.95s cubic-bezier(.2,.8,.3,1) forwards;\n}\n\n@keyframes candleRise {\n  0% {\n    opacity: 0;\n    transform: translateY(75px);\n  }\n\n  75% {\n    opacity: 1;\n    transform: translateY(-5px);\n  }\n\n  100% {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* FLAME APPEARS */\n\n.flame-build {\n  opacity: 0;\n  transform: scale(.2);\n  transform-box: fill-box;\n  transform-origin: center bottom;\n\n  animation: flameAppear .7s 6.85s ease-out forwards;\n}\n\n@keyframes flameAppear {\n  0% {\n    opacity: 0;\n    transform: scale(.2);\n  }\n\n  70% {\n    opacity: 1;\n    transform: scale(1.15);\n  }\n\n  100% {\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n\n/* FLAME FLICKER */\n\n.flame {\n  transform-origin: 210px 22px;\n  animation: flameMove .75s ease-in-out infinite alternate;\n}\n\n@keyframes flameMove {\n  from { transform: rotate(-5deg) scale(.95); }\n  to { transform: rotate(5deg) scale(1.08); }\n}\n\n.flame-glow {\n  animation: flameGlow 1.2s infinite alternate;\n}\n\n@keyframes flameGlow {\n  from { opacity: .35; }\n  to { opacity: .9; }\n}\n\n/* =====================================\n   FLAME EXTINGUISH\n===================================== */\n\nbody.candle-out .flame,\nbody.candle-out .flame-glow {\n  opacity: 0;\n  animation: none;\n}\n\n/* =====================================\n   SMOKE\n===================================== */\n\n.smoke {\n  opacity: 0;\n  pointer-events: none;\n}\n\n.smoke path {\n  stroke-dasharray: 60;\n  stroke-dashoffset: 60;\n  opacity: 0;\n}\n\nbody.candle-out .smoke {\n  opacity: 1;\n}\n\nbody.candle-out .smoke-one {\n  animation: smokeRise 2.5s ease-out forwards;\n}\n\nbody.candle-out .smoke-two {\n  animation: smokeRise 2.8s .15s ease-out forwards;\n}\n\n@keyframes smokeRise {\n  0% {\n    stroke-dashoffset: 60;\n    opacity: 0;\n    transform: translateY(8px);\n  }\n\n  20% { opacity: .7; }\n\n  100% {\n    stroke-dashoffset: 0;\n    opacity: 0;\n    transform: translateY(-25px);\n  }\n}\n\n/* =====================================\n   BIRTHDAY TEXT\n===================================== */\n\n.birthday-content {\n  width: 100%;\n  text-align: center;\n  margin-bottom: 8px;\n\n  opacity: 0;\n  animation: contentAppear .8s 7.2s ease forwards;\n}\n\n@keyframes contentAppear {\n  to { opacity: 1; }\n}\n\n.birthday-content h1 {\n  min-height: 1.25em;\n\n  color: #ffdc88;\n  font-size: clamp(25px, 6.1vw, 42px);\n  font-weight: bold;\n  white-space: nowrap;\n\n  text-shadow:\n    0 0 8px rgba(255,185,93,.35),\n    0 0 22px rgba(255,185,93,.15);\n}\n\n.birthday-content h1::after {\n  content: \"|\";\n  margin-left: 3px;\n  animation: cursorBlink .7s infinite;\n}\n\n.birthday-content h1.typing-done::after {\n  display: none;\n}\n\n@keyframes cursorBlink {\n  50% { opacity: 0; }\n}\n\n.wish-text {\n  font-size: clamp(19px, 4.8vw, 27px);\n  color: #fce5f2;\n  margin-top: 24px;\n\n  opacity: 0;\n  transition: opacity .6s;\n}\n\n.wish-text.visible {\n  opacity: 1;\n}\n\n/* =====================================\n   BUTTONS\n===================================== */\n\n.wish-button,\n.continue-button {\n  padding: 17px 40px;\n\n  border: 1.5px solid #ff9bc6;\n  border-radius: 60px;\n\n  background: rgba(255,169,209,.06);\n  color: white;\n\n  font-family: inherit;\n  font-size: 17px;\n  font-weight: bold;\n\n  cursor: pointer;\n\n  box-shadow:\n    0 0 12px rgba(255,116,178,.12),\n    inset 0 0 12px rgba(255,116,178,.05);\n\n  transition: all .35s ease;\n}\n\n.wish-button {\n  margin-top: 27px;\n  opacity: 0;\n  visibility: hidden;\n}\n\n.wish-button.visible {\n  opacity: 1;\n  visibility: visible;\n  animation: buttonAppear .8s ease both;\n}\n\n@keyframes buttonAppear {\n  from {\n    opacity: 0;\n    transform: translateY(15px);\n  }\n\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n.wish-button:hover,\n.continue-button:hover {\n  background: rgba(255,169,209,.16);\n  box-shadow: 0 0 25px rgba(255,116,178,.4);\n}\n\n.wish-button:active,\n.continue-button:active {\n  transform: scale(.94);\n}\n\n/* =====================================\n   PARTICLES - ONLY ON CLICK\n===================================== */\n\n.particle-container {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  overflow: hidden;\n  z-index: 5;\n}\n\n.confetti {\n  position: absolute;\n  width: var(--size);\n  height: var(--size);\n\n  background: var(--particle-color);\n  border-radius: var(--particle-radius);\n\n  animation: particleBurst var(--particle-time) ease-out forwards;\n}\n\n@keyframes particleBurst {\n  0% {\n    opacity: 0;\n    transform: translate(0,0) scale(.3);\n  }\n\n  12% { opacity: 1; }\n\n  100% {\n    opacity: 0;\n    transform:\n      translate(var(--move-x),var(--move-y))\n      rotate(var(--rotation))\n      scale(.7);\n  }\n}\n\n/* =====================================\n   AFTER WISH\n===================================== */\n\n.after-wish {\n  display: none;\n  width: 100%;\n  text-align: center;\n  margin-bottom: 12px;\n}\n\n.after-wish.show {\n  display: block;\n  animation: messageAppear 1s ease both;\n}\n\n.after-wish h2 {\n  color: #ffdc88;\n  font-size: clamp(23px, 5.5vw, 37px);\n}\n\n.after-wish p {\n  color: #ffe3ef;\n  font-size: clamp(19px, 4.8vw, 27px);\n  margin-top: 15px;\n}\n\n@keyframes messageAppear {\n  from {\n    opacity: 0;\n    transform: translateY(18px);\n  }\n\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* CONTINUE */\n\n.continue-button {\n  display: block;\n  margin: 30px auto 0;\n\n  opacity: 0;\n  visibility: hidden;\n}\n\n.continue-button.visible {\n  opacity: 1;\n  visibility: visible;\n  animation: buttonAppear .8s ease both;\n}\n\n/* =====================================\n   HEARTS\n===================================== */\n\n.heart-container {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  overflow: hidden;\n  z-index: 10;\n}\n\n.floating-heart {\n  position: absolute;\n  bottom: -30px;\n\n  animation: heartFly var(--heart-duration) ease-out forwards;\n}\n\n@keyframes heartFly {\n  0% {\n    transform: translateY(0) scale(.5);\n    opacity: 0;\n  }\n\n  15% { opacity: 1; }\n\n  100% {\n    transform: translateY(-110vh) rotate(360deg) scale(1.4);\n    opacity: 0;\n  }\n}\n\n/* =====================================\n   NEXT PAGE\n===================================== */\n\n.next-page {\n  position: fixed;\n  inset: 0;\n  z-index: 20;\n  min-height: 100vh;\n  min-height: 100svh;\n\n  background:\n    radial-gradient(\n      ellipse at 50% 45%,\n      #352044 0%,\n      #251533 48%,\n      #130b20 100%\n    );\n}\n\n/* =====================================\n   MOBILE\n===================================== */\n\n@media (max-width: 480px) {\n\n  .birthday-page {\n    padding: 48px 10px 30px;\n  }\n\n  .intro-title {\n    letter-spacing: 3px;\n  }\n\n  .intro-subtitle {\n    letter-spacing: 3px;\n  }\n\n  .cake-section {\n    width: min(360px, 94vw);\n  }\n\n  .birthday-content h1 {\n    font-size: clamp(24px, 6.1vw, 31px);\n  }\n\n}\n\n@media (max-height: 700px) {\n\n  .birthday-page {\n    padding-top: 22px;\n    padding-bottom: 18px;\n  }\n\n  .cake-section {\n    width: min(300px, 78vw);\n  }\n\n  .wish-text {\n    margin-top: 12px;\n  }\n\n  .wish-button {\n    margin-top: 17px;\n    padding: 14px 35px;\n  }\n\n}\n\n@media (max-width: 350px) {\n\n  .intro-title {\n    letter-spacing: 2px;\n  }\n\n  .birthday-content h1 {\n    font-size: 23px;\n  }\n\n  .cake-section {\n    width: 90vw;\n  }\n\n}\n</style><script>\n/* =====================================\n   ELEMENTS\n===================================== */\n\nconst starsContainer = document.getElementById(\"stars\");\nconst particleContainer = document.getElementById(\"particleContainer\");\n\nconst flameGroup = document.getElementById(\"flameGroup\");\n\nconst wishButton = document.getElementById(\"wishButton\");\nconst birthdayContent = document.getElementById(\"birthdayContent\");\nconst birthdayHeading = document.getElementById(\"birthdayHeading\");\nconst wishText = document.getElementById(\"wishText\");\n\nconst afterWish = document.getElementById(\"afterWish\");\nconst continueButton = document.getElementById(\"continueButton\");\n\nconst heartContainer = document.getElementById(\"heartContainer\");\n\nconst birthdayPage = document.getElementById(\"birthdayPage\");\nconst nextPage = document.getElementById(\"nextPage\");\n\n\n/* =====================================\n   STARS\n===================================== */\n\nfunction createStar() {\n\n  const star = document.createElement(\"span\");\n\n  star.className = \"star\";\n\n  const size = Math.random() * 3.5 + 1;\n\n  star.style.width = `${size}px`;\n  star.style.height = `${size}px`;\n\n  star.style.left = `${Math.random() * 100}%`;\n  star.style.top = `${Math.random() * 100}%`;\n\n  star.style.setProperty(\n    \"--duration\",\n    `${Math.random() * 3 + 1.5}s`\n  );\n\n  star.style.animationDelay =\n    `${Math.random() * 4}s`;\n\n  starsContainer.appendChild(star);\n\n}\n\nfor (let i = 0; i < 110; i++) {\n  createStar();\n}\n\nsetInterval(() => {\n\n  createStar();\n\n  const allStars = starsContainer.querySelectorAll(\".star\");\n\n  if (allStars.length > 150) {\n    allStars[0].remove();\n  }\n\n}, 1800);\n\n\n/* =====================================\n   BIRTHDAY TYPING\n===================================== */\n\nconst headingText = \"Happy Birthday, Shivani!\";\n\nlet letterIndex = 0;\n\nfunction typeBirthdayHeading() {\n\n  if (letterIndex < headingText.length) {\n\n    birthdayHeading.textContent +=\n      headingText.charAt(letterIndex);\n\n    letterIndex++;\n\n    setTimeout(typeBirthdayHeading, 115);\n\n  } else {\n\n    birthdayHeading.classList.add(\"typing-done\");\n\n    wishText.classList.add(\"visible\");\n\n    setTimeout(() => {\n      wishButton.classList.add(\"visible\");\n    }, 450);\n\n  }\n\n}\n\n\n/* =====================================\n   START AFTER CANDLE IS LIT\n===================================== */\n\nwindow.addEventListener(\"load\", () => {\n\n  // Plate: 0.8 seconds\n  // Bottom layer: 1.9 seconds\n  // Middle layer: 2.9 seconds\n  // Top layer: 3.9 seconds\n  // Cream: 4.85 seconds\n  // Candle: 5.95 seconds\n  // Flame: 6.85 seconds\n\n  // Start typing after cake is complete\n  setTimeout(() => {\n\n    typeBirthdayHeading();\n\n  }, 7400);\n\n});\n\n\n/* =====================================\n   PARTICLE BURST\n===================================== */\n\nfunction burstParticles(originX, originY, count = 65) {\n\n  const colors = [\n    \"#ffca55\",\n    \"#ff85b5\",\n    \"#ffffff\",\n    \"#ff9b43\",\n    \"#a78bfa\",\n    \"#53d8e8\",\n    \"#ff5f87\"\n  ];\n\n  for (let i = 0; i < count; i++) {\n\n    const particle = document.createElement(\"span\");\n\n    particle.className = \"confetti\";\n\n    const angle = Math.random() * Math.PI * 2;\n    const distance = Math.random() * 125 + 45;\n\n    const moveX = Math.cos(angle) * distance;\n    const moveY = Math.sin(angle) * distance;\n\n    const color =\n      colors[Math.floor(Math.random() * colors.length)];\n\n    const size = Math.random() * 7 + 4;\n\n    particle.style.left = `${originX}px`;\n    particle.style.top = `${originY}px`;\n\n    particle.style.setProperty(\"--size\", `${size}px`);\n    particle.style.setProperty(\"--particle-color\", color);\n\n    particle.style.setProperty(\n      \"--particle-radius\",\n      Math.random() > .5 ? \"50%\" : \"2px\"\n    );\n\n    particle.style.setProperty(\"--move-x\", `${moveX}px`);\n    particle.style.setProperty(\"--move-y\", `${moveY}px`);\n\n    particle.style.setProperty(\n      \"--rotation\",\n      `${Math.random() * 720 - 360}deg`\n    );\n\n    particle.style.setProperty(\n      \"--particle-time\",\n      `${Math.random() * 1.2 + 1.2}s`\n    );\n\n    particleContainer.appendChild(particle);\n\n    setTimeout(() => particle.remove(), 2700);\n\n  }\n\n}\n\n\n/* =====================================\n   WISH BUTTON\n===================================== */\n\nlet wishMade = false;\n\nwishButton.addEventListener(\"click\", () => {\n\n  if (wishMade) return;\n\n  wishMade = true;\n\n  // Get actual flame position\n  const rect = flameGroup.getBoundingClientRect();\n\n  const flameX = rect.left + rect.width / 2;\n  const flameY = rect.top + rect.height / 2;\n\n  // Extinguish candle\n  document.body.classList.add(\"candle-out\");\n\n  // Particles ONLY when candle extinguishes\n  burstParticles(flameX, flameY, 75);\n\n  // Hide original heading and button\n  birthdayContent.style.display = \"none\";\n\n  // Show only original messages\n  afterWish.classList.add(\"show\");\n\n  // Floating hearts\n  createHearts();\n\n  // Continue after 2 seconds\n  setTimeout(() => {\n\n    continueButton.classList.add(\"visible\");\n\n  }, 2000);\n\n});\n\n\n/* =====================================\n   FLOATING HEARTS\n===================================== */\n\nfunction createHearts() {\n\n  const symbols = [\"❤️\", \"💕\", \"💗\", \"✨\", \"💖\"];\n\n  for (let i = 0; i < 30; i++) {\n\n    setTimeout(() => {\n\n      const heart = document.createElement(\"span\");\n\n      heart.className = \"floating-heart\";\n\n      heart.textContent =\n        symbols[Math.floor(Math.random() * symbols.length)];\n\n      heart.style.left =\n        `${Math.random() * 95}%`;\n\n      heart.style.fontSize =\n        `${Math.random() * 18 + 15}px`;\n\n      heart.style.setProperty(\n        \"--heart-duration\",\n        `${Math.random() * 2 + 3}s`\n      );\n\n      heartContainer.appendChild(heart);\n\n      setTimeout(() => heart.remove(), 5500);\n\n    }, i * 90);\n\n  }\n\n}\n\n\n/* =====================================\n   CONTINUE TO NEXT PAGE\n===================================== */\n\ncontinueButton.addEventListener(\"click\", () => {\n  birthdayPage.classList.add(\"page-hidden\");\n  setTimeout(() => {\n    window.parent.postMessage({ type: \"birthday-next\" }, \"*\");\n  }, 600);\n});\n</script>", "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n  <title>Sweet Memories &amp; Birthday Letter for SHIVANI 🎂</title>\n\n  <style>\n    /* ==========================================================================\n       1. BASE RESET & AMBIENT BACKGROUND (100% Standalone CSS - Zero External Deps)\n       ========================================================================== */\n    *, *::before, *::after {\n      box-sizing: border-box;\n      -webkit-tap-highlight-color: transparent;\n    }\n\n    html, body {\n      margin: 0;\n      padding: 0;\n      width: 100%;\n      min-height: 100vh;\n      min-height: 100dvh;\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n      background-color: #21141e;\n      background-image:\n        radial-gradient(circle at 50% 38%, rgba(138, 76, 92, 0.38) 0%, rgba(59, 32, 44, 0.78) 50%, rgba(33, 20, 30, 0.99) 100%),\n        linear-gradient(180deg, #21141e 0%, #3b202c 52%, #281620 100%);\n      color: #ffffff;\n      overflow-x: hidden;\n    }\n\n    /* Ambient floating dots & confetti canvases (strictly pointer-events: none) */\n    #bg-canvas, #fx-canvas {\n      position: fixed;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n    }\n    #bg-canvas { z-index: 1; }\n    #fx-canvas { z-index: 100; }\n\n    /* ==========================================================================\n       2. TOP BAR CONTROLS\n       ========================================================================== */\n    .top-bar {\n      position: relative;\n      z-index: 40;\n      width: 100%;\n      max-width: 820px;\n      margin: 0 auto;\n      padding: 14px 16px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 8px;\n    }\n\n    .pill-btn {\n      background: rgba(255, 255, 255, 0.1);\n      border: 1px solid rgba(255, 255, 255, 0.18);\n      color: #f7e9ed;\n      border-radius: 999px;\n      padding: 8px 14px;\n      font-size: 13px;\n      font-weight: 600;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      cursor: pointer;\n      touch-action: manipulation;\n      transition: background 0.2s ease, transform 0.15s ease;\n    }\n    .pill-btn:hover { background: rgba(255, 255, 255, 0.18); }\n    .pill-btn:active { transform: scale(0.95); }\n\n    .step-indicator-pill {\n      font-size: 12px;\n      font-weight: 700;\n      color: #ffd57e;\n      letter-spacing: 0.04em;\n      text-align: center;\n    }\n\n    /* ==========================================================================\n       3. MAIN CONTAINER & STEP PAGES\n       ========================================================================== */\n    .main-wrap {\n      position: relative;\n      z-index: 30;\n      width: 100%;\n      max-width: 100%;\n      margin: 0 auto;\n      padding: 6px 0 48px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n    }\n\n    .page-step-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 4px 12px;\n      border-radius: 999px;\n      font-size: 11.5px;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      text-transform: uppercase;\n      background: rgba(255, 255, 255, 0.09);\n      color: #f3d7df;\n      border: 1px solid rgba(255, 255, 255, 0.16);\n      margin-bottom: 10px;\n    }\n\n    /* ==========================================================================\n       4. PAGE 1: CLOTHESLINE SWIPEABLE POLAROID GALLERY (\"A walk down memory lane\")\n       ========================================================================== */\n    .gallery-section {\n      width: 100%;\n      margin-top: 8px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      transition: opacity 0.35s ease, transform 0.35s ease;\n    }\n\n    .gallery-header {\n      text-align: center;\n      padding: 0 18px;\n      margin-bottom: 14px;\n    }\n\n    .gallery-title {\n      margin: 0;\n      font-size: 25px;\n      font-weight: 700;\n      letter-spacing: -0.01em;\n      color: #ffffff;\n    }\n\n    .gallery-sub {\n      margin: 7px 0 0;\n      font-size: 14.5px;\n      font-weight: 500;\n      color: #e4cdd4;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 6px;\n    }\n\n    /* Full-bleed Clothesline + Horizontal Swipe Carousel Wrapper */\n    .clothesline-stage {\n      position: relative;\n      width: 100%;\n      padding-top: 14px;\n      margin-top: 6px;\n      overflow: hidden;\n    }\n\n    /* Glowing golden clothesline string across full viewport width */\n    .clothesline-wire {\n      position: absolute;\n      top: 26px;\n      left: 0;\n      right: 0;\n      height: 2px;\n      background: linear-gradient(\n        90deg,\n        rgba(246, 189, 96, 0.25) 0%,\n        rgba(255, 218, 138, 0.9) 25%,\n        rgba(255, 232, 168, 0.98) 50%,\n        rgba(255, 218, 138, 0.9) 75%,\n        rgba(246, 189, 96, 0.25) 100%\n      );\n      box-shadow: 0 0 10px rgba(255, 210, 125, 0.75), 0 0 22px rgba(245, 166, 35, 0.4);\n      z-index: 2;\n      pointer-events: none;\n    }\n\n    /* Glowing golden fairy-light bulbs spaced along the string */\n    .fairy-lights-row {\n      position: absolute;\n      top: 22px;\n      left: 0;\n      right: 0;\n      height: 10px;\n      display: flex;\n      justify-content: space-around;\n      align-items: center;\n      z-index: 3;\n      pointer-events: none;\n    }\n\n    @keyframes fairyTwinkle {\n      0%, 100% {\n        opacity: 0.55;\n        transform: scale(0.9);\n      }\n      50% {\n        opacity: 1;\n        transform: scale(1.22);\n      }\n    }\n\n    .fairy-bulb {\n      width: 7px;\n      height: 7px;\n      border-radius: 999px;\n      background: #fff2c2;\n      box-shadow: 0 0 8px 2px rgba(255, 214, 118, 0.9), 0 0 16px 4px rgba(245, 166, 35, 0.55);\n      animation: fairyTwinkle 2.4s ease-in-out infinite;\n    }\n\n    /* Horizontal Snap-Scroll Polaroid Track */\n    .polaroid-track {\n      position: relative;\n      z-index: 5;\n      width: 100%;\n      display: flex;\n      align-items: center;\n      gap: 18px;\n      overflow-x: auto;\n      scroll-snap-type: x mandatory;\n      scroll-behavior: smooth;\n      -webkit-overflow-scrolling: touch;\n      scrollbar-width: none;\n      -ms-overflow-style: none;\n      /* Center first and last Polaroids while letting neighbors peek in */\n      padding: 16px calc(50vw - 134px) 22px;\n      cursor: grab;\n    }\n\n    .polaroid-track::-webkit-scrollbar {\n      display: none;\n    }\n\n    .polaroid-track.is-dragging {\n      scroll-behavior: auto;\n      scroll-snap-type: none;\n      cursor: grabbing;\n    }\n\n    @media (min-width: 480px) {\n      .polaroid-track {\n        gap: 22px;\n        padding: 16px calc(50vw - 148px) 22px;\n      }\n    }\n\n    /* Individual Clipped Polaroid Card */\n    .polaroid-slide {\n      position: relative;\n      flex: 0 0 268px;\n      width: 268px;\n      scroll-snap-align: center;\n      background: #fffdf9;\n      border-radius: 12px;\n      padding: 12px 12px 18px;\n      box-shadow:\n        0 18px 36px rgba(0, 0, 0, 0.48),\n        0 4px 12px rgba(0, 0, 0, 0.25);\n      transform-origin: top center;\n      transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.35s ease;\n      user-select: none;\n    }\n\n    @media (min-width: 480px) {\n      .polaroid-slide {\n        flex: 0 0 296px;\n        width: 296px;\n        padding: 13px 13px 20px;\n      }\n    }\n\n    .polaroid-slide.is-active {\n      transform: rotate(0deg) scale(1.01) !important;\n      z-index: 8;\n    }\n\n    /* Realistic 3D Wooden Clothespin clipped on top center */\n    .wooden-pin {\n      position: absolute;\n      top: -15px;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 14px;\n      height: 32px;\n      border-radius: 3px 3px 2px 2px;\n      background: linear-gradient(\n        90deg,\n        #b57e36 0%,\n        #dfb068 35%,\n        #cfa056 68%,\n        #9e6a26 100%\n      );\n      box-shadow:\n        0 3px 6px rgba(0, 0, 0, 0.42),\n        inset 0 1px 0 rgba(255, 238, 198, 0.65);\n      z-index: 12;\n      pointer-events: none;\n    }\n\n    /* Metallic spring coil groove across the wooden clothespin */\n    .wooden-pin::before {\n      content: \"\";\n      position: absolute;\n      top: 13px;\n      left: -1px;\n      right: -1px;\n      height: 3px;\n      background: linear-gradient(180deg, #5e5a54 0%, #c8c2b8 50%, #4a4640 100%);\n      border-radius: 1px;\n    }\n\n    /* Center wood split line at bottom tip of clothespin */\n    .wooden-pin::after {\n      content: \"\";\n      position: absolute;\n      bottom: 0;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 1px;\n      height: 11px;\n      background: rgba(84, 52, 14, 0.55);\n    }\n\n    .polaroid-frame {\n      position: relative;\n      width: 100%;\n      aspect-ratio: 4 / 4.75;\n      border-radius: 6px;\n      overflow: hidden;\n      background: linear-gradient(135deg, #3c222e 0%, #24141d 100%);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .polaroid-frame img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      display: block;\n      pointer-events: none;\n    }\n\n    /* Clean fallback card when photo/1.jpg..8.jpg is not present */\n    .photo-fallback {\n      position: absolute;\n      inset: 0;\n      padding: 14px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      text-align: center;\n      background: radial-gradient(circle at 50% 35%, rgba(245, 184, 65, 0.16), rgba(33, 20, 30, 0.96));\n      border: 1.5px dashed rgba(245, 184, 65, 0.5);\n      border-radius: 6px;\n      color: #f8e5c8;\n    }\n\n    .polaroid-label {\n      margin: 13px 0 0;\n      font-family: \"Comic Sans MS\", \"Bradley Hand\", \"Segoe Print\", cursive, sans-serif;\n      font-size: 16.5px;\n      font-weight: 600;\n      color: #3d2a24;\n      text-align: center;\n      line-height: 1.25;\n      min-height: 22px;\n    }\n\n    /* Circular Pagination Dots directly below carousel */\n    .carousel-dots {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      margin: 6px auto 22px;\n      padding: 4px 12px;\n    }\n\n    .dot-btn {\n      width: 8px;\n      height: 8px;\n      padding: 0;\n      border: none;\n      border-radius: 999px;\n      background: rgba(255, 255, 255, 0.28);\n      cursor: pointer;\n      touch-action: manipulation;\n      transition: all 0.28s cubic-bezier(0.22, 1, 0.36, 1);\n    }\n\n    .dot-btn.active {\n      width: 18px;\n      background: #f5a623;\n      box-shadow: 0 0 10px rgba(245, 166, 35, 0.85);\n    }\n\n    /* \"Keep going ✨\" Pill CTA Button */\n    .keep-going-wrap {\n      width: 100%;\n      max-width: 310px;\n      padding: 0 16px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n    }\n\n    @keyframes keepGoingGlow {\n      0%, 100% {\n        box-shadow: 0 10px 26px rgba(235, 130, 74, 0.42);\n      }\n      50% {\n        box-shadow: 0 14px 34px rgba(246, 164, 68, 0.68);\n      }\n    }\n\n    .keep-going-btn {\n      width: 100%;\n      border: none;\n      border-radius: 999px;\n      padding: 15px 28px;\n      font-size: 16px;\n      font-weight: 700;\n      letter-spacing: 0.01em;\n      color: #ffffff;\n      background: linear-gradient(90deg, #f6a444 0%, #e57a54 100%);\n      opacity: 0.52;\n      cursor: pointer;\n      touch-action: manipulation;\n      transition: opacity 0.35s ease, transform 0.2s ease, box-shadow 0.35s ease;\n    }\n\n    .keep-going-btn.unlocked {\n      opacity: 1;\n      animation: keepGoingGlow 2.4s ease-in-out infinite;\n    }\n\n    .keep-going-btn:hover {\n      opacity: 1;\n      transform: translateY(-2px);\n    }\n\n    .keep-going-btn:active {\n      transform: scale(0.97);\n    }\n\n    .action-chip {\n      border: none;\n      border-radius: 999px;\n      padding: 8px 14px;\n      font-size: 12.5px;\n      font-weight: 700;\n      cursor: pointer;\n      touch-action: manipulation;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      transition: transform 0.15s ease, opacity 0.2s ease, background 0.2s ease;\n    }\n    .action-chip:active { transform: scale(0.95); }\n\n    .chip-gold {\n      background: linear-gradient(90deg, #f5a623 0%, #e67e22 100%);\n      color: #ffffff;\n      box-shadow: 0 6px 16px rgba(230, 126, 34, 0.35);\n    }\n\n    .chip-glass {\n      background: rgba(255, 255, 255, 0.12);\n      border: 1px solid rgba(255, 255, 255, 0.2);\n      color: #fff3f6;\n    }\n    .chip-glass:hover {\n      background: rgba(255, 255, 255, 0.2);\n    }\n\n    /* ==========================================================================\n       5. PAGE 2: 3D GOLDEN ENVELOPE STAGE\n       ========================================================================== */\n    #page-2-wrapper {\n      display: none;\n      width: 100%;\n      max-width: 820px;\n      padding: 0 16px;\n      flex-direction: column;\n      align-items: center;\n    }\n\n    .page-step-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 4px 12px;\n      border-radius: 999px;\n      font-size: 11.5px;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      text-transform: uppercase;\n      background: rgba(255, 255, 255, 0.09);\n      color: #f3d7df;\n      border: 1px solid rgba(255, 255, 255, 0.16);\n      margin-bottom: 10px;\n    }\n\n    /* ==========================================================================\n       4. PAGE 1: 8-PHOTO POLAROID GALLERY (\"Sweet Memories ✨\")\n       ========================================================================== */\n    .gallery-section {\n      width: 100%;\n      max-width: 800px;\n      margin-top: 4px;\n      padding-top: 4px;\n      transition: opacity 0.35s ease, transform 0.35s ease;\n    }\n\n    .gallery-header {\n      text-align: center;\n      margin-bottom: 18px;\n    }\n\n    .gallery-badge {\n      display: inline-block;\n      padding: 5px 14px;\n      border-radius: 999px;\n      font-size: 12px;\n      font-weight: 700;\n      letter-spacing: 0.04em;\n      background: rgba(245, 184, 65, 0.16);\n      color: #ffd57e;\n      border: 1px solid rgba(245, 184, 65, 0.35);\n      margin-bottom: 8px;\n    }\n\n    .gallery-title {\n      margin: 0;\n      font-size: 24px;\n      font-weight: 700;\n      color: #ffffff;\n    }\n\n    .gallery-sub {\n      margin: 6px auto 12px;\n      font-size: 13px;\n      color: #dcc5cc;\n      max-width: 460px;\n      line-height: 1.45;\n    }\n\n    .header-actions-row {\n      display: flex;\n      flex-wrap: wrap;\n      justify-content: center;\n      gap: 10px;\n      margin-top: 10px;\n    }\n\n    .action-chip {\n      border: none;\n      border-radius: 999px;\n      padding: 9px 16px;\n      font-size: 13px;\n      font-weight: 700;\n      cursor: pointer;\n      touch-action: manipulation;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      transition: transform 0.15s ease, opacity 0.2s ease, background 0.2s ease;\n    }\n    .action-chip:active { transform: scale(0.95); }\n\n    .chip-gold {\n      background: linear-gradient(90deg, #f5a623 0%, #e67e22 100%);\n      color: #ffffff;\n      box-shadow: 0 6px 16px rgba(230, 126, 34, 0.35);\n    }\n\n    .chip-glass {\n      background: rgba(255, 255, 255, 0.12);\n      border: 1px solid rgba(255, 255, 255, 0.2);\n      color: #fff3f6;\n    }\n    .chip-glass:hover {\n      background: rgba(255, 255, 255, 0.2);\n    }\n\n    /* Responsive 2-col mobile / 4-col desktop grid */\n    .polaroid-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 14px;\n    }\n\n    @media (min-width: 680px) {\n      .polaroid-grid {\n        grid-template-columns: repeat(4, minmax(0, 1fr));\n        gap: 16px;\n      }\n    }\n\n    .polaroid-card {\n      background: #fff9ef;\n      border-radius: 14px;\n      padding: 9px 9px 13px;\n      box-shadow:\n        0 14px 28px rgba(0, 0, 0, 0.4),\n        0 0 0 1px rgba(238, 197, 138, 0.5);\n      transition: transform 0.25s ease;\n    }\n\n    .polaroid-card:hover {\n      transform: translateY(-4px) rotate(0deg) !important;\n    }\n\n    .polaroid-frame {\n      position: relative;\n      width: 100%;\n      aspect-ratio: 4 / 5;\n      border-radius: 9px;\n      overflow: hidden;\n      background: linear-gradient(135deg, #3c222e 0%, #26151e 100%);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .polaroid-frame img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      display: block;\n    }\n\n    /* Clean fallback card when photo/1.jpg..8.jpg is not present */\n    .photo-fallback {\n      position: absolute;\n      inset: 0;\n      padding: 10px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      text-align: center;\n      background: radial-gradient(circle at 50% 35%, rgba(245, 184, 65, 0.16), rgba(33, 20, 30, 0.95));\n      border: 1.5px dashed rgba(245, 184, 65, 0.5);\n      border-radius: 9px;\n      color: #f8e5c8;\n    }\n\n    .polaroid-label {\n      margin: 8px 0 0;\n      font-family: \"Comic Sans MS\", \"Bradley Hand\", cursive, sans-serif;\n      font-size: 14.5px;\n      font-weight: 700;\n      color: #5a3921;\n      text-align: center;\n      line-height: 1.25;\n    }\n\n    /* ==========================================================================\n       5. PAGE 2: 3D GOLDEN ENVELOPE STAGE\n       ========================================================================== */\n    #page-2-wrapper {\n      display: none;\n      width: 100%;\n      flex-direction: column;\n      align-items: center;\n    }\n\n    .envelope-stage {\n      position: relative;\n      z-index: 50;\n      width: 100%;\n      max-width: 440px;\n      margin-top: 8px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      text-align: center;\n      transition: opacity 0.45s ease, transform 0.45s ease;\n    }\n\n    .back-bar {\n      width: 100%;\n      display: flex;\n      justify-content: flex-start;\n      margin-bottom: 12px;\n    }\n\n    .env-title {\n      margin: 0;\n      font-size: 26px;\n      font-weight: 700;\n      line-height: 1.25;\n      color: #ffffff;\n      letter-spacing: -0.01em;\n    }\n\n    .env-subtitle {\n      margin: 8px 0 0;\n      font-size: 14.5px;\n      color: #e8cfd6;\n      font-weight: 400;\n    }\n\n    /* Interactive 3D Golden Envelope Container */\n    .envelope-box {\n      position: relative;\n      z-index: 50;\n      width: 320px;\n      height: 210px;\n      margin: 28px auto 20px;\n      perspective: 1100px;\n      cursor: pointer;\n      touch-action: manipulation;\n      user-select: none;\n      transition: transform 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);\n    }\n\n    @media (min-width: 400px) {\n      .envelope-box {\n        width: 344px;\n        height: 224px;\n      }\n    }\n\n    .envelope-box:hover {\n      transform: translateY(-4px) scale(1.02);\n    }\n\n    .envelope-box:active {\n      transform: scale(0.97);\n    }\n\n    .envelope-body {\n      position: relative;\n      width: 100%;\n      height: 100%;\n      border-radius: 14px;\n      background: linear-gradient(145deg, #c9731e 0%, #e69532 50%, #b86314 100%);\n      box-shadow:\n        0 24px 48px rgba(0, 0, 0, 0.55),\n        0 0 38px rgba(245, 184, 65, 0.25),\n        inset 0 1px 1px rgba(255, 232, 175, 0.5);\n    }\n\n    .envelope-inside {\n      position: absolute;\n      inset: 2px;\n      border-radius: 12px;\n      background: linear-gradient(180deg, #8c490d 0%, #b66518 100%);\n      z-index: 1;\n      pointer-events: none;\n    }\n\n    /* Mini letter card peeking up when opened */\n    .envelope-peek {\n      position: absolute;\n      left: 16px;\n      right: 16px;\n      bottom: 12px;\n      height: 175px;\n      border-radius: 10px;\n      background: repeating-linear-gradient(\n        to bottom,\n        #fff7e8 0px,\n        #fff7e8 24px,\n        #eadbc3 25px\n      );\n      box-shadow: 0 -4px 16px rgba(0, 0, 0, 0.22);\n      z-index: 2;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      padding-top: 18px;\n      transform: translateY(0);\n      transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1) 0.22s;\n      pointer-events: none;\n    }\n\n    .envelope-box.is-open .envelope-peek {\n      transform: translateY(-88px);\n    }\n\n    /* Envelope Triangular Flaps */\n    .flap-left {\n      position: absolute;\n      inset: 0;\n      border-radius: 14px;\n      background: linear-gradient(115deg, #e79634 0%, #f4b342 62%, #d47d22 100%);\n      clip-path: polygon(0 0, 52% 52%, 0 100%);\n      z-index: 4;\n      pointer-events: none;\n    }\n\n    .flap-right {\n      position: absolute;\n      inset: 0;\n      border-radius: 14px;\n      background: linear-gradient(245deg, #e79634 0%, #f4b342 62%, #d47d22 100%);\n      clip-path: polygon(100% 0, 48% 52%, 100% 100%);\n      z-index: 4;\n      pointer-events: none;\n    }\n\n    .flap-bottom {\n      position: absolute;\n      inset: 0;\n      border-radius: 14px;\n      background: linear-gradient(0deg, #f5b841 0%, #e59330 68%, #cc741d 100%);\n      clip-path: polygon(0 100%, 50% 46%, 100% 100%);\n      z-index: 5;\n      filter: drop-shadow(0 -3px 6px rgba(95, 45, 5, 0.28));\n      pointer-events: none;\n    }\n\n    .flap-top {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 58%;\n      background: linear-gradient(180deg, #f7bf4f 0%, #e89732 74%, #cf771e 100%);\n      clip-path: polygon(0 0, 100% 0, 50% 100%);\n      border-top-left-radius: 14px;\n      border-top-right-radius: 14px;\n      transform-origin: top center;\n      transform: rotateX(0deg);\n      transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1), z-index 0.1s linear 0.25s;\n      z-index: 6;\n      filter: drop-shadow(0 5px 8px rgba(74, 34, 4, 0.35));\n      pointer-events: none;\n    }\n\n    .envelope-box.is-open .flap-top {\n      transform: rotateX(180deg);\n      z-index: 1;\n    }\n\n    /* White-Ringed 'S' Wax Seal */\n    @keyframes sealPulse {\n      0%, 100% {\n        transform: translate(-50%, -50%) scale(1);\n        box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35), 0 0 0 0 rgba(255, 244, 214, 0.55);\n      }\n      50% {\n        transform: translate(-50%, -50%) scale(1.07);\n        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), 0 0 0 11px rgba(255, 244, 214, 0);\n      }\n    }\n\n    .wax-seal {\n      position: absolute;\n      top: 52%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      width: 58px;\n      height: 58px;\n      border-radius: 999px;\n      background: radial-gradient(circle at 32% 30%, #ffd97d 0%, #f2a93b 55%, #c9771c 100%);\n      border: 3px solid rgba(255, 255, 255, 0.95);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      z-index: 55;\n      cursor: pointer;\n      animation: sealPulse 2.3s ease-in-out infinite;\n      transition: opacity 0.25s ease, transform 0.25s ease;\n    }\n\n    .wax-seal-inner {\n      width: 44px;\n      height: 44px;\n      border-radius: 999px;\n      border: 1px solid rgba(255, 255, 255, 0.5);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-weight: 800;\n      font-size: 21px;\n      color: #ffffff;\n      text-shadow: 0 1px 3px rgba(120, 60, 5, 0.5);\n    }\n\n    .envelope-box.is-open .wax-seal {\n      opacity: 0;\n      transform: translate(-50%, -50%) scale(0.5);\n      animation: none;\n      pointer-events: none;\n    }\n\n    /* Tap Prompt below envelope */\n    .tap-prompt {\n      margin-top: 6px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      cursor: pointer;\n    }\n\n    @keyframes handBob {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-6px); }\n    }\n\n    .hand-icon {\n      font-size: 26px;\n      margin-bottom: 4px;\n      animation: handBob 1.5s ease-in-out infinite;\n    }\n\n    .tap-text {\n      margin: 0;\n      font-size: 14px;\n      color: #d4bcc3;\n      font-weight: 500;\n    }\n\n    /* ==========================================================================\n       6. OPENED LETTER STAGE (Ruled Cream Notepad + Typewriter)\n       ========================================================================== */\n    .opened-content {\n      display: none;\n      width: 100%;\n      flex-direction: column;\n      align-items: center;\n      opacity: 0;\n      transform: translateY(16px);\n      transition: opacity 0.45s ease, transform 0.45s ease;\n    }\n\n    .opened-content.visible {\n      display: flex;\n      opacity: 1;\n      transform: translateY(0);\n    }\n\n    .letter-actions-bar {\n      width: 100%;\n      max-width: 540px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 8px;\n      margin-bottom: 12px;\n    }\n\n    /* Ruled Cream Notepad Card */\n    .notepad-card {\n      position: relative;\n      width: 100%;\n      max-width: 540px;\n      border-radius: 18px;\n      background-color: #fff7e8;\n      box-shadow:\n        0 22px 54px rgba(0, 0, 0, 0.55),\n        0 0 40px rgba(255, 214, 153, 0.22),\n        inset 0 0 0 1px rgba(235, 210, 172, 0.85);\n      overflow: hidden;\n    }\n\n    /* Vertical red margin line */\n    .notepad-card::before {\n      content: \"\";\n      position: absolute;\n      top: 0;\n      bottom: 0;\n      left: 34px;\n      width: 1.5px;\n      background: rgba(220, 95, 95, 0.3);\n      pointer-events: none;\n      z-index: 2;\n    }\n\n    .notepad-body {\n      width: 100%;\n      padding: 24px 20px 32px 46px;\n      background-image: repeating-linear-gradient(\n        to bottom,\n        transparent 0px,\n        transparent 31px,\n        #eadbc3 31px,\n        #eadbc3 32px\n      );\n      background-position: 0 18px;\n    }\n\n    .letter-greeting {\n      font-family: \"Comic Sans MS\", \"Bradley Hand\", \"Segoe Print\", cursive, sans-serif;\n      font-size: 22px;\n      font-weight: 700;\n      color: #8c5a32;\n      line-height: 32px;\n      margin: 0 0 12px;\n    }\n\n    .letter-paragraphs {\n      font-family: \"Comic Sans MS\", \"Bradley Hand\", \"Segoe Print\", cursive, sans-serif;\n      font-size: 17.5px;\n      color: #3a2618;\n      line-height: 32px;\n    }\n\n    .letter-paragraphs p {\n      margin: 0 0 14px;\n    }\n\n    .letter-paragraphs p.lead-bold {\n      font-weight: 700;\n      color: #26150a;\n      font-size: 19px;\n    }\n\n    .letter-paragraphs p.sign-right {\n      text-align: right;\n      font-weight: 700;\n      color: #3a2618;\n      margin-bottom: 4px;\n    }\n\n    .letter-paragraphs p.sign-love {\n      text-align: right;\n      font-style: italic;\n      font-weight: 700;\n      color: #9a6334;\n      margin-bottom: 0;\n    }\n\n    /* Blinking Golden Typewriter Cursor */\n    .typing-cursor {\n      display: inline-block;\n      width: 9px;\n      height: 19px;\n      margin-left: 2px;\n      vertical-align: -3px;\n      border-radius: 3px;\n      background: linear-gradient(180deg, #ffbe44 0%, #f08826 100%);\n      box-shadow: 0 0 10px rgba(245, 166, 35, 0.85);\n      animation: cursorBlink 0.7s ease-in-out infinite;\n    }\n\n    @keyframes cursorBlink {\n      0%, 100% { opacity: 1; }\n      50% { opacity: 0.2; }\n    }\n\n    /* Bottom Celebration & Close Bar */\n    .bottom-cta-row {\n      width: 100%;\n      max-width: 480px;\n      margin: 28px auto 0;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n\n    @media (min-width: 480px) {\n      .bottom-cta-row {\n        flex-direction: row;\n      }\n    }\n\n    .cta-primary {\n      flex: 1;\n      border: none;\n      border-radius: 999px;\n      padding: 14px 22px;\n      font-size: 15px;\n      font-weight: 700;\n      color: #ffffff;\n      background: linear-gradient(90deg, #f5a623 0%, #e67e22 100%);\n      box-shadow: 0 10px 24px rgba(230, 126, 34, 0.4);\n      cursor: pointer;\n      touch-action: manipulation;\n      transition: transform 0.18s ease, box-shadow 0.18s ease;\n    }\n\n    .cta-primary:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 14px 28px rgba(230, 126, 34, 0.5);\n    }\n\n    .cta-primary:active {\n      transform: scale(0.97);\n    }\n\n    .cta-secondary {\n      border: 1px solid rgba(255, 255, 255, 0.22);\n      border-radius: 999px;\n      padding: 14px 20px;\n      font-size: 14px;\n      font-weight: 600;\n      color: #f7e9ed;\n      background: rgba(255, 255, 255, 0.1);\n      cursor: pointer;\n      touch-action: manipulation;\n      transition: background 0.18s ease, transform 0.15s ease;\n    }\n\n    .cta-secondary:hover {\n      background: rgba(255, 255, 255, 0.18);\n    }\n\n    .cta-secondary:active {\n      transform: scale(0.97);\n    }\n  </style>\n</head>\n<body>\n  <!-- Background Bokeh & Confetti Canvases (strictly non-blocking) -->\n  <canvas id=\"bg-canvas\"></canvas>\n  <canvas id=\"fx-canvas\"></canvas>\n\n  <!-- Top Controls -->\n  <header class=\"top-bar\">\n    <button type=\"button\" class=\"pill-btn\" id=\"replay-btn\">\n      <span>↺ Replay</span>\n    </button>\n\n    <button type=\"button\" class=\"pill-btn\" id=\"upload-photos-btn\" title=\"Select up to 8 photos from your phone\">\n      <span>+ Photos</span>\n    </button>\n    <input type=\"file\" id=\"phone-photo-input\" accept=\"image/*\" multiple style=\"display: none;\" />\n\n    <button type=\"button\" class=\"pill-btn\" id=\"sound-toggle-btn\">\n      <span id=\"sound-icon\">🔊 Sound On</span>\n    </button>\n  </header>\n\n  <!-- Main Wrapper -->\n  <main class=\"main-wrap\">\n\n    <!-- ======================================================================\n         PAGE 1 (FIRST VIEW): CLOTHESLINE SWIPEABLE POLAROID GALLERY\n         ====================================================================== -->\n    <section id=\"gallery-section\" class=\"gallery-section\">\n      <div class=\"gallery-header\">\n        <h1 class=\"gallery-title\">A walk down memory lane</h1>\n        <p class=\"gallery-sub\">swipe through 📸</p>\n      </div>\n\n      <!-- Horizontal Glowing Golden Clothesline + Swipeable Polaroid Track -->\n      <div class=\"clothesline-stage\">\n        <div class=\"clothesline-wire\" aria-hidden=\"true\"></div>\n        <div class=\"fairy-lights-row\" aria-hidden=\"true\">\n          <span class=\"fairy-bulb\" style=\"animation-delay: 0s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 0.4s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 0.8s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 1.2s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 1.6s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 2.0s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 0.5s;\"></span>\n          <span class=\"fairy-bulb\" style=\"animation-delay: 1.1s;\"></span>\n        </div>\n\n        <div id=\"polaroid-track\" class=\"polaroid-track\" role=\"region\" aria-label=\"Memory lane photo carousel\"></div>\n      </div>\n\n      <!-- Circular Pagination Dots -->\n      <div id=\"carousel-dots\" class=\"carousel-dots\" role=\"tablist\" aria-label=\"Photo slide navigation\"></div>\n\n      <!-- Bottom \"Keep going ✨\" CTA Pill Button -->\n      <div class=\"keep-going-wrap\">\n        <button type=\"button\" class=\"keep-going-btn\" id=\"keep-going-btn\">\n          Keep going ✨\n        </button>\n      </div>\n    </section>\n\n    <!-- ======================================================================\n         PAGE 2 (SECOND VIEW): 3D GOLDEN ENVELOPE + RULED NOTEPAD MESSAGE\n         ====================================================================== -->\n    <div id=\"page-2-wrapper\">\n\n      <!-- VIEW 2A: CLOSED 3D GOLDEN ENVELOPE -->\n      <section id=\"envelope-stage\" class=\"envelope-stage\">\n        <div class=\"back-bar\">\n          <button type=\"button\" class=\"action-chip chip-glass\" id=\"back-to-photos-env-btn\">\n            ← Back to Photos\n          </button>\n        </div>\n\n        <div class=\"page-step-badge\">Step 2 of 2 • Special Message</div>\n        <h2 class=\"env-title\">One last thing, SHIVANI...</h2>\n        <p class=\"env-subtitle\">Your Brother wrote you a letter.</p>\n\n        <!-- Interactive 3D Golden Envelope -->\n        <div id=\"envelope-box\" class=\"envelope-box\" role=\"button\" tabindex=\"0\" aria-label=\"Tap to open your letter\">\n          <div class=\"envelope-body\">\n            <div class=\"envelope-inside\"></div>\n\n            <!-- Inner letter card preview -->\n            <div class=\"envelope-peek\">\n              <span style=\"font-size: 26px;\">🎂</span>\n              <div style=\"width: 72%; height: 8px; border-radius: 99px; background: #e5d2b5; margin-top: 8px;\"></div>\n              <div style=\"width: 60%; height: 8px; border-radius: 99px; background: #eadbc3; margin-top: 10px;\"></div>\n            </div>\n\n            <div class=\"flap-left\"></div>\n            <div class=\"flap-right\"></div>\n            <div class=\"flap-bottom\"></div>\n            <div class=\"flap-top\"></div>\n\n            <!-- White-ringed 'S' Wax Seal -->\n            <div class=\"wax-seal\" id=\"wax-seal-btn\">\n              <div class=\"wax-seal-inner\">S</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Tap Prompt -->\n        <div class=\"tap-prompt\" id=\"tap-prompt-btn\">\n          <span class=\"hand-icon\" aria-hidden=\"true\">👆</span>\n          <p class=\"tap-text\">Tap to open your letter</p>\n        </div>\n      </section>\n\n      <!-- VIEW 2B: OPENED LETTER NOTEPAD CARD -->\n      <section id=\"opened-content\" class=\"opened-content\" aria-live=\"polite\">\n\n        <!-- Quick Action Bar above the Letter -->\n        <div class=\"letter-actions-bar\">\n          <button type=\"button\" class=\"action-chip chip-glass\" id=\"back-to-photos-letter-btn\">\n            ← Back to Photos\n          </button>\n\n          <button type=\"button\" id=\"read-full-btn\" class=\"action-chip chip-gold\">\n            ⚡ Read Full Letter\n          </button>\n        </div>\n\n        <!-- Ruled Cream Notepad Card -->\n        <article class=\"notepad-card\">\n          <div class=\"notepad-body\">\n            <h2 class=\"letter-greeting\">Dear SHIVANI,</h2>\n            <div id=\"letter-paragraphs\" class=\"letter-paragraphs\"></div>\n          </div>\n        </article>\n\n        <!-- Bottom Celebration & Close Controls -->\n        <div class=\"bottom-cta-row\">\n          <button type=\"button\" class=\"cta-primary\" id=\"celebrate-btn\">\n            Happy Birthday Shivani! 🎂✨\n          </button>\n          <button type=\"button\" class=\"cta-secondary\" id=\"close-letter-btn\">\n            Close Letter ✉️\n          </button>\n        </div>\n\n      </section>\n\n    </div>\n\n  </main>\n\n  <script>\n    (function () {\n      \"use strict\";\n\n      /* ==========================================================================\n         1. LETTER PARAGRAPHS & 8-PHOTO CONFIGURATION\n         ========================================================================== */\n      var LETTER_LINES = [\n        { text: \"Happy Birthday, My Sister! ❤️\", cls: \"lead-bold\" },\n        { text: \"Every single day with you in our family feels brighter, happier, and full of warmth. You are not just my sister, you are my biggest blessing and my forever best friend.\", cls: \"\" },\n        { text: \"Thank you for always standing by me, bringing endless smiles into our lives, and making every ordinary moment unforgettable, My Sister ❤️.\", cls: \"\" },\n        { text: \"May all your dreams come true this year and always. Keep shining and keep smiling just the way you do!\", cls: \"\" },\n        { text: \"From your Brother 🥰\", cls: \"sign-right\" },\n        { text: \"Love from your Brother\", cls: \"sign-love\" }\n      ];\n\n      var GALLERY_PHOTOS = [\n        { src: \"photo/1.jpg\", caption: \"So sweet ❤️\", rotate: \"-2deg\" },\n        { src: \"photo/2.jpg\", caption: \"My cutie 🥰\", rotate: \"1.8deg\" },\n        { src: \"photo/3.jpg\", caption: \"So beautiful ❤️\", rotate: \"-1.6deg\" },\n        { src: \"photo/4.jpg\", caption: \"Forever Smiles 😊\", rotate: \"1.9deg\" },\n        { src: \"photo/5.jpg\", caption: \"Golden Moments 🌟\", rotate: \"-1.8deg\" },\n        { src: \"photo/6.jpg\", caption: \"Best Sister 💖\", rotate: \"1.6deg\" },\n        { src: \"photo/7.jpg\", caption: \"Always Together 🤝\", rotate: \"-1.5deg\" },\n        { src: \"photo/8.jpg\", caption: \"💛\", rotate: \"1.7deg\" }\n      ];\n\n      var activeSlideIndex = 0;\n      var hasSwipedGallery = false;\n      var scrollTicking = false;\n      var audioCtx = null;\n      var soundEnabled = true;\n\n      function initAudio() {\n        try {\n          if (!audioCtx) {\n            var Ctx = window.AudioContext || window.webkitAudioContext;\n            if (Ctx) audioCtx = new Ctx();\n          }\n          if (audioCtx && audioCtx.state === \"suspended\") {\n            audioCtx.resume();\n          }\n        } catch (e) {}\n      }\n\n      function playChime() {\n        if (!soundEnabled) return;\n        initAudio();\n        if (!audioCtx) return;\n        try {\n          var now = audioCtx.currentTime;\n          var notes = [523.25, 659.25, 783.99, 1046.5];\n          notes.forEach(function (freq, i) {\n            var t = now + i * 0.08;\n            var osc = audioCtx.createOscillator();\n            var gain = audioCtx.createGain();\n            osc.type = \"sine\";\n            osc.frequency.setValueAtTime(freq, t);\n            gain.gain.setValueAtTime(0.001, t);\n            gain.gain.linearRampToValueAtTime(0.1, t + 0.02);\n            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.42);\n            osc.connect(gain);\n            gain.connect(audioCtx.destination);\n            osc.start(t);\n            osc.stop(t + 0.44);\n          });\n        } catch (e) {}\n      }\n\n      function playTick() {\n        if (!soundEnabled) return;\n        initAudio();\n        if (!audioCtx) return;\n        try {\n          var now = audioCtx.currentTime;\n          var osc = audioCtx.createOscillator();\n          var gain = audioCtx.createGain();\n          osc.type = \"triangle\";\n          osc.frequency.setValueAtTime(640 + Math.random() * 120, now);\n          osc.frequency.exponentialRampToValueAtTime(190, now + 0.02);\n          gain.gain.setValueAtTime(0.025, now);\n          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.022);\n          osc.connect(gain);\n          gain.connect(audioCtx.destination);\n          osc.start(now);\n          osc.stop(now + 0.024);\n        } catch (e) {}\n      }\n\n      function toggleSound() {\n        soundEnabled = !soundEnabled;\n        var soundIcon = document.getElementById(\"sound-icon\");\n        if (soundIcon) {\n          soundIcon.textContent = soundEnabled ? \"🔊 Sound On\" : \"🔇 Muted\";\n        }\n        if (soundEnabled) initAudio();\n      }\n\n      /* ==========================================================================\n         3. RENDER CLOTHESLINE POLAROID CAROUSEL, DOTS & PHONE UPLOAD PREVIEW\n         ========================================================================== */\n      function renderPolaroidGallery() {\n        var track = document.getElementById(\"polaroid-track\");\n        var dotsContainer = document.getElementById(\"carousel-dots\");\n        if (!track || !dotsContainer) return;\n\n        track.innerHTML = \"\";\n        dotsContainer.innerHTML = \"\";\n\n        GALLERY_PHOTOS.forEach(function (item, index) {\n          var slide = document.createElement(\"div\");\n          slide.className = \"polaroid-slide\" + (index === activeSlideIndex ? \" is-active\" : \"\");\n          slide.style.transform = \"rotate(\" + item.rotate + \")\";\n          slide.setAttribute(\"data-index\", String(index));\n\n          // Realistic 3D Wooden Clothespin clipped onto the clothesline string\n          var pin = document.createElement(\"div\");\n          pin.className = \"wooden-pin\";\n          pin.setAttribute(\"aria-hidden\", \"true\");\n\n          var frame = document.createElement(\"div\");\n          frame.className = \"polaroid-frame\";\n\n          var img = document.createElement(\"img\");\n          img.src = item.src;\n          img.alt = \"Shivani Memory \" + (index + 1);\n          img.draggable = false;\n\n          var fallback = document.createElement(\"div\");\n          fallback.className = \"photo-fallback\";\n          fallback.innerHTML =\n            '<span style=\"font-size: 32px; margin-bottom: 6px;\">📸</span>' +\n            '<span style=\"font-size: 13px; font-weight: 700; color: #ffd57e;\">photo/' + (index + 1) + '.jpg</span>' +\n            '<span style=\"font-size: 11px; color: #e5cfd5; margin-top: 4px;\">Swipe or tap \"+ Photos\" at top</span>';\n\n          img.onload = function () {\n            fallback.style.display = \"none\";\n            img.style.display = \"block\";\n          };\n          img.onerror = function () {\n            img.style.display = \"none\";\n            fallback.style.display = \"flex\";\n          };\n\n          var caption = document.createElement(\"p\");\n          caption.className = \"polaroid-label\";\n          caption.textContent = item.caption;\n\n          // Clicking a peeking adjacent slide smoothly centers it\n          slide.addEventListener(\"click\", function () {\n            if (index !== activeSlideIndex) {\n              scrollToSlide(index);\n            }\n          });\n\n          frame.appendChild(img);\n          frame.appendChild(fallback);\n          slide.appendChild(pin);\n          slide.appendChild(frame);\n          slide.appendChild(caption);\n          track.appendChild(slide);\n\n          // Pagination dot\n          var dot = document.createElement(\"button\");\n          dot.type = \"button\";\n          dot.className = \"dot-btn\" + (index === activeSlideIndex ? \" active\" : \"\");\n          dot.setAttribute(\"aria-label\", \"View photo \" + (index + 1));\n          dot.addEventListener(\"click\", function () {\n            scrollToSlide(index);\n          });\n          dotsContainer.appendChild(dot);\n        });\n\n        updateActiveCarouselUI(activeSlideIndex);\n      }\n\n      function scrollToSlide(index) {\n        var track = document.getElementById(\"polaroid-track\");\n        if (!track) return;\n        var slides = track.querySelectorAll(\".polaroid-slide\");\n        var target = slides[index];\n        if (!target) return;\n\n        var targetLeft = target.offsetLeft - (track.clientWidth - target.offsetWidth) / 2;\n        track.scrollTo({\n          left: Math.max(0, targetLeft),\n          behavior: \"smooth\"\n        });\n      }\n\n      function updateActiveCarouselUI(newIndex) {\n        var track = document.getElementById(\"polaroid-track\");\n        var dotsContainer = document.getElementById(\"carousel-dots\");\n        var keepGoingBtn = document.getElementById(\"keep-going-btn\");\n        if (!track || !dotsContainer) return;\n\n        if (newIndex !== activeSlideIndex && newIndex > 0) {\n          hasSwipedGallery = true;\n        }\n        activeSlideIndex = newIndex;\n\n        var slides = track.querySelectorAll(\".polaroid-slide\");\n        slides.forEach(function (slide, idx) {\n          if (idx === activeSlideIndex) {\n            slide.classList.add(\"is-active\");\n          } else {\n            slide.classList.remove(\"is-active\");\n          }\n        });\n\n        var dots = dotsContainer.querySelectorAll(\".dot-btn\");\n        dots.forEach(function (dot, idx) {\n          if (idx === activeSlideIndex) {\n            dot.classList.add(\"active\");\n          } else {\n            dot.classList.remove(\"active\");\n          }\n        });\n\n        if (keepGoingBtn && (hasSwipedGallery || activeSlideIndex > 0)) {\n          keepGoingBtn.classList.add(\"unlocked\");\n        }\n      }\n\n      function handleCarouselScroll() {\n        if (scrollTicking) return;\n        scrollTicking = true;\n\n        requestAnimationFrame(function () {\n          scrollTicking = false;\n          var track = document.getElementById(\"polaroid-track\");\n          if (!track) return;\n\n          var trackCenter = track.scrollLeft + track.clientWidth / 2;\n          var slides = track.querySelectorAll(\".polaroid-slide\");\n          var closestIdx = 0;\n          var minDist = Infinity;\n\n          slides.forEach(function (slide, idx) {\n            var slideCenter = slide.offsetLeft + slide.offsetWidth / 2;\n            var dist = Math.abs(trackCenter - slideCenter);\n            if (dist < minDist) {\n              minDist = dist;\n              closestIdx = idx;\n            }\n          });\n\n          updateActiveCarouselUI(closestIdx);\n        });\n      }\n\n      function enableDesktopDragScroll(track) {\n        if (!track) return;\n        var isDown = false;\n        var startX = 0;\n        var scrollStart = 0;\n\n        track.addEventListener(\"mousedown\", function (e) {\n          isDown = true;\n          track.classList.add(\"is-dragging\");\n          startX = e.pageX - track.offsetLeft;\n          scrollStart = track.scrollLeft;\n        });\n\n        window.addEventListener(\"mouseup\", function () {\n          if (!isDown) return;\n          isDown = false;\n          track.classList.remove(\"is-dragging\");\n        });\n\n        track.addEventListener(\"mousemove\", function (e) {\n          if (!isDown) return;\n          e.preventDefault();\n          var x = e.pageX - track.offsetLeft;\n          var walk = (x - startX) * 1.3;\n          track.scrollLeft = scrollStart - walk;\n        });\n      }\n\n      function handlePhonePhotos(event) {\n        var files = Array.prototype.slice.call(event.target.files || [], 0, 8);\n        if (!files.length) return;\n\n        files.forEach(function (file, idx) {\n          var objectUrl = URL.createObjectURL(file);\n          GALLERY_PHOTOS[idx].src = objectUrl;\n        });\n\n        renderPolaroidGallery();\n      }\n\n      /* ==========================================================================\n         4. TWO-PAGE STEP NAVIGATION, ENVELOPE OPEN & TYPEWRITER FLOW\n         ========================================================================== */\n      var isOpened = false;\n      var isTyping = false;\n      var typeTimer = null;\n\n      function resetEnvelope() {\n        if (typeTimer) {\n          clearTimeout(typeTimer);\n          typeTimer = null;\n        }\n        isTyping = false;\n        isOpened = false;\n\n        var envBox = document.getElementById(\"envelope-box\");\n        var envStage = document.getElementById(\"envelope-stage\");\n        var openedContent = document.getElementById(\"opened-content\");\n        var container = document.getElementById(\"letter-paragraphs\");\n\n        if (openedContent) {\n          openedContent.classList.remove(\"visible\");\n          openedContent.style.display = \"none\";\n        }\n        if (container) container.innerHTML = \"\";\n\n        if (envBox) envBox.classList.remove(\"is-open\");\n        if (envStage) {\n          envStage.style.display = \"flex\";\n          requestAnimationFrame(function () {\n            envStage.style.opacity = \"1\";\n            envStage.style.transform = \"translateY(0) scale(1)\";\n          });\n        }\n      }\n\n      function goToPage1() {\n        resetEnvelope();\n        var page1 = document.getElementById(\"gallery-section\");\n        var page2 = document.getElementById(\"page-2-wrapper\");\n\n        if (page2) page2.style.display = \"none\";\n        if (page1) {\n          page1.style.display = \"flex\";\n          page1.style.opacity = \"0\";\n          page1.style.transform = \"translateY(10px)\";\n          requestAnimationFrame(function () {\n            page1.style.opacity = \"1\";\n            page1.style.transform = \"translateY(0)\";\n          });\n        }\n        window.scrollTo({ top: 0, behavior: \"smooth\" });\n      }\n\n      function goToPage2() {\n        initAudio();\n        var page1 = document.getElementById(\"gallery-section\");\n        var page2 = document.getElementById(\"page-2-wrapper\");\n\n        if (page1) page1.style.display = \"none\";\n        if (page2) {\n          page2.style.display = \"flex\";\n          page2.style.opacity = \"0\";\n          page2.style.transform = \"translateY(12px)\";\n          page2.style.transition = \"opacity 0.35s ease, transform 0.35s ease\";\n          requestAnimationFrame(function () {\n            page2.style.opacity = \"1\";\n            page2.style.transform = \"translateY(0)\";\n          });\n        }\n        window.scrollTo({ top: 0, behavior: \"smooth\" });\n      }\n\n      function goToPage2() {\n        initAudio();\n        var page1 = document.getElementById(\"gallery-section\");\n        var page2 = document.getElementById(\"page-2-wrapper\");\n        var indicator = document.getElementById(\"top-step-indicator\");\n\n        if (page1) page1.style.display = \"none\";\n        if (page2) {\n          page2.style.display = \"flex\";\n          page2.style.opacity = \"0\";\n          page2.style.transform = \"translateY(12px)\";\n          page2.style.transition = \"opacity 0.35s ease, transform 0.35s ease\";\n          requestAnimationFrame(function () {\n            page2.style.opacity = \"1\";\n            page2.style.transform = \"translateY(0)\";\n          });\n        }\n        if (indicator) indicator.textContent = \"Page 2 of 2 • Letter\";\n        window.scrollTo({ top: 0, behavior: \"smooth\" });\n      }\n\n      function startTypewriter() {\n        if (typeTimer) clearTimeout(typeTimer);\n        var container = document.getElementById(\"letter-paragraphs\");\n        var readFullBtn = document.getElementById(\"read-full-btn\");\n        if (!container) return;\n\n        container.innerHTML = \"\";\n        isTyping = true;\n        if (readFullBtn) readFullBtn.style.display = \"inline-flex\";\n\n        var pIndex = 0;\n        var cIndex = 0;\n\n        var cursor = document.createElement(\"span\");\n        cursor.className = \"typing-cursor\";\n\n        var currentP = document.createElement(\"p\");\n        if (LETTER_LINES[0].cls) currentP.className = LETTER_LINES[0].cls;\n        container.appendChild(currentP);\n        currentP.appendChild(cursor);\n\n        function step() {\n          if (!isTyping) return;\n\n          if (pIndex >= LETTER_LINES.length) {\n            isTyping = false;\n            cursor.remove();\n            if (readFullBtn) readFullBtn.style.display = \"none\";\n            return;\n          }\n\n          var chars = Array.from(LETTER_LINES[pIndex].text);\n          if (cIndex < chars.length) {\n            var ch = chars[cIndex];\n            cursor.insertAdjacentText(\"beforebegin\", ch);\n            cIndex++;\n            if (ch.trim() !== \"\" && cIndex % 2 === 0) playTick();\n\n            var delay = 28;\n            if (ch === \".\" || ch === \"!\" || ch === \"?\") delay = 180;\n            else if (ch === \",\") delay = 95;\n\n            typeTimer = setTimeout(step, delay);\n          } else {\n            pIndex++;\n            cIndex = 0;\n            if (pIndex < LETTER_LINES.length) {\n              currentP = document.createElement(\"p\");\n              if (LETTER_LINES[pIndex].cls) currentP.className = LETTER_LINES[pIndex].cls;\n              container.appendChild(currentP);\n              currentP.appendChild(cursor);\n              typeTimer = setTimeout(step, 220);\n            } else {\n              isTyping = false;\n              cursor.remove();\n              if (readFullBtn) readFullBtn.style.display = \"none\";\n            }\n          }\n        }\n\n        typeTimer = setTimeout(step, 240);\n      }\n\n      function finishTypingNow() {\n        if (typeTimer) {\n          clearTimeout(typeTimer);\n          typeTimer = null;\n        }\n        isTyping = false;\n        var readFullBtn = document.getElementById(\"read-full-btn\");\n        if (readFullBtn) readFullBtn.style.display = \"none\";\n\n        var container = document.getElementById(\"letter-paragraphs\");\n        if (!container) return;\n        container.innerHTML = \"\";\n        LETTER_LINES.forEach(function (line) {\n          var p = document.createElement(\"p\");\n          if (line.cls) p.className = line.cls;\n          p.textContent = line.text;\n          container.appendChild(p);\n        });\n      }\n\n      function openEnvelope() {\n        if (isOpened) return;\n        isOpened = true;\n\n        playChime();\n\n        var envBox = document.getElementById(\"envelope-box\");\n        var envStage = document.getElementById(\"envelope-stage\");\n        var openedContent = document.getElementById(\"opened-content\");\n\n        if (envBox) {\n          var rect = envBox.getBoundingClientRect();\n          burstConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2, 65);\n          envBox.classList.add(\"is-open\");\n        }\n\n        setTimeout(function () {\n          if (envStage) {\n            envStage.style.opacity = \"0\";\n            envStage.style.transform = \"translateY(-14px) scale(0.96)\";\n          }\n\n          setTimeout(function () {\n            if (envStage) envStage.style.display = \"none\";\n            if (openedContent) {\n              openedContent.style.display = \"flex\";\n              requestAnimationFrame(function () {\n                openedContent.classList.add(\"visible\");\n              });\n            }\n            startTypewriter();\n          }, 380);\n        }, 680);\n      }\n\n      function triggerCelebration(e) {\n        playChime();\n        var btn = e && e.currentTarget;\n        if (btn) {\n          var r = btn.getBoundingClientRect();\n          burstConfetti(r.left + r.width * 0.25, r.top, 45);\n          burstConfetti(r.left + r.width * 0.75, r.top, 45);\n        } else {\n          burstConfetti(window.innerWidth / 2, window.innerHeight / 2, 70);\n        }\n      }\n\n      /* ==========================================================================\n         5. BACKGROUND BOKEH & CONFETTI ANIMATION LOOP\n         ========================================================================== */\n      var bgCanvas = document.getElementById(\"bg-canvas\");\n      var bgCtx = bgCanvas ? bgCanvas.getContext(\"2d\") : null;\n      var fxCanvas = document.getElementById(\"fx-canvas\");\n      var fxCtx = fxCanvas ? fxCanvas.getContext(\"2d\") : null;\n\n      var bokehDots = [];\n      var confettiPieces = [];\n      var CONFETTI_COLORS = [\"#ffd56b\", \"#ff9eb5\", \"#56d4f5\", \"#b3a1ff\", \"#ff9c59\", \"#ffffff\"];\n\n      function resizeCanvases() {\n        var dpr = Math.min(window.devicePixelRatio || 1, 2);\n        if (bgCanvas && bgCtx) {\n          bgCanvas.width = window.innerWidth * dpr;\n          bgCanvas.height = window.innerHeight * dpr;\n          bgCtx.setTransform(dpr, 0, 0, dpr, 0, 0);\n        }\n        if (fxCanvas && fxCtx) {\n          fxCanvas.width = window.innerWidth * dpr;\n          fxCanvas.height = window.innerHeight * dpr;\n          fxCtx.setTransform(dpr, 0, 0, dpr, 0, 0);\n        }\n      }\n\n      function initBokeh() {\n        bokehDots = [];\n        for (var i = 0; i < 34; i++) {\n          bokehDots.push({\n            x: Math.random() * window.innerWidth,\n            y: Math.random() * window.innerHeight,\n            r: Math.random() * 2.2 + 0.8,\n            vx: (Math.random() - 0.5) * 0.16,\n            vy: -(Math.random() * 0.22 + 0.06),\n            alpha: Math.random() * 0.45 + 0.12,\n            phase: Math.random() * Math.PI * 2,\n            speed: Math.random() * 0.02 + 0.008\n          });\n        }\n      }\n\n      function burstConfetti(x, y, count) {\n        for (var i = 0; i < count; i++) {\n          var angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.4;\n          var speed = Math.random() * 6 + 2.2;\n          confettiPieces.push({\n            x: x,\n            y: y,\n            vx: Math.cos(angle) * speed,\n            vy: Math.sin(angle) * speed - 2.4,\n            size: Math.random() * 5.5 + 3.5,\n            color: CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)],\n            rot: Math.random() * 360,\n            vRot: (Math.random() - 0.5) * 14,\n            drag: 0.965,\n            gravity: 0.15,\n            alpha: 1,\n            decay: Math.random() * 0.011 + 0.008\n          });\n        }\n      }\n\n      function animateCanvases() {\n        if (bgCtx) {\n          bgCtx.clearRect(0, 0, window.innerWidth, window.innerHeight);\n          for (var i = 0; i < bokehDots.length; i++) {\n            var p = bokehDots[i];\n            p.x += p.vx;\n            p.y += p.vy;\n            p.phase += p.speed;\n            if (p.y < -10) {\n              p.y = window.innerHeight + 10;\n              p.x = Math.random() * window.innerWidth;\n            }\n            var a = p.alpha * (0.6 + 0.4 * Math.sin(p.phase));\n            bgCtx.beginPath();\n            bgCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);\n            bgCtx.fillStyle = \"rgba(255, 224, 185, \" + a.toFixed(3) + \")\";\n            bgCtx.fill();\n          }\n        }\n\n        if (fxCtx) {\n          fxCtx.clearRect(0, 0, window.innerWidth, window.innerHeight);\n          for (var j = confettiPieces.length - 1; j >= 0; j--) {\n            var c = confettiPieces[j];\n            c.vx *= c.drag;\n            c.vy = c.vy * c.drag + c.gravity;\n            c.x += c.vx;\n            c.y += c.vy;\n            c.rot += c.vRot;\n            c.alpha -= c.decay;\n\n            if (c.alpha <= 0 || c.y > window.innerHeight + 30) {\n              confettiPieces.splice(j, 1);\n              continue;\n            }\n\n            fxCtx.save();\n            fxCtx.globalAlpha = Math.max(0, c.alpha);\n            fxCtx.translate(c.x, c.y);\n            fxCtx.rotate((c.rot * Math.PI) / 180);\n            fxCtx.fillStyle = c.color;\n            fxCtx.fillRect(-c.size / 2, -c.size / 2, c.size, c.size * 0.65);\n            fxCtx.restore();\n          }\n        }\n\n        requestAnimationFrame(animateCanvases);\n      }\n\n      /* ==========================================================================\n         6. BIND ALL EVENT LISTENERS & INITIALIZE RELIABLY\n         ========================================================================== */\n      function initApp() {\n        resizeCanvases();\n        initBokeh();\n        renderPolaroidGallery();\n        animateCanvases();\n\n        var polaroidTrack = document.getElementById(\"polaroid-track\");\n        if (polaroidTrack) {\n          polaroidTrack.addEventListener(\"scroll\", handleCarouselScroll, { passive: true });\n          enableDesktopDragScroll(polaroidTrack);\n        }\n\n        var replayBtn = document.getElementById(\"replay-btn\");\n        if (replayBtn) {\n          replayBtn.addEventListener(\"click\", function () {\n            hasSwipedGallery = false;\n            var keepGoingBtn = document.getElementById(\"keep-going-btn\");\n            if (keepGoingBtn) keepGoingBtn.classList.remove(\"unlocked\");\n            goToPage1();\n            scrollToSlide(0);\n          });\n        }\n\n        var soundToggleBtn = document.getElementById(\"sound-toggle-btn\");\n        if (soundToggleBtn) soundToggleBtn.addEventListener(\"click\", toggleSound);\n\n        var uploadBtn = document.getElementById(\"upload-photos-btn\");\n        var photoInput = document.getElementById(\"phone-photo-input\");\n        if (uploadBtn && photoInput) {\n          uploadBtn.addEventListener(\"click\", function () {\n            photoInput.click();\n          });\n          photoInput.addEventListener(\"change\", handlePhonePhotos);\n        }\n\n        var keepGoingBtn = document.getElementById(\"keep-going-btn\");\n        if (keepGoingBtn) keepGoingBtn.addEventListener(\"click\", goToPage2);\n\n        var backEnvBtn = document.getElementById(\"back-to-photos-env-btn\");\n        if (backEnvBtn) backEnvBtn.addEventListener(\"click\", goToPage1);\n\n        var backLetterBtn = document.getElementById(\"back-to-photos-letter-btn\");\n        if (backLetterBtn) backLetterBtn.addEventListener(\"click\", goToPage1);\n\n        var envBox = document.getElementById(\"envelope-box\");\n        if (envBox) {\n          envBox.addEventListener(\"click\", openEnvelope);\n          envBox.addEventListener(\"keydown\", function (e) {\n            if (e.key === \"Enter\" || e.key === \" \") {\n              e.preventDefault();\n              openEnvelope();\n            }\n          });\n        }\n\n        var waxSeal = document.getElementById(\"wax-seal-btn\");\n        if (waxSeal) {\n          waxSeal.addEventListener(\"click\", function (e) {\n            e.stopPropagation();\n            openEnvelope();\n          });\n        }\n\n        var tapPrompt = document.getElementById(\"tap-prompt-btn\");\n        if (tapPrompt) tapPrompt.addEventListener(\"click\", openEnvelope);\n\n        var readFullBtn = document.getElementById(\"read-full-btn\");\n        if (readFullBtn) readFullBtn.addEventListener(\"click\", finishTypingNow);\n\n        var celebrateBtn = document.getElementById(\"celebrate-btn\");\n        if (celebrateBtn) celebrateBtn.addEventListener(\"click\", triggerCelebration);\n\n        var closeLetterBtn = document.getElementById(\"close-letter-btn\");\n        if (closeLetterBtn) closeLetterBtn.addEventListener(\"click\", resetEnvelope);\n\n        window.addEventListener(\"resize\", resizeCanvases);\n      }\n\n      if (document.readyState === \"loading\") {\n        document.addEventListener(\"DOMContentLoaded\", initApp);\n      } else {\n        initApp();\n      }\n    })();\n  </script>\n<script>\n      const celebrateForNext = document.getElementById(\"celebrate-btn\");\n      if (celebrateForNext) {\n        celebrateForNext.addEventListener(\"click\", () => {\n          setTimeout(() => parent.postMessage({type:\"birthday-next\"}, \"*\"), 1800);\n        });\n      }\n    </script>\n</body>\n</html>", "<!-- \n  SETUP INSTRUCTIONS:\n  1. Create a folder named \"video song\".\n  2. Put your video inside it as \"video.mp4\".\n  3. Keep this HTML file in the parent folder.\n-->\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Happy Birthday Shivani!</title>\n\n<script src=\"https://cdn.tailwindcss.com\"></script>\n\n<link href=\"https://fonts.googleapis.com/css2?family=Caveat:wght@600;700&family=Fredoka:wght@600;700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n<style>\n* {\n    box-sizing: border-box;\n    user-select: none;\n    -webkit-tap-highlight-color: transparent;\n}\n\nhtml, body {\n    margin: 0;\n    padding: 0;\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    font-family: 'Inter', sans-serif;\n    background: radial-gradient(circle at 50% 25%, #2a1838 0%, #140b1d 60%, #09040e 100%);\n}\n\n/* BACKGROUND STARS */\n\n.star-particle {\n    position: absolute;\n    border-radius: 50%;\n    background: rgba(255,255,255,.45);\n    pointer-events: none;\n    animation: floatStar linear infinite;\n}\n\n@keyframes floatStar {\n    0% {\n        transform: translateY(0) scale(.8);\n        opacity: 0;\n    }\n    20% { opacity: .75; }\n    80% { opacity: .6; }\n    100% {\n        transform: translateY(-110vh) scale(1.2);\n        opacity: 0;\n    }\n}\n\n/* BUNTING */\n\n.bunting-header {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    z-index: 30;\n    pointer-events: none;\n    filter: drop-shadow(0 4px 8px rgba(0,0,0,.45));\n}\n\n/* STAGE */\n\n#stage-container {\n    position: fixed;\n    inset: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 20;\n    pointer-events: none;\n}\n\n#floating-assembly {\n    position: relative;\n    width: min(86vw, 370px);\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    transform: translateY(135vh) scale(.84);\n    transition: transform 2.3s cubic-bezier(.22,1,.36,1);\n    pointer-events: auto;\n}\n\n#floating-assembly.state-center {\n    transform: translateY(3vh) scale(.9);\n}\n\n#floating-assembly.state-playing {\n    transition: transform 1.2s cubic-bezier(.34,1.56,.64,1);\n    transform: translateY(3vh) scale(1.06);\n}\n\n#floating-assembly.state-exit {\n    transition: transform 2.5s cubic-bezier(.45,0,.55,1);\n    transform: translateY(-145vh) scale(.76);\n}\n\n/* BALLOONS */\n\n.balloon-rig {\n    position: relative;\n    width: 100%;\n    height: 155px;\n    margin-bottom: -8px;\n    z-index: 25;\n    pointer-events: none;\n}\n\n/* VIDEO CARD */\n\n.video-card {\n    position: relative;\n    width: 100%;\n    aspect-ratio: 9 / 14.5;\n    border-radius: 26px;\n    border: 3.5px solid rgba(255,236,195,.9);\n    box-shadow:\n        0 28px 65px rgba(0,0,0,.78),\n        0 0 35px rgba(255,190,90,.22);\n    background: #110c16;\n    overflow: hidden;\n    z-index: 20;\n}\n\n.tie-ring {\n    position: absolute;\n    top: -5px;\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    border: 2px solid #ffecc3;\n    background: #2a1838;\n    z-index: 26;\n    box-shadow: 0 2px 4px rgba(0,0,0,.5);\n}\n\nvideo {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n    background: #000;\n}\n\n/* =====================================\n   BIRTHDAY FINALE SCREEN\n===================================== */\n\n#finale-screen {\n    background:\n        radial-gradient(\n            ellipse at 50% 42%,\n            rgba(91,48,112,.62) 0%,\n            rgba(48,24,61,.48) 42%,\n            transparent 72%\n        ),\n        radial-gradient(\n            ellipse at 78% 82%,\n            rgba(112,48,55,.34) 0%,\n            transparent 48%\n        ),\n        linear-gradient(\n            145deg,\n            #170d20 0%,\n            #24122f 48%,\n            #351a2c 100%\n        );\n    overflow: hidden;\n}\n\n.finale-content {\n    width: 100%;\n    min-height: 100%;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: flex-start;\n    padding: clamp(105px, 19vh, 175px) 18px 30px;\n    position: relative;\n    z-index: 2;\n}\n\n/* WHITE HAPPY BIRTHDAY */\n\n.finale-title {\n    font-family: 'Inter', sans-serif;\n    font-weight: 700;\n    font-size: clamp(2.5rem, 8.2vw, 4.5rem);\n    line-height: 1.12;\n    letter-spacing: .015em;\n    color: #fff0e9;\n    text-align: center;\n    text-shadow: 0 4px 22px rgba(0,0,0,.38);\n    animation: titleReveal 1.1s cubic-bezier(.2,.8,.2,1) both;\n}\n\n/* ORANGE HANDWRITTEN NAME */\n\n.finale-name {\n    margin-top: 14px;\n    font-family: 'Caveat', cursive;\n    font-weight: 700;\n    font-size: clamp(3.2rem, 10vw, 5rem);\n    line-height: 1;\n    color: #f5a018;\n    text-shadow: 0 3px 18px rgba(245,160,24,.22);\n    animation: nameReveal 1.2s .25s ease both;\n}\n\n/* CAT */\n\n.finale-cat {\n    width: clamp(175px, 48vw, 245px);\n    margin-top: 22px;\n    animation:\n        catReveal 1.35s .45s cubic-bezier(.2,.8,.2,1) both,\n        kittyBob 3.2s 1.8s ease-in-out infinite;\n    filter: drop-shadow(0 14px 24px rgba(0,0,0,.35));\n}\n\n/* FINALE ANIMATIONS */\n\n@keyframes titleReveal {\n    from {\n        opacity: 0;\n        transform: translateY(22px);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n@keyframes nameReveal {\n    from {\n        opacity: 0;\n        transform: translateY(18px) scale(.94);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0) scale(1);\n    }\n}\n\n@keyframes catReveal {\n    from {\n        opacity: 0;\n        transform: translateY(28px) scale(.82);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0) scale(1);\n    }\n}\n\n@keyframes kittyBob {\n    0%, 100% {\n        translate: 0 0;\n        rotate: -1deg;\n    }\n    50% {\n        translate: 0 -8px;\n        rotate: 1deg;\n    }\n}\n\n/* CONFETTI */\n\n#confetti-canvas {\n    position: fixed;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n    z-index: 35;\n}\n</style>\n</head>\n\n<body>\n\n<!-- BACKGROUND STARS -->\n\n<div id=\"stars-layer\" class=\"fixed inset-0 pointer-events-none z-0\"></div>\n\n<!-- TOP BUNTING -->\n\n<div class=\"bunting-header\">\n<svg viewBox=\"0 0 1200 100\" preserveAspectRatio=\"none\" class=\"w-full h-12 sm:h-16\">\n\n<path d=\"M-10,5 Q600,42 1210,5\"\nfill=\"none\"\nstroke=\"rgba(255,255,255,0.4)\"\nstroke-width=\"2.5\"/>\n\n<polygon points=\"20,9 85,15 48,68\" fill=\"#e55959\"/>\n<polygon points=\"100,16 165,21 128,76\" fill=\"#54b6d8\"/>\n<polygon points=\"180,22 245,26 208,82\" fill=\"#f7c852\"/>\n<polygon points=\"260,27 325,30 288,87\" fill=\"#e65c7b\"/>\n<polygon points=\"340,31 405,33 368,90\" fill=\"#a288e3\"/>\n<polygon points=\"420,34 485,35 450,92\" fill=\"#68c9a8\"/>\n<polygon points=\"500,35 565,36 532,94\" fill=\"#f49f45\"/>\n<polygon points=\"580,36 645,35 612,94\" fill=\"#e55959\"/>\n<polygon points=\"660,35 725,34 692,92\" fill=\"#54b6d8\"/>\n<polygon points=\"740,33 805,31 772,90\" fill=\"#f7c852\"/>\n<polygon points=\"820,30 885,27 852,87\" fill=\"#e65c7b\"/>\n<polygon points=\"900,26 965,22 932,82\" fill=\"#a288e3\"/>\n<polygon points=\"980,21 1045,16 1012,76\" fill=\"#68c9a8\"/>\n<polygon points=\"1060,15 1125,9 1092,68\" fill=\"#f49f45\"/>\n<polygon points=\"1135,8 1195,3 1165,60\" fill=\"#e55959\"/>\n\n</svg>\n</div>\n\n<canvas id=\"confetti-canvas\"></canvas>\n\n<!-- =====================================\n     FINALE SCREEN - SHIVANI\n===================================== -->\n\n<div id=\"finale-screen\"\nclass=\"fixed inset-0 z-40 hidden opacity-0 flex-col items-center justify-center text-center transition-opacity duration-700\">\n\n<div class=\"finale-content\">\n\n<h1 class=\"finale-title\">\nHAPPY<br>BIRTHDAY\n</h1>\n\n<h2 class=\"finale-name\">\nSHIVANI!\n</h2>\n\n<!-- CAT WITH RED CAP AND PINK FLOWERS -->\n\n<svg class=\"finale-cat\"\nviewBox=\"0 0 260 245\"\nrole=\"img\"\naria-label=\"Cute cat wearing a red cap and holding pink flowers\">\n\n<defs>\n\n<linearGradient id=\"catFur\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n<stop offset=\"0\" stop-color=\"#f8f5ed\"/>\n<stop offset=\".55\" stop-color=\"#c9c8c2\"/>\n<stop offset=\"1\" stop-color=\"#777b7b\"/>\n</linearGradient>\n\n<linearGradient id=\"capRed\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n<stop offset=\"0\" stop-color=\"#ed3b35\"/>\n<stop offset=\"1\" stop-color=\"#991d24\"/>\n</linearGradient>\n\n<linearGradient id=\"flowerPink\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n<stop offset=\"0\" stop-color=\"#ffd0c9\"/>\n<stop offset=\"1\" stop-color=\"#e77c83\"/>\n</linearGradient>\n\n</defs>\n\n<!-- FLOATING FLOWER -->\n\n<g transform=\"translate(206 111) scale(.55)\">\n\n<g fill=\"#ffb7c5\">\n<ellipse cx=\"0\" cy=\"-10\" rx=\"7\" ry=\"12\"/>\n<ellipse cx=\"10\" cy=\"0\" rx=\"7\" ry=\"12\" transform=\"rotate(90 10 0)\"/>\n<ellipse cx=\"0\" cy=\"10\" rx=\"7\" ry=\"12\"/>\n<ellipse cx=\"-10\" cy=\"0\" rx=\"7\" ry=\"12\" transform=\"rotate(90 -10 0)\"/>\n</g>\n\n<circle r=\"5\" fill=\"#f5d36d\"/>\n\n</g>\n\n<!-- CAT EARS -->\n\n<path d=\"M65 104 L58 48 Q58 39 68 47 L105 78 Z\"\nfill=\"#aeb1ad\" stroke=\"#747977\" stroke-width=\"3\"/>\n\n<path d=\"M75 83 L68 59 L91 80 Z\"\nfill=\"#e9a2a8\"/>\n\n<path d=\"M163 78 L199 45 Q208 39 207 52 L198 111 Z\"\nfill=\"#9da29e\" stroke=\"#747977\" stroke-width=\"3\"/>\n\n<path d=\"M179 80 L198 58 L193 91 Z\"\nfill=\"#e9a2a8\"/>\n\n<!-- BODY -->\n\n<ellipse cx=\"132\" cy=\"183\" rx=\"58\" ry=\"45\" fill=\"url(#catFur)\"/>\n\n<ellipse cx=\"132\" cy=\"190\" rx=\"28\" ry=\"30\" fill=\"#f2eee7\"/>\n\n<path d=\"M170 190 Q218 178 213 209 Q207 225 187 213\"\nfill=\"none\"\nstroke=\"#d9d5cd\"\nstroke-width=\"12\"\nstroke-linecap=\"round\"/>\n\n<!-- HEAD -->\n\n<ellipse cx=\"132\" cy=\"119\" rx=\"76\" ry=\"67\"\nfill=\"url(#catFur)\"\nstroke=\"#858985\"\nstroke-width=\"2\"/>\n\n<path d=\"M66 114 Q77 73 119 65 Q149 59 180 86 Q155 81 139 94 Q113 81 91 112 Z\"\nfill=\"#777c7a\"\nopacity=\".9\"/>\n\n<path d=\"M151 72 Q178 82 195 112 Q176 101 162 107 Z\"\nfill=\"#858a86\"\nopacity=\".9\"/>\n\n<!-- EYES -->\n\n<ellipse cx=\"101\" cy=\"126\" rx=\"16\" ry=\"22\" fill=\"#252a29\"/>\n<ellipse cx=\"164\" cy=\"126\" rx=\"16\" ry=\"22\" fill=\"#252a29\"/>\n\n<ellipse cx=\"96\" cy=\"118\" rx=\"5\" ry=\"7\" fill=\"#fff\"/>\n<ellipse cx=\"159\" cy=\"118\" rx=\"5\" ry=\"7\" fill=\"#fff\"/>\n\n<ellipse cx=\"106\" cy=\"137\" rx=\"3\" ry=\"4\" fill=\"#fff\" opacity=\".8\"/>\n<ellipse cx=\"169\" cy=\"137\" rx=\"3\" ry=\"4\" fill=\"#fff\" opacity=\".8\"/>\n\n<!-- MUZZLE -->\n\n<ellipse cx=\"132\" cy=\"151\" rx=\"30\" ry=\"20\" fill=\"#f1e9e3\"/>\n\n<path d=\"M124 143 Q132 137 140 143 Q136 151 132 151 Q128 151 124 143\"\nfill=\"#e98f9b\"/>\n\n<path d=\"M132 151 Q126 162 117 157 M132 151 Q138 162 147 157\"\nfill=\"none\"\nstroke=\"#55514f\"\nstroke-width=\"2.5\"\nstroke-linecap=\"round\"/>\n\n<path d=\"M80 151 Q91 147 100 153 M164 153 Q174 147 184 151\"\nstroke=\"#f2a6ad\"\nstroke-width=\"7\"\nopacity=\".55\"\nstroke-linecap=\"round\"/>\n\n<!-- RED BASEBALL CAP -->\n\n<path d=\"M75 73 Q81 25 133 20 Q184 20 193 72 Q151 87 103 79 Z\"\nfill=\"url(#capRed)\"\nstroke=\"#8f1d22\"\nstroke-width=\"3\"/>\n\n<path d=\"M78 69 Q122 77 177 67 Q202 66 211 81 Q174 100 119 88 Q94 84 78 69\"\nfill=\"#b9272d\"\nstroke=\"#8f1d22\"\nstroke-width=\"3\"/>\n\n<text x=\"132\" y=\"63\"\ntext-anchor=\"middle\"\nfont-family=\"Arial,sans-serif\"\nfont-size=\"27\"\nfont-weight=\"bold\"\nfill=\"#fff\">LA</text>\n\n<!-- FLOWER STEMS -->\n\n<g fill=\"none\" stroke=\"#66864d\" stroke-width=\"4\" stroke-linecap=\"round\">\n\n<path d=\"M67 207 Q57 164 48 118\"/>\n<path d=\"M75 209 Q74 164 74 112\"/>\n<path d=\"M82 210 Q94 163 100 124\"/>\n<path d=\"M70 183 Q52 177 48 163\"/>\n<path d=\"M78 177 Q94 170 98 156\"/>\n\n</g>\n\n<g fill=\"#71965b\">\n<path d=\"M60 183 Q40 171 43 160 Q61 164 65 179Z\"/>\n<path d=\"M81 180 Q98 164 105 169 Q99 186 81 187Z\"/>\n</g>\n\n<!-- PINK FLOWERS -->\n\n<g fill=\"url(#flowerPink)\" stroke=\"#dc8b91\" stroke-width=\"1.5\">\n\n<path d=\"M35 119 Q25 105 34 91 Q38 104 43 91 Q52 104 45 120 Q40 126 35 119Z\"/>\n\n<path d=\"M61 112 Q51 96 62 81 Q65 96 72 82 Q81 99 72 115 Q66 121 61 112Z\"/>\n\n<path d=\"M88 124 Q78 109 89 94 Q93 108 99 95 Q109 112 99 127 Q93 132 88 124Z\"/>\n\n<path d=\"M49 133 Q39 120 49 107 Q53 120 59 108 Q68 123 59 137 Q54 141 49 133Z\"/>\n\n</g>\n\n<g fill=\"#ffe2d8\" opacity=\".8\">\n<ellipse cx=\"36\" cy=\"100\" rx=\"3\" ry=\"7\"/>\n<ellipse cx=\"64\" cy=\"91\" rx=\"3\" ry=\"7\"/>\n<ellipse cx=\"91\" cy=\"104\" rx=\"3\" ry=\"7\"/>\n</g>\n\n</svg>\n\n</div>\n</div>\n\n<!-- =====================================\n     MAIN FLOATING VIDEO STAGE\n===================================== -->\n\n<div id=\"stage-container\">\n\n<div id=\"floating-assembly\">\n\n<!-- THREE BALLOONS -->\n\n<div class=\"balloon-rig\">\n\n<svg id=\"balloons-svg\"\nviewBox=\"0 0 360 165\"\nclass=\"w-full h-full overflow-visible\">\n\n<defs>\n\n<radialGradient id=\"grad-pink\" cx=\"32%\" cy=\"28%\" r=\"68%\">\n<stop offset=\"0%\" stop-color=\"#ffc2d4\"/>\n<stop offset=\"35%\" stop-color=\"#ff5c8a\"/>\n<stop offset=\"85%\" stop-color=\"#c9184a\"/>\n<stop offset=\"100%\" stop-color=\"#800f2f\"/>\n</radialGradient>\n\n<radialGradient id=\"grad-gold\" cx=\"32%\" cy=\"28%\" r=\"68%\">\n<stop offset=\"0%\" stop-color=\"#fff3b0\"/>\n<stop offset=\"35%\" stop-color=\"#ffbe0b\"/>\n<stop offset=\"85%\" stop-color=\"#fb8500\"/>\n<stop offset=\"100%\" stop-color=\"#9e4700\"/>\n</radialGradient>\n\n<radialGradient id=\"grad-cyan\" cx=\"32%\" cy=\"28%\" r=\"68%\">\n<stop offset=\"0%\" stop-color=\"#caf0f8\"/>\n<stop offset=\"35%\" stop-color=\"#00b4d8\"/>\n<stop offset=\"85%\" stop-color=\"#0077b6\"/>\n<stop offset=\"100%\" stop-color=\"#03045e\"/>\n</radialGradient>\n\n<filter id=\"balloon-shadow\" x=\"-25%\" y=\"-25%\" width=\"150%\" height=\"150%\">\n<feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"5\"\nflood-color=\"#000000\" flood-opacity=\".45\"/>\n</filter>\n\n</defs>\n\n<!-- STRINGS -->\n\n<path id=\"string-left\"\nd=\"M72 86 Q82 125 96 162\"\nfill=\"none\"\nstroke=\"rgba(255,245,225,.88)\"\nstroke-width=\"1.6\"\nstroke-linecap=\"round\"/>\n\n<path id=\"string-center\"\nd=\"M180 72 Q180 118 180 162\"\nfill=\"none\"\nstroke=\"rgba(255,245,225,.92)\"\nstroke-width=\"1.7\"\nstroke-linecap=\"round\"/>\n\n<path id=\"string-right\"\nd=\"M288 86 Q278 125 264 162\"\nfill=\"none\"\nstroke=\"rgba(255,245,225,.88)\"\nstroke-width=\"1.6\"\nstroke-linecap=\"round\"/>\n\n<!-- LEFT PINK BALLOON -->\n\n<g id=\"balloon-left-group\" filter=\"url(#balloon-shadow)\">\n\n<polygon points=\"68,85 76,85 72,91\" fill=\"#c9184a\"/>\n<rect x=\"69.5\" y=\"84\" width=\"5\" height=\"2\" rx=\"1\" fill=\"#800f2f\"/>\n\n<ellipse cx=\"72\" cy=\"50\" rx=\"31\" ry=\"36\" fill=\"url(#grad-pink)\"/>\n\n<ellipse cx=\"60\" cy=\"36\" rx=\"7\" ry=\"13\"\ntransform=\"rotate(-24 60 36)\"\nfill=\"rgba(255,255,255,.48)\"/>\n\n<circle cx=\"55\" cy=\"52\" r=\"2.5\" fill=\"rgba(255,255,255,.35)\"/>\n\n</g>\n\n<!-- CENTER GOLD BALLOON -->\n\n<g id=\"balloon-center-group\" filter=\"url(#balloon-shadow)\">\n\n<polygon points=\"176,71 184,71 180,77\" fill=\"#fb8500\"/>\n<rect x=\"177.5\" y=\"70\" width=\"5\" height=\"2\" rx=\"1\" fill=\"#9e4700\"/>\n\n<ellipse cx=\"180\" cy=\"35\" rx=\"33\" ry=\"38\" fill=\"url(#grad-gold)\"/>\n\n<ellipse cx=\"167\" cy=\"21\" rx=\"7.5\" ry=\"14\"\ntransform=\"rotate(-24 167 21)\"\nfill=\"rgba(255,255,255,.55)\"/>\n\n<circle cx=\"162\" cy=\"38\" r=\"2.8\" fill=\"rgba(255,255,255,.38)\"/>\n\n</g>\n\n<!-- RIGHT CYAN BALLOON -->\n\n<g id=\"balloon-right-group\" filter=\"url(#balloon-shadow)\">\n\n<polygon points=\"284,85 292,85 288,91\" fill=\"#0077b6\"/>\n<rect x=\"285.5\" y=\"84\" width=\"5\" height=\"2\" rx=\"1\" fill=\"#03045e\"/>\n\n<ellipse cx=\"288\" cy=\"50\" rx=\"31\" ry=\"36\" fill=\"url(#grad-cyan)\"/>\n\n<ellipse cx=\"276\" cy=\"36\" rx=\"7\" ry=\"13\"\ntransform=\"rotate(-24 276 36)\"\nfill=\"rgba(255,255,255,.48)\"/>\n\n<circle cx=\"271\" cy=\"52\" r=\"2.5\" fill=\"rgba(255,255,255,.35)\"/>\n\n</g>\n\n</svg>\n</div>\n\n<!-- VIDEO CARD -->\n\n<div class=\"video-card\" id=\"video-card\">\n\n<div class=\"tie-ring\" style=\"left:calc(26.6% - 5px)\"></div>\n<div class=\"tie-ring\" style=\"left:calc(50% - 5px)\"></div>\n<div class=\"tie-ring\" style=\"left:calc(73.3% - 5px)\"></div>\n\n<video id=\"main-video\" playsinline preload=\"auto\">\n<source src=\"video song/video.mp4\" type=\"video/mp4\">\n<source src=\"video song/birthday.mp4\" type=\"video/mp4\">\n<source src=\"video_song/video.mp4\" type=\"video/mp4\">\n</video>\n\n<!-- VIDEO MISSING NOTICE -->\n\n<div id=\"missing-video-notice\"\nclass=\"hidden absolute inset-0 flex flex-col items-center justify-center p-6 text-center bg-[#180d24]/95 text-purple-100\">\n\n<div class=\"text-4xl mb-3\">📁🎬</div>\n\n<p class=\"font-semibold text-sm sm:text-base text-amber-300 mb-1.5\">\nVideo File Abhi Nahi Mili\n</p>\n\n<p class=\"text-xs text-purple-200/85 leading-relaxed\">\nApne folder mein\n<span class=\"font-mono bg-white/10 px-1.5 py-0.5 rounded text-white\">video song</span>\nnaam ka folder banayein aur usmein apna video\n<span class=\"font-mono bg-white/10 px-1.5 py-0.5 rounded text-white\">video.mp4</span>\nnaam se save karein.\n</p>\n\n</div>\n\n</div>\n</div>\n</div>\n\n<!-- =====================================\n     JAVASCRIPT\n===================================== -->\n\n<script>\n\n/* 1. BACKGROUND STARS */\n\nconst starsLayer = document.getElementById('stars-layer');\n\nfor (let i = 0; i < 42; i++) {\n\n    const star = document.createElement('div');\n\n    star.className = 'star-particle';\n\n    const size = Math.random() * 3.5 + 1.5;\n\n    star.style.width = `${size}px`;\n    star.style.height = `${size}px`;\n\n    star.style.left = `${Math.random() * 100}%`;\n    star.style.top = `${Math.random() * 100 + 15}%`;\n\n    star.style.animationDuration = `${Math.random() * 14 + 10}s`;\n    star.style.animationDelay = `-${Math.random() * 14}s`;\n\n    starsLayer.appendChild(star);\n}\n\n/* 2. DOM REFERENCES */\n\nconst finaleScreen = document.getElementById('finale-screen');\n\nconst floatingAssembly = document.getElementById('floating-assembly');\n\nconst mainVideo = document.getElementById('main-video');\n\nconst missingVideoNotice = document.getElementById('missing-video-notice');\n\nconst balloonLeft = document.getElementById('balloon-left-group');\nconst balloonCenter = document.getElementById('balloon-center-group');\nconst balloonRight = document.getElementById('balloon-right-group');\n\nconst stringLeft = document.getElementById('string-left');\nconst stringCenter = document.getElementById('string-center');\nconst stringRight = document.getElementById('string-right');\n\nlet sequenceTimers = [];\n\nlet flightPhase = 'idle';\n\nlet videoHasError = false;\n\n/* 3. TIMER FUNCTIONS */\n\nfunction clearSequenceTimers() {\n\n    sequenceTimers.forEach(id => clearTimeout(id));\n\n    sequenceTimers = [];\n}\n\nfunction scheduleStep(fn, ms) {\n\n    const id = setTimeout(fn, ms);\n\n    sequenceTimers.push(id);\n\n    return id;\n}\n\n/* 4. BALLOON PHYSICS */\n\nfunction animateBalloonsAndStrings(timestamp) {\n\n    const t = timestamp * 0.0018;\n\n    const tension =\n        (flightPhase === 'rising' || flightPhase === 'exiting')\n        ? 1.45\n        : 1.0;\n\n    // LEFT BALLOON\n\n    const lx = Math.sin(t * 1.15) * 6.5;\n\n    const ly =\n        Math.cos(t * 1.6) * 4.5 -\n        (tension - 1) * 8;\n\n    const lRot = Math.sin(t * 1.15 - 0.4) * 5;\n\n    balloonLeft.setAttribute(\n        'transform',\n        `translate(${lx.toFixed(2)},${ly.toFixed(2)}) rotate(${lRot.toFixed(2)} 72 86)`\n    );\n\n    const lKnotX = 72 + lx;\n    const lKnotY = 88 + ly;\n\n    const lCtrlX =\n        (lKnotX + 96) / 2 -\n        Math.sin(t * 1.4) * (7 / tension);\n\n    const lCtrlY = (lKnotY + 162) / 2;\n\n    stringLeft.setAttribute(\n        'd',\n        `M ${lKnotX.toFixed(1)} ${lKnotY.toFixed(1)} Q ${lCtrlX.toFixed(1)} ${lCtrlY.toFixed(1)} 96 162`\n    );\n\n    // CENTER BALLOON\n\n    const cx = Math.sin(t * .95 + 1.2) * 5.5;\n\n    const cy =\n        Math.sin(t * 1.45 + .5) * 5 -\n        (tension - 1) * 10;\n\n    const cRot = Math.sin(t * .95 + .8) * 4;\n\n    balloonCenter.setAttribute(\n        'transform',\n        `translate(${cx.toFixed(2)},${cy.toFixed(2)}) rotate(${cRot.toFixed(2)} 180 72)`\n    );\n\n    const cKnotX = 180 + cx;\n    const cKnotY = 74 + cy;\n\n    const cCtrlX =\n        (cKnotX + 180) / 2 +\n        Math.cos(t * 1.3) * (6 / tension);\n\n    const cCtrlY = (cKnotY + 162) / 2;\n\n    stringCenter.setAttribute(\n        'd',\n        `M ${cKnotX.toFixed(1)} ${cKnotY.toFixed(1)} Q ${cCtrlX.toFixed(1)} ${cCtrlY.toFixed(1)} 180 162`\n    );\n\n    // RIGHT BALLOON\n\n    const rx = Math.cos(t * 1.1 + .7) * 6.5;\n\n    const ry =\n        Math.sin(t * 1.55 + 1.8) * 4.5 -\n        (tension - 1) * 8;\n\n    const rRot = Math.cos(t * 1.1 + .3) * 5;\n\n    balloonRight.setAttribute(\n        'transform',\n        `translate(${rx.toFixed(2)},${ry.toFixed(2)}) rotate(${rRot.toFixed(2)} 288 86)`\n    );\n\n    const rKnotX = 288 + rx;\n    const rKnotY = 88 + ry;\n\n    const rCtrlX =\n        (rKnotX + 264) / 2 +\n        Math.sin(t * 1.4 + 1) * (7 / tension);\n\n    const rCtrlY = (rKnotY + 162) / 2;\n\n    stringRight.setAttribute(\n        'd',\n        `M ${rKnotX.toFixed(1)} ${rKnotY.toFixed(1)} Q ${rCtrlX.toFixed(1)} ${rCtrlY.toFixed(1)} 264 162`\n    );\n\n    requestAnimationFrame(animateBalloonsAndStrings);\n}\n\nrequestAnimationFrame(animateBalloonsAndStrings);\n\n/* 5. CONFETTI */\n\nconst confettiCanvas = document.getElementById('confetti-canvas');\n\nconst cCtx = confettiCanvas.getContext('2d');\n\nlet confettiList = [];\n\nlet confettiLoopId = null;\n\nfunction resizeConfetti() {\n\n    confettiCanvas.width = window.innerWidth;\n    confettiCanvas.height = window.innerHeight;\n}\n\nwindow.addEventListener('resize', resizeConfetti);\n\nresizeConfetti();\n\nfunction burstConfetti(amount = 85) {\n\n    const palette = [\n        '#ff5c8a',\n        '#ffbe0b',\n        '#00b4d8',\n        '#a288e3',\n        '#68c9a8',\n        '#ffffff'\n    ];\n\n    for (let i = 0; i < amount; i++) {\n\n        confettiList.push({\n\n            x: Math.random() * confettiCanvas.width,\n\n            y: -20 - Math.random() * (confettiCanvas.height * .35),\n\n            w: Math.random() * 8 + 4,\n\n            h: Math.random() * 5 + 3,\n\n            color: palette[Math.floor(Math.random() * palette.length)],\n\n            vx: (Math.random() - .5) * 3,\n\n            vy: Math.random() * 3 + 2,\n\n            rot: Math.random() * 360,\n\n            vRot: (Math.random() - .5) * 7\n\n        });\n    }\n\n    if (!confettiLoopId) {\n        renderConfetti();\n    }\n}\n\nfunction renderConfetti() {\n\n    cCtx.clearRect(\n        0,\n        0,\n        confettiCanvas.width,\n        confettiCanvas.height\n    );\n\n    confettiList.forEach(p => {\n\n        p.x += p.vx;\n        p.y += p.vy;\n        p.rot += p.vRot;\n\n        cCtx.save();\n\n        cCtx.translate(p.x, p.y);\n\n        cCtx.rotate((p.rot * Math.PI) / 180);\n\n        cCtx.fillStyle = p.color;\n\n        cCtx.fillRect(\n            -p.w / 2,\n            -p.h / 2,\n            p.w,\n            p.h\n        );\n\n        cCtx.restore();\n    });\n\n    confettiList = confettiList.filter(\n        p => p.y < confettiCanvas.height + 25\n    );\n\n    if (confettiList.length > 0) {\n\n        confettiLoopId = requestAnimationFrame(renderConfetti);\n\n    } else {\n\n        confettiLoopId = null;\n    }\n}\n\n/* 6. RESET VIDEO ASSEMBLY */\n\nfunction resetAssemblyPosition() {\n\n    clearSequenceTimers();\n\n    mainVideo.pause();\n\n    if (mainVideo.readyState > 0) {\n        mainVideo.currentTime = 0;\n    }\n\n    floatingAssembly.style.transition = 'none';\n\n    floatingAssembly.classList.remove(\n        'state-center',\n        'state-playing',\n        'state-exit'\n    );\n\n    void floatingAssembly.offsetWidth;\n\n    floatingAssembly.style.transition = '';\n}\n\n/* 7. FINALE SCREEN */\n\nfunction triggerFinaleExit() {\n\n    if (flightPhase === 'exiting') return;\n\n    flightPhase = 'exiting';\n\n    floatingAssembly.classList.remove(\n        'state-playing',\n        'state-center'\n    );\n\n    floatingAssembly.classList.add('state-exit');\n\n    burstConfetti(95);\n\n    // After balloons and video card fly away,\n    // show the new Shivani birthday screen.\n\n    scheduleStep(() => {\n\n        flightPhase = 'idle';\n\n        finaleScreen.classList.remove('hidden');\n\n        finaleScreen.classList.add('flex');\n\n        requestAnimationFrame(() => {\n\n            finaleScreen.style.opacity = '1';\n\n        });\n\n    }, 1900);\n}\n\n/* 8. START BALLOON FLIGHT */\n\nfunction startBalloonFlightSequence() {\n\n    resetAssemblyPosition();\n\n    flightPhase = 'rising';\n\n    // Step 1: Balloons lift the video card.\n\n    scheduleStep(() => {\n\n        floatingAssembly.classList.add('state-center');\n\n    }, 60);\n\n    // Step 2: Video starts playing.\n\n    scheduleStep(() => {\n\n        flightPhase = 'playing';\n\n        floatingAssembly.classList.add('state-playing');\n\n        if (\n            videoHasError ||\n            mainVideo.networkState === HTMLMediaElement.NETWORK_NO_SOURCE\n        ) {\n\n            missingVideoNotice.classList.remove('hidden');\n\n            scheduleStep(\n                () => triggerFinaleExit(),\n                4500\n            );\n\n            return;\n        }\n\n        missingVideoNotice.classList.add('hidden');\n\n        mainVideo.muted = false;\n\n        const playPromise = mainVideo.play();\n\n        if (playPromise !== undefined) {\n\n            playPromise.catch(() => {\n\n                mainVideo.muted = true;\n\n                mainVideo.play().catch(() => {\n\n                    missingVideoNotice.classList.remove('hidden');\n\n                });\n\n            });\n        }\n\n    }, 2200);\n}\n\n/* 9. AUDIO UNLOCK */\n\nfunction unlockAudioSilently() {\n\n    if (mainVideo.muted && !mainVideo.paused) {\n\n        mainVideo.muted = false;\n    }\n}\n\nwindow.addEventListener(\n    'pointerdown',\n    unlockAudioSilently,\n    { once: true }\n);\n\nwindow.addEventListener(\n    'keydown',\n    unlockAudioSilently,\n    { once: true }\n);\n\n/* 10. VIDEO FILE ERROR DETECTION */\n\nconst sources = mainVideo.querySelectorAll('source');\n\nlet failedSources = 0;\n\nsources.forEach(srcEl => {\n\n    srcEl.addEventListener('error', () => {\n\n        failedSources++;\n\n        if (failedSources >= sources.length) {\n\n            videoHasError = true;\n\n            missingVideoNotice.classList.remove('hidden');\n        }\n    });\n});\n\nmainVideo.addEventListener('loadeddata', () => {\n\n    videoHasError = false;\n\n    missingVideoNotice.classList.add('hidden');\n});\n\n/* 11. WHEN VIDEO ENDS */\n\nmainVideo.addEventListener('ended', () => {\n\n    triggerFinaleExit();\n\n});\n\n/* 12. AUTO START */\n\nwindow.addEventListener('DOMContentLoaded', () => {\n\n    startBalloonFlightSequence();\n\n});\n\n</script>\n\n<script></script>\n</body>\n</html>\n"];

const pageFrame = document.getElementById("pageFrame");
const backBtn = document.getElementById("backBtn");
const restartBtn = document.getElementById("restartBtn");
const nextBtn = document.getElementById("nextBtn");
const stepCount = document.getElementById("stepCount");

let currentPage = 0;
let canContinue = false;

const pageNames = [
  "Heart Animation",
  "Bow & Arrow Surprise",
  "Blooming Heart Tree",
  "Pop the Balloons",
  "Birthday Cake",
  "Memories & Birthday Letter",
  "Birthday Video Finale"
];

function updateControls() {
  stepCount.textContent = `${currentPage + 1} / 7`;
  backBtn.disabled = currentPage === 0;
  nextBtn.hidden = !canContinue;
  nextBtn.innerHTML = (currentPage === 5 ? "Finish" : "Continue") + " <span>→</span>";
}

function loadPage(index) {
  if (index < 0 || index >= BIRTHDAY_PAGES.length) return;
  currentPage = index;
  canContinue = false;
  nextBtn.hidden = true;
  pageFrame.srcdoc = BIRTHDAY_PAGES[index];
  updateControls();
  document.title = pageNames[index] + " | Happy Birthday Shivani";
}

function showContinue() {
  if (currentPage >= 6) return;
  canContinue = true;
  updateControls();
}

function goNext() {
  if (currentPage >= 6) return;
  loadPage(currentPage + 1);
}

backBtn.addEventListener("click", () => loadPage(currentPage - 1));
restartBtn.addEventListener("click", () => loadPage(0));
nextBtn.addEventListener("click", goNext);

window.addEventListener("message", (event) => {
  if (event.source !== pageFrame.contentWindow) return;
  const data = event.data;
  if (!data || typeof data !== "object") return;
  if (data.type === "birthday-reveal-next") showContinue();
  if (data.type === "birthday-next") goNext();
});

loadPage(0);
